        this.id = id;
        this.name = name;
        this.colorIndex = colorIndex;
        this.isReady = isReady;
    }

    public String getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public int getColorIndex() {
        return colorIndex;
    }

    public boolean isReady() {
        return isReady;
    }

    @Override
    public String toString() {
        return "LobbyMember{" +
                "id='" + id + '\'' +
                ", name='" + name + '\'' +
                ", colorIndex=" + colorIndex +
                ", isReady=" + isReady +
                '}';
    }
}

