                ", isReady=" + isReady +
                '}';
    }
}

/**
 * Enum representing the possible states of a lobby.
 */
enum LobbyStatus {
    ACTIVE,
    IN_GAME,
    CLOSED,
    MAINTENANCE
}

/**
 * Manages a lobby, its members, settings, and status.
 */
class EnhancedLobbyManager {
    private final String lobbyId;
    private String ownerId; // mutable to allow owner change
    private final List<LobbyMember> members;
    private final Map<String, String> settings;
    private LobbyStatus status;

    public EnhancedLobbyManager(JSONObject lobbyJson, String lobbyId) {
        this.lobbyId = lobbyId;
        this.ownerId = lobbyJson.getString("ownerId");
        this.members = new ArrayList<>();
        this.settings = new HashMap<>();
        this.status = LobbyStatus.ACTIVE; // default status

        // Parse initial settings if present
        if (lobbyJson.has("settings") && !lobbyJson.isNull("settings")) {
            JSONObject settingsJson = lobbyJson.getJSONObject("settings");
            Iterator<String> keys = settingsJson.keys();
            while (keys.hasNext()) {
                String key = keys.next();
                String value = settingsJson.optString(key, "");
                settings.put(key, value);
            }
        }
    }

    /**
     * Adds a member to the lobby.
     *
     * @param memberJson JSON object containing member data.
     * @return true if the member was added, false if a member with the same id already exists.
     */
    public boolean addMember(JSONObject memberJson) {
        String id = memberJson.getString("id");
        // Check if member already exists
        for (LobbyMember m : members) {
            if (m.getId().equals(id)) {
                return false;
            }
        }

        String name = memberJson.optString("name", "");
        int colorIndex = memberJson.optInt("colorIndex", 0);
        boolean isReady = memberJson.optBoolean("isReady", false);

        LobbyMember newMember = new LobbyMember(id, name, colorIndex, isReady);
        members.add(newMember);
        return true;
    }

    /**
     * Removes a member from the lobby by ID.
     *
     * @param memberId ID of the member to remove.
     * @return true if the member was found and removed, false otherwise.
     */
    public boolean removeMember(String memberId) {
        for (int i = 0; i < members.size(); i++) {
            if (members.get(i).getId().equals(memberId)) {
                members.remove(i);
                return true;
            }
        }
        return false;
    }

    /**
     * Updates the lobby settings with the values from the provided JSON object.
     * Existing settings are cleared before applying the new ones.
     *
     * @param settingsJson JSON object containing key/value pairs for settings.
     */
    public void updateSettings(JSONObject settingsJson) {
        settings.clear();
        Iterator<String> keys = settingsJson.keys();
        while (keys.hasNext()) {
            String key = keys.next();
            String value = settingsJson.optString(key, "");
            settings.put(key, value);
        }
    }

    /**
     * Sets the current status of the lobby.
     *
     * @param newStatus The new status to apply.
     */
    public void setStatus(LobbyStatus newStatus) {
        this.status = newStatus;
    }

    /**
     * Changes the owner of the lobby to the specified member ID.
     *
     * @param newOwnerId The ID of the new owner.
     * @throws IllegalArgumentException if the new owner is not an existing member.
     */
    public void changeOwner(String newOwnerId) {
        boolean exists = false;
        for (LobbyMember m : members) {
            if (m.getId().equals(newOwnerId)) {
                exists = true;
                break;
            }
        }
        if (!exists) {
            throw new IllegalArgumentException("New owner must be an existing member.");
        }
        this.ownerId = newOwnerId;
    }

    public String getLobbyId() {
        return lobbyId;
    }

    public String getOwnerId() {
        return ownerId;
    }

    public List<LobbyMember> getMembers() {
        return new ArrayList<>(members); // defensive copy
    }

    public Map<String, String> getSettings() {
        return new HashMap<>(settings); // defensive copy
    }

    public LobbyStatus getStatus() {
        return status;
    }
}
