import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ThreadResourceManager {
    // Internal map to keep track of created threads
    private final Map<String, Thread> threadMap = new ConcurrentHashMap<>();

    // Executor that monitors and cleans up dead threads
    private final ScheduledExecutorService monitorExecutor;

    /**
     * Constructs a ThreadResourceManager and starts a background monitor
     * that runs every second to remove any threads that are no longer alive.
     */
    public ThreadResourceManager() {
        monitorExecutor = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            t.setName("ThreadResourceManager-Monitor");
            return t;
        });

        // Schedule the cleanup task to run every second
        monitorExecutor.scheduleAtFixedRate(() -> {
            // Remove entries whose threads are not alive
            threadMap.entrySet().removeIf(entry -> !entry.getValue().isAlive());
        }, 1, 1, TimeUnit.SECONDS);
    }

    /**
     * Creates a daemon thread with the specified name and task.
     *
     * @param threadName the name of the thread to create
     * @param task       the Runnable task to run in the thread
     * @return true if the thread was created and started successfully; false if
     *         threadName or task is null
     */
    public boolean createDaemonThread(String threadName, Runnable task) {
        if (threadName == null || task == null) {
            return false;
        }

        Thread thread = new Thread(task, threadName);
        thread.setDaemon(true);
        thread.start();

        threadMap.put(threadName, thread);
        return true;
    }

    /**
     * Stops the daemon thread with the given name by interrupting it and
     * removing it from the internal map.
     *
     * @param threadName the name of the thread to stop
     * @return true if the thread was found and stopped; false otherwise
     */
    public boolean stopDaemonThread(String threadName) {
        if (threadName == null) {
            return false;
        }

        Thread thread = threadMap.remove(threadName);
        if (thread != null) {
            thread.interrupt();
            return true;
        }
        return false;
    }

    /**
     * Retrieves a thread by its name.
     *
     * @param threadName the name of the thread
     * @return the Thread instance, or null if no thread with that name exists
     */
    public Thread getThread(String threadName) {
        return threadMap.get(threadName);
    }

    /**
     * Returns the current number of active threads stored in the internal map.
     *
     * @return the count of active threads
     */
    public int getActiveThreadCount() {
        return threadMap.size();
    }

    /**
     * Stops all managed threads by interrupting them and clears the internal map.
     */
    public void stopAll() {
        for (Thread t : threadMap.values()) {
            t.interrupt();
        }
        threadMap.clear();
    }

