     * @param path the actual request path, e.g. "/users/123/profile"
     * @return {@code true} if the path matches the pattern, {@code false} otherwise
     */
    private boolean matchesParameterizedRoute(String routePattern, String path) {
        // Split both strings into segments, ignoring leading/trailing slashes
        String[] patternParts = routePattern.split("/");
        String[] pathParts = path.split("/");

        List<String> patternSegments = new ArrayList<>();
        for (String part : patternParts) {
            if (!part.isEmpty()) {
                patternSegments.add(part);
            }
        }

        List<String> pathSegments = new ArrayList<>();
        for (String part : pathParts) {
            if (!part.isEmpty()) {
                pathSegments.add(part);
            }
        }

        // The number of segments must be the same
        if (patternSegments.size() != pathSegments.size()) {
            return false;
        }

