class UrlRouter {
    private Map<String, String> routeMap;
    private String defaultRoute;

    public UrlRouter(Map<String, String> routes, String defaultRoute) {
        this.routeMap = new HashMap<>(routes);
        this.defaultRoute = defaultRoute;
    }

    /**
     * Resolve the given request path to a template name.
     * <p>
     * 1. If the path matches a static route, return its template name.
     * 2. If the path matches a parameterized route, extract the first
     *    parameter value and replace all occurrences of {@code {id}}
     *    in the template name with that value.
     * 3. If no match is found, return the default route.
     *
     * @param path the request path
     * @return the resolved template name
     */
    public String resolveRoute(String path) {
        // 1. Static route match
        if (routeMap.containsKey(path)) {
            return routeMap.get(path);
        }

        // 2. Parameterized route match
        for (Map.Entry<String, String> entry : routeMap.entrySet()) {
            String routePattern = entry.getKey();
            if (isParameterizedRoute(routePattern) &&
                matchesParameterizedRoute(routePattern, path)) {

                String parameter = extractParameter(routePattern, path);
                // If for some reason extraction failed, fall back to default
                if (parameter == null) {
                    return defaultRoute;
                }

                String templatePattern = entry.getValue();
                return constructParameterizedTemplate(templatePattern, parameter);
            }
        }

        // 3. No match – return default
        return defaultRoute;
    }

