            String pathSeg = pathSegments.get(i);

            if (isParameterSegment(patternSeg)) {
                continue; // any value is acceptable
            }

            if (!patternSeg.equals(pathSeg)) {
                return false;
            }
        }

        return true;
    }

    public String extractParameter(String routePattern, String path) {
        List<String> patternSegments = splitPath(routePattern);
        List<String> pathSegments = splitPath(path);

        if (patternSegments.size() != pathSegments.size()) {
            return null;
        }

        for (int i = 0; i < patternSegments.size(); i++) {
            String patternSeg = patternSegments.get(i);
            if (isParameterSegment(patternSeg)) {
                return pathSegments.get(i);
            }
        }

        return null; // no parameter placeholder found
    }

    /**
     * Replace all occurrences of {@code {id}} in the template pattern
     * with the supplied parameter value.
     *
     * @param templatePattern the template string containing {@code {id}}
     * @param parameter       the value to substitute
     * @return the final template name
     */
    public String constructParameterizedTemplate(String templatePattern, String parameter) {
        if (parameter == null) {
            return templatePattern;
        }
        return templatePattern.replace("{id}", parameter);
    }

    /* --------------------------------------------------------------------- */
    /* Utility methods                                                      */
    /* --------------------------------------------------------------------- */

    private List<String> splitPath(String path) {
        String[] parts = path.split("/");
        List<String> segments = new ArrayList<>();
        for (String part : parts) {
            if (!part.isEmpty()) {
                segments.add(part);
            }
        }
        return segments;
    }

    private boolean isParameterSegment(String segment) {
        return segment.startsWith("{") && segment.endsWith("}");
    }
