import java.util.ArrayList;
import java.util.List;
import java.util.function.IntUnaryOperator;

public class FunctionDemonstrator {

    /**
     * Demonstrates four function concepts:
     * 1. Primitive function (square) of the input value.
     * 2. Variable assignment to double the input value.
     * 3. Parameter passing via a method reference that adds five.
     * 4. Function composition (square then add five) using a higher‑order function.
     *
     * @param baseValue the integer to be processed
     * @return a list containing four formatted strings:
     *         - "Primitive function (square) result: X"
     *         - "Variable assignment result: Y"
     *         - "Parameter passing result: Z"
     *         - "Higher-order function result: W"
     */
    public List<String> demonstrateFunctionConcepts(int baseValue) {
        List<String> results = new ArrayList<>();

        // 1. Primitive function: square
        int squared = square(baseValue);
        results.add("Primitive function (square) result: " + squared);

        // 2. Variable assignment: double
        int doubled = baseValue * 2;
        results.add("Variable assignment result: " + doubled);

        // 3. Parameter passing via method reference
        IntUnaryOperator addFiveOperator = this::addFive;
        int addedFive = addFiveOperator.applyAsInt(baseValue);
        results.add("Parameter passing result: " + addedFive);

        // 4. Higher‑order function: compose square then add five
        IntUnaryOperator composed = compose(this::square, addFiveOperator);
        int composedResult = composed.applyAsInt(baseValue);
        results.add("Higher-order function result: " + composedResult);

        return results;
    }

    // Private helper method used in the third demonstration
    private int addFive(int x) {
        return x + 5;
    }

    // Private helper method for squaring
    private int square(int x) {
        return x * x;
    }

    /**
     * Higher‑order function that composes two IntUnaryOperator functions.
     * The returned function applies {@code first} then {@code second}.
     *
     * @param first  the first function to apply
     * @param second the second function to apply
     * @return a composed IntUnaryOperator
     */
    private IntUnaryOperator compose(IntUnaryOperator first, IntUnaryOperator second) {
        return first.andThen(second);
    }

    // Optional main method for quick testing
    public static void main(String[] args) {
        FunctionDemonstrator fd = new FunctionDemonstrator();
        List<String> output = fd.demonstrateFunctionConcepts(3);
        output.forEach(System.out::println);
    }
}

