import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.atomic.AtomicInteger;

public class P2PAddressServer {
    private final ConcurrentMap<String, PeerInfo> peerRegistry;
    private final int maxPeers;
    private final AtomicInteger currentPeers = new AtomicInteger(0);

    public P2PAddressServer() {
        this(100);
    }

    public P2PAddressServer(int maxPeers) {
        if (maxPeers < 1 || maxPeers > 10000) {
            throw new IllegalArgumentException("maxPeers must be between 1 and 10000 inclusive");
        }
        this.maxPeers = maxPeers;
        this.peerRegistry = new ConcurrentHashMap<>();
    }

    public boolean registerPeer(String peerId, String address, int port) {
        // Input validation
        if (peerId == null || peerId.isEmpty()) {
            return false;
        }
        if (port <= 0 || port > 65535) {
            return false;
        }

        // Check capacity
        if (currentPeers.get() >= maxPeers) {
            return false;
        }

        PeerInfo newPeer = new PeerInfo(address, port, System.currentTimeMillis());
        PeerInfo existing = peerRegistry.putIfAbsent(peerId, newPeer);
        if (existing != null) {
            return false; // duplicate ID
        }

        // Increment counter and ensure we didn't exceed capacity
        int newCount = currentPeers.incrementAndGet();
        if (newCount > maxPeers) {
            // Roll back registration
            peerRegistry.remove(peerId, newPeer);
            currentPeers.decrementAndGet();
            return false;
        }
        return true;
    }

    public static class PeerInfo {
        private final String address;
        private final int port;
        private final long registrationTime;

        public PeerInfo(String address, int port, long registrationTime) {
            this.address = address;
            this.port = port;
            this.registrationTime = registrationTime;
        }

        public String getAddress() {
            return address;
        }

        public int getPort() {
            return port;
