import java.lang.reflect.Array;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * A minimal ObjectInspector that can inspect an object and return a map
 * containing its type, value (for simple types), array elements, and
 * non‑static fields of complex objects. Recursion depth can be limited.
 */
public class ObjectInspector {

    /**
     * Inspects the given object with unlimited depth.
     *
     * @param obj the object to inspect
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj) {
        return inspectObject(obj, Integer.MAX_VALUE);
    }

    /**
     * Inspects the given object up to the specified maximum depth.
     *
     * @param obj      the object to inspect
     * @param maxDepth the maximum recursion depth (0 or less stops recursion)
     * @return a map with inspection results
     */
    public static Map<String, Object> inspectObject(Object obj, int maxDepth) {
        Map<String, Object> result = new HashMap<>();

        if (obj == null) {
            result.put("value", null);
            return result;
        }

        if (maxDepth <= 0) {
            // Depth limit reached – return type only
            result.put("type", obj.getClass().getSimpleName());
            return result;
        }

        Class<?> clazz = obj.getClass();

        if (isSimpleType(obj)) {
            result.put("type", clazz.getSimpleName());
            result.put("value", obj);
            return result;
        }

        if (clazz.isArray()) {
            Class<?> componentType = clazz.getComponentType();
            String typeName = componentType.getSimpleName() + "[]";
            result.put("type", typeName);

            int length = Array.getLength(obj);
            List<Object> inspectedElements = new ArrayList<>(length);
            for (int i = 0; i < length; i++) {
                Object element = Array.get(obj, i);
                inspectedElements.add(inspectObject(element, maxDepth - 1));
            }
            result.put("value", inspectedElements);
            return result;
        }

        // Complex object – inspect non‑static fields
        result.put("type", clazz.getSimpleName());
        Map<String, Object> fieldsMap = new HashMap<>();

        Class<?> current = clazz;
        while (current != null && current != Object.class) {
            Field[] fields = current.getDeclaredFields();
            for (Field field : fields) {
                if (Modifier.isStatic(field.getModifiers())) {
                    continue; // skip static fields
                }
                field.setAccessible(true);
                try {
                    Object fieldValue = field.get(obj);
                    fieldsMap.put(field.getName(), inspectObject(fieldValue, maxDepth - 1));
                } catch (IllegalAccessException e) {
                    throw new RuntimeException("Failed to access field: " + field.getName(), e);
                }
            }
            current = current.getSuperclass();
        }

        result.put("fields", fieldsMap);
        return result;
    }

    /**
     * Checks whether the given object is a simple type.
     *
     * @param obj the object to check
     * @return {@code true} if {@code obj} is an instance of
     *         {@link String}, {@link Number}, {@link Boolean} or {@link Character};
     *         {@code false} otherwise
     */
    private static boolean isSimpleType(Object obj) {
        return obj instanceof String
                || obj instanceof Number
                || obj instanceof Boolean
                || obj instanceof Character;
    }

    // Example usage (can be removed or commented out in production)
    public static void main(String[] args) {
        System.out.println(inspectObject(null));          // {value=null}
        System.out.println(inspectObject("Hello"));       // {type=String, value=Hello}
        System.out.println(inspectObject(42));            // {type=Integer, value=42}
        System.out.println(inspectObject(true));          // {type=Boolean, value=true}
        System.out.println(inspectObject('c'));           // {type=Character, value=c}
        System.out.println(inspectObject(new Object())); // {type=Object, fields={}}

        int[] intArray = {1, 2, 3};
        System.out.println(inspectObject(intArray));
        // {type=int[], value=[{type=Integer, value=1}, {type=Integer, value=2}, {type=Integer, value=3}]}

        String[][] stringArray = {{"a", "b"}, {"c", "d"}};
        System.out.println(inspectObject(stringArray));
        // {type=String[][], value=[[{type=String, value=a}, {type=String, value=b}], [{type=String, value=c}, {type=String, value=d}]]}

        // Complex object example
        class Person {
            String name = "Alice";
            int age = 30;
            static String species = "Human";
            private double height = 1.65;
        }
        Person p = new Person();
        System.out.println(inspectObject(p));
        // {type=Person, fields={name={type=String, value=Alice}, age={type=Integer, value=30}, height={type=Double, value=1.65}}}

        // Demonstrate depth limit
        Object[] nested = new Object[]{intArray, stringArray};
        System.out.println(inspectObject(nested, 1));
        // {type=Object[], value=[{type=int[], value=null}, {type=String[][], value=null}]}
    }
}

