     * @param uriString the URI string to process
     * @return a map with keys: "isValid", "authority", "path", "type"
     * @throws URISyntaxException if the URI string is malformed
     */
    public static Map<String, Object> processContentUri(String uriString) throws URISyntaxException {
        if (uriString == null) {
            throw new URISyntaxException("", "URI string is null");
        }

        // Attempt to parse the URI; this will throw URISyntaxException if malformed
        URI uri = new URI(uriString);

        Map<String, Object> result = new HashMap<>();
        result.put("isValid", true);

        // Extract authority and path using java.net.URI methods
        String authority = uri.getAuthority();
        String path = uri.getPath();

        result.put("authority", authority != null ? authority : "");
        result.put("path", path != null ? path : "");
        result.put("type", "UNKNOWN");

        return result;
    }
}

