import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PaginationUtils {

    /**
     * Returns a sublist of {@code items} starting at {@code offset} and containing at most {@code limit} elements.
     *
     * @param items  the original list of items (must not be {@code null})
     * @param limit  the maximum number of items to return (must be non‑negative)
     * @param offset the starting index (must be non‑negative)
     * @param <T>    the type of elements in the list
     * @return a new list containing the requested slice; an empty list if {@code offset} is beyond the end of {@code items}
     * @throws IllegalArgumentException if {@code items} is {@code null} or if {@code limit} or {@code offset} is negative
     */
    public static <T> List<T> paginate(List<T> items, int limit, int offset) {
        if (items == null) {
            throw new IllegalArgumentException("Items list cannot be null");
        }
        if (limit < 0 || offset < 0) {
            throw new IllegalArgumentException("Limit and offset must be non-negative");
        }

        int size = items.size();
        if (offset >= size) {
            return Collections.emptyList();
        }

        int end = Math.min(offset + limit, size);
        return new ArrayList<>(items.subList(offset, end));
    }
}

