import java.util.ArrayList;

class CargoOptimizer {

    /**
     * Calculates the maximum number of trips a cargo vehicle can make.
     * A trip can be made if a single item's weight is less than or equal to the vehicle's capacity.
     *
     * @param weights  List of item weights.
     * @param capacity Vehicle capacity.
     * @return Number of items that can be transported in separate trips.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty()) {
            return 0;
        }

        int trips = 0;
        for (int weight : weights) {
            if (weight <= capacity) {
                trips++;
            }
        }
        return trips;
    }
}

