     * Calculates the maximum number of trips a cargo vehicle can make.
     * <p>
     * A trip can be made in two ways:
     * <ul>
     *   <li>Single‑item trip: the item's weight is less than or equal to the vehicle capacity.</li>
     *   <li>Group trip: a group of items is chosen such that the heaviest item in the group
     *       multiplied by the group size is greater than or equal to the vehicle capacity.</li>
     * </ul>
     * After processing all single‑item trips, the remaining items are grouped greedily
     * to maximize the number of group trips. The greedy strategy uses the heaviest
     * remaining item as the group’s maximum and takes the smallest possible group
     * size that satisfies the capacity condition.
     *
     * @param weights  List of item weights.
     * @param capacity Vehicle capacity.
     * @return Number of trips that can be made.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        if (weights == null || weights.isEmpty() || capacity <= 0) {
            return 0;
        }

        int trips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // First pass: count single‑item trips and collect the rest
        for (int w : weights) {
            if (w <= capacity) {
                trips++;          // can travel alone
            } else {
                remaining.add(w); // candidate for grouping
            }
        }

        // If no items left for grouping, return the result
        if (remaining.isEmpty()) {
            return trips;
        }

        // Sort remaining weights to facilitate greedy grouping
        Collections.sort(remaining);

        int remainingCount = remaining.size();

        // Greedy grouping: use the heaviest remaining item as the group maximum
        while (remainingCount > 0) {
            int maxWeight = remaining.get(remainingCount - 1);
            int neededSize = (capacity + maxWeight - 1) / maxWeight; // ceil(capacity / maxWeight)

            if (remainingCount >= neededSize) {
                // Form a group of the required size
                remainingCount -= neededSize;
                trips++;
            } else {
                // Not enough items left to satisfy the capacity condition
                break;
            }
        }

        return trips;
    }
}

