class CargoOptimizer {

    /**
     * Calculates the maximum number of trips a cargo vehicle can make.
     *
     * <p>A trip can be made in two ways:</p>
     * <ul>
     *   <li><strong>Single‑item trip:</strong> an item's weight is less than or equal to the vehicle capacity.</li>
     *   <li><strong>Group trip:</strong> a group of items is chosen such that the heaviest item in the group
     *       multiplied by the group size is greater than or equal to the vehicle capacity.</li>
     * </ul>
     *
     * <p>The method first counts all single‑item trips and collects the remaining items.
     * It then sorts the remaining weights in descending order and greedily forms groups
     * starting with the heaviest available item. The smallest group size that satisfies
     * the capacity condition is used for each group.</p>
     *
     * @param weights  List of item weights. The original list is not modified.
     * @param capacity Vehicle capacity.
     * @return Number of trips that can be made, or 0 if input is null/empty or capacity is non‑positive.
     */
    public static int calculateMaxTrips(ArrayList<Integer> weights, int capacity) {
        // Handle null or empty input and non‑positive capacity
        if (weights == null || weights.isEmpty() || capacity <= 0) {
            return 0;
        }

        int trips = 0;
        ArrayList<Integer> remaining = new ArrayList<>();

        // First pass: count single‑item trips and collect the rest
        for (int w : weights) {
            if (w <= capacity) {
                trips++;          // can travel alone
            } else {
                remaining.add(w); // candidate for grouping
            }
        }

        // If no items left for grouping, return the result
        if (remaining.isEmpty()) {
            return trips;
        }

        // Sort remaining weights in descending order
        Collections.sort(remaining, Collections.reverseOrder());

        int index = 0;
        int size = remaining.size();

        // Greedy grouping: always start with the heaviest available item
        while (index < size) {
            int maxWeight = remaining.get(index);
            int neededSize = (capacity + maxWeight - 1) / maxWeight; // ceil(capacity / maxWeight)

            if (index + neededSize <= size) {
                // Form a group of the required size
                index += neededSize;
                trips++;
            } else {
                // Not enough items left to satisfy the capacity condition
                break;
            }
        }

        return trips;
    }
}

