public class AdvancedTileCalculator {

    /**
     * Calculates the tile configuration based on the presence of neighboring tiles.
     *
     * @param up        true if there is a neighbor above
     * @param down      true if there is a neighbor below
     * @param left      true if there is a neighbor to the left
     * @param right     true if there is a neighbor to the right
     * @param upLeft    true if there is a neighbor diagonally up‑left
     * @param upRight   true if there is a neighbor diagonally up‑right
     * @param downLeft  true if there is a neighbor diagonally down‑left
     * @param downRight true if there is a neighbor diagonally down‑right
     * @return a TileConfiguration instance:
     *         - (0, 0) if no neighbors are present,
     *         - (3, 0) if UP + LEFT + UP_LEFT are present,
     *         - (2, 0) if UP + RIGHT + UP_RIGHT are present,
     *         - (3, 1) if DOWN + LEFT + DOWN_LEFT are present,
     *         - (2, 1) if DOWN + RIGHT + DOWN_RIGHT are present,
     *         - (2, 2) for any T‑junction (exactly three orthogonal neighbors),
     *         - (4, 2) if all four orthogonal neighbors and all four diagonals are present,
     *         - (6, 0) if all four orthogonal neighbors are present but at least one diagonal is missing,
     *         - (5, 2) if only UP and DOWN are present,
     *         - (1, 2) if only LEFT and RIGHT are present,
     *         - (1, 0) if only UP is present,
     *         - (0, 2) if only DOWN is present,
     *         - (5, 1) if only LEFT is present,
     *         - (5, 0) if only RIGHT is present,
     *         - (1, 1) for all other configurations
     */
    public TileConfiguration calculateAdvancedTile(
            boolean up, boolean down, boolean left, boolean right,
            boolean upLeft, boolean upRight, boolean downLeft, boolean downRight) {

        // Isolated tile
        if (!up && !down && !left && !right && !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(0, 0);
        }

        // Corner cases
        if (up && left && upLeft &&
                !down && !right && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(3, 0);
        }
        if (up && right && upRight &&
                !down && !left && !upLeft && !downLeft && !downRight) {
            return new TileConfiguration(2, 0);
        }
        if (down && left && downLeft &&
                !up && !right && !upLeft && !upRight && !downRight) {
            return new TileConfiguration(3, 1);
        }
        if (down && right && downRight &&
                !up && !left && !upLeft && !upRight && !downLeft) {
            return new TileConfiguration(2, 1);
        }

        // T‑junctions (exactly three orthogonal neighbors)
        if (up && down && right && !left) {
            return new TileConfiguration(2, 2);
        }
        if (up && down && left && !right) {
            return new TileConfiguration(2, 2);
        }
        if (up && left && right && !down) {
            return new TileConfiguration(2, 2);
        }
        if (down && left && right && !up) {
            return new TileConfiguration(2, 2);
        }

        // Full cross
        if (up && down && left && right) {
            if (upLeft && upRight && downLeft && downRight) {
                return new TileConfiguration(4, 2); // fully surrounded
            } else {
                return new TileConfiguration(6, 0); // missing at least one diagonal
            }
        }

        // Vertical passage (only UP and DOWN)
        if (up && down &&
                !left && !right &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(5, 2);
        }

        // Horizontal passage (only LEFT and RIGHT)
        if (left && right &&
                !up && !down &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(1, 2);
        }

        // Dead ends (exactly one orthogonal neighbor)
        if (up &&
                !down && !left && !right &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(1, 0);
        }
        if (!up && down &&
                !left && !right &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(0, 2);
        }
        if (!up && !down && left &&
                !right &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(5, 1);
        }
        if (!up && !down && !left && right &&
                !upLeft && !upRight && !downLeft && !downRight) {
            return new TileConfiguration(5, 0);
        }

        // Default
        return new TileConfiguration(1, 1);
    }

