public class PathAnalyzer {

    /**
     * Analyzes the given file path and returns a map containing the filename and its extension.
     *
     * @param filePath the file path to analyze
     * @return a map with two entries:
     *         - "filename"  -> the filename component of the path
     *         - "extension" -> the file extension (empty string if none)
     * @throws IllegalArgumentException if filePath is null or empty
     */
    public static Map<String, Object> analyzePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) {
            throw new IllegalArgumentException("filePath must not be null or empty");
        }

        Path path = Paths.get(filePath);
        String filename = path.getFileName() != null ? path.getFileName().toString() : "";

        String extension = "";
        if (!filename.isEmpty() && !filename.startsWith(".")) {
            int lastDot = filename.lastIndexOf('.');
            if (lastDot != -1 && lastDot < filename.length() - 1) {
                extension = filename.substring(lastDot + 1);
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("filename", filename);
        result.put("extension", extension);
        return result;
    }
}

