import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.HashSet;
import java.util.List;
import java.util.ArrayList;
import java.util.Arrays;

/**
 * Exception thrown when configuration validation fails.
 */
class ConfigurationException extends RuntimeException {
    public ConfigurationException(String message) {
        super(message);
    }
}

/**
 * Functional interface for custom validation logic.
 */
interface Validator {
    /**
     * Validates the given value.
     *
     * @param value the value to validate
     * @return true if the value passes validation, false otherwise
     */
    boolean validate(Object value);

    /**
     * Returns the error message to be used if validation fails.
     *
     * @return the error message
     */
    String getErrorMessage();
}

/**
 * Manages configuration key-value pairs with support for required keys and custom validation.
 */
public class ConfigurationManager {
    private final Map<String, Object> configMap;
    private final Set<String> requiredKeys;
    private final Map<String, List<Validator>> validators;

    /**
     * Creates a new ConfigurationManager.
     *
     * @param requiredKeys the set of keys that must be present in any loaded configuration
     * @param validators   a map of validators for specific keys
     */
    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.requiredKeys = new HashSet<>(requiredKeys);
        this.validators = new HashMap<>(validators);
        this.configMap = new HashMap<>();
    }

    /**
     * Loads configuration from the given properties map.
     *
     * @param properties the map of configuration properties to load
     * @throws ConfigurationException if any required key is missing or validation fails
     */
    public void loadConfiguration(Map<String, String> properties) {
        // Check for missing required keys
        List<String> missing = new ArrayList<>();
        for (String key : requiredKeys) {
            if (!properties.containsKey(key)) {
                missing.add(key);
            }
        }
        if (!missing.isEmpty()) {
            throw new ConfigurationException(
                "Missing required keys: " + String.join(", ", missing));
        }

        // Store all properties (as strings) into the internal map
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            configMap.put(entry.getKey(), entry.getValue());
        }

        // Validate the loaded configuration
        validateConfiguration();
    }

    /**
     * Validates all configuration entries using the provided validators.
     *
     * @throws ConfigurationException if any validator fails
     */
    private void validateConfiguration() {
        for (Map.Entry<String, Object> entry : configMap.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            List<Validator> vList = validators.get(key);
            if (vList != null) {
                for (Validator v : vList) {
                    if (!v.validate(value)) {
                        throw new ConfigurationException(v.getErrorMessage());
                    }
                }
            }
        }
    }

    /**
     * Retrieves a configuration value cast to the requested type.
     *
     * @param key  the configuration key
     * @param type the desired type of the value
     * @param <T>  the type parameter
     * @return the configuration value cast to type T
     */
    public <T> T getConfigValue(String key, Class<T> type) {
        Object value = configMap.get(key);
        return type.cast(value);
    }

    /**
     * Sets a configuration value manually.
     *
     * @param key   the configuration key
     * @param value the value to associate with the key
     */
    public void setConfigValue(String key, Object value) {
        configMap.put(key, value);
    }

    // Example usage
    public static void main(String[] args) {
        // Define required keys
        Set<String> required = Set.of("host", "port");

        // Define validators
        Validator portValidator = new Validator() {
            @Override
            public boolean validate(Object value) {
                try {
                    int port = Integer.parseInt((String) value);
                    return port > 0 && port <= 65535;
                } catch (NumberFormatException e) {
                    return false;
                }
            }

            @Override
            public String getErrorMessage() {
                return "Port must be an integer between 1 and 65535";
            }
        };

        Validator timeoutValidator = new Validator() {
            @Override
            public boolean validate(Object value) {
                try {
                    int timeout = Integer.parseInt((String) value);
                    return timeout >= 0;
                } catch (NumberFormatException e) {
                    return false;
                }
            }

            @Override
            public String getErrorMessage() {
                return "Timeout must be a non‑negative integer";
            }
        };

        Map<String, List<Validator>> validators = new HashMap<>();
        validators.put("port", List.of(portValidator));
        validators.put("timeout", List.of(timeoutValidator));

        // Create manager
        ConfigurationManager manager = new ConfigurationManager(required, validators);

        // Sample properties
        Map<String, String> props = new HashMap<>();
        props.put("host", "localhost");
        props.put("port", "8080");
        props.put("timeout", "30");

        try {
            manager.loadConfiguration(props);
            String host = manager.getConfigValue("host", String.class);
            int port = Integer.parseInt(manager.getConfigValue("port", String.class));
            int timeout = Integer.parseInt(manager.getConfigValue("timeout", String.class));
            System.out.println("Host: " + host + ", Port: " + port + ", Timeout: " + timeout);
        } catch (ConfigurationException e) {
            System.err.println("Configuration error: " + e.getMessage());
        }
    }
}

