public class ConfigurationManager {
    private final Map<String, Object> configMap;
    private final Set<String> requiredKeys;
    private final Map<String, List<Validator>> validators;

    /**
     * Creates a new ConfigurationManager.
     *
     * @param requiredKeys the set of keys that must be present in any loaded configuration
     * @param validators   a map of validators for specific keys
     */
    public ConfigurationManager(Set<String> requiredKeys, Map<String, List<Validator>> validators) {
        this.requiredKeys = new HashSet<>(requiredKeys);
        this.validators = new HashMap<>(validators);
        this.configMap = new HashMap<>();
    }

    /**
     * Loads configuration from the given properties map.
     *
     * @param properties the map of configuration properties to load
     * @throws ConfigurationException if any required key is missing or validation fails
     */
    public void loadConfiguration(Map<String, String> properties) {
        // Check for missing required keys
        List<String> missing = new ArrayList<>();
        for (String key : requiredKeys) {
            if (!properties.containsKey(key)) {
                missing.add(key);
            }
        }
        if (!missing.isEmpty()) {
            throw new ConfigurationException(
                "Missing required keys: " + String.join(", ", missing));
        }

        // Store all properties (as strings) into the internal map
        for (Map.Entry<String, String> entry : properties.entrySet()) {
            configMap.put(entry.getKey(), entry.getValue());
        }

        // Validate the loaded configuration
        validateConfiguration();
    }

    /**
     * Validates all configuration entries using the provided validators.
     *
     * @throws ConfigurationException if any validator fails
     */
    private void validateConfiguration() {
        for (Map.Entry<String, Object> entry : configMap.entrySet()) {
            String key = entry.getKey();
            Object value = entry.getValue();
            List<Validator> vList = validators.get(key);
            if (vList != null) {
                for (Validator v : vList) {
                    if (!v.validate(value)) {
                        throw new ConfigurationException(v.getErrorMessage());
                    }
                }
            }
        }
