                return type.cast(Double.parseDouble(value.toString()));
            }

            if (type == Boolean.class) {
                if (value instanceof Boolean) {
                    return type.cast(value);
                }
                return type.cast(Boolean.parseBoolean(value.toString()));
            }

            if (type == String.class) {
                return type.cast(value.toString());
            }

            if (type == TimeUnit.class) {
                if (value instanceof TimeUnit) {
                    return type.cast(value);
                }
                return type.cast(TimeUnit.valueOf(value.toString().toUpperCase()));
            }

            // Fallback: direct cast if possible
            if (type.isInstance(value)) {
                return type.cast(value);
            }

            throw new ConfigurationException(
                "Unsupported conversion for key '" + key + "' to type " + type.getSimpleName());
        } catch (NumberFormatException | IllegalArgumentException e) {
            throw new ConfigurationException(
                "Failed to convert key '" + key + "' to type " + type.getSimpleName() + ": " + e.getMessage());
        }
