import java.util.concurrent.atomic.AtomicLong;
import java.util.HashMap;
import java.util.Map;

/**
 * Data transfer object representing a client.
 */
class ClientTO {
    private Long id;
    private String firstName;
    private String lastName;
    private String email;
    private String phone;

    public ClientTO(String firstName, String lastName, String email, String phone) {
        this.firstName = firstName;
        this.lastName  = lastName;
        this.email     = email;
        this.phone     = phone;
    }

    // Getters and setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getFirstName() { return firstName; }
    public void setFirstName(String firstName) { this.firstName = firstName; }

    public String getLastName() { return lastName; }
    public void setLastName(String lastName) { this.lastName = lastName; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getPhone() { return phone; }
    public void setPhone(String phone) { this.phone = phone; }

    @Override
    public String toString() {
        return "ClientTO{" +
                "id=" + id +
                ", firstName='" + firstName + '\'' +
                ", lastName='" + lastName + '\'' +
                ", email='" + email + '\'' +
                ", phone='" + phone + '\'' +
                '}';
    }
}

/**
 * Manager responsible for creating and storing clients.
 */
class ClientManager {
    private final Map<Long, ClientTO> clients = new HashMap<>();
    private final AtomicLong idGenerator = new AtomicLong(1);

    /**
     * Creates a new client, assigns a unique ID, stores it, and returns the client.
     *
     * @param client the client data (without ID)
     * @return the client with the assigned unique ID
     */
    public ClientTO createClient(ClientTO client) {
        long id = idGenerator.getAndIncrement();
        client.setId(id);
        clients.put(id, client);
        return client;
    }

    /**
     * Retrieves a client by its ID.
     *
     * @param id the client's unique ID
     * @return the client, or null if not found
     */
    public ClientTO getClient(Long id) {
        return clients.get(id);
    }
}

/**
 * Example usage of the client management system.
 */
public class Main {
    public static void main(String[] args) {
        ClientManager manager = new ClientManager();

        ClientTO newClient = new ClientTO("John", "Doe", "john.doe@example.com", "555-1234");
        ClientTO createdClient = manager.createClient(newClient);

        System.out.println("Created client: " + createdClient);

        // Retrieve the client by ID
        ClientTO fetchedClient = manager.getClient(createdClient.getId());
        System.out.println("Fetched client: " + fetchedClient);
    }
}

