        existing.setFirstName(client.getFirstName());
        existing.setLastName(client.getLastName());
        existing.setEmail(client.getEmail());
        existing.setPhone(client.getPhone());

        return existing;
    }

    /* --------------------------------------------------------------------- */
    /*  Admin‑protected operations                                         */
    /* --------------------------------------------------------------------- */

    /**
     * Finds a client by its ID. If {@code requireAdmin} is true, a
     * {@link SecurityException} is thrown when the caller does not have
     * administrative privileges.
     *
     * @param id            the client's unique ID
     * @param requireAdmin  whether admin privileges are required
     * @return the client if found, otherwise {@code null}
     * @throws IllegalArgumentException if {@code id} is {@code null}
     * @throws SecurityException        if admin privileges are required but not present
     */
    public ClientTO findClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to find client.");
        }
        if (id == null) {
            throw new IllegalArgumentException("Client ID cannot be null.");
        }
        return clients.get(id);
    }

    /**
     * Deletes a client by ID. If {@code requireAdmin} is true, a
     * {@link SecurityException} is thrown when the caller does not have
     * administrative privileges.
     *
     * @param id            the client's unique ID
     * @param requireAdmin  whether admin privileges are required
     * @return {@code true} if the client was deleted, {@code false} if not found
     * @throws IllegalArgumentException if {@code id} is {@code null}
     * @throws SecurityException        if admin privileges are required but not present
     */
    public boolean deleteClient(Long id, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to delete client.");
        }
        if (id == null) {
            throw new IllegalArgumentException("Client ID cannot be null.");
        }
        return clients.remove(id) != null;
    }

    /**
     * Returns a list of all clients. If {@code requireAdmin} is true, a
     * {@link SecurityException} is thrown when the caller does not have
     * administrative privileges.
     *
     * @param requireAdmin whether admin privileges are required
     * @return a list of all clients
     * @throws SecurityException if admin privileges are required but not present
     */
    public List<ClientTO> findAllClients(boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to list clients.");
        }
        return new ArrayList<>(clients.values());
    }

    /**
     * Returns a list of all clients that match the given filter. If the filter
     * is {@code null} or empty, all clients are returned. Otherwise, only
     * clients whose first name, last name, or email contains the filter
     * string (case‑insensitive) are returned.
     *
     * @param filter        the filter string
     * @param requireAdmin  whether admin privileges are required
     * @return a list of matching clients
     * @throws SecurityException if admin privileges are required but not present
     */
    public List<ClientTO> findAllClients(String filter, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to list clients.");
        }

        List<ClientTO> result = new ArrayList<>();
        if (filter == null || filter.trim().isEmpty()) {
            result.addAll(clients.values());
            return result;
        }

        String lowerFilter = filter.toLowerCase();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lowerFilter) ||
                containsIgnoreCase(c.getLastName(), lowerFilter) ||
                containsIgnoreCase(c.getEmail(), lowerFilter)) {
                result.add(c);
            }
        }
        return result;
    }

    /**
     * Searches for clients by first or last name (case‑insensitive).
     *
     * @param name          the name to search for
     * @param requireAdmin  whether admin privileges are required
     * @return a list of matching clients
     * @throws IllegalArgumentException if {@code name} is {@code null} or empty
     * @throws SecurityException        if admin privileges are required but not present
     */
    public List<ClientTO> findClientsByName(String name, boolean requireAdmin) {
        if (requireAdmin && !hasAdminPrivileges()) {
            throw new SecurityException("Admin privileges required to search clients.");
        }
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty.");
        }

        String lowerName = name.toLowerCase();
        List<ClientTO> result = new ArrayList<>();
        for (ClientTO c : clients.values()) {
            if (containsIgnoreCase(c.getFirstName(), lowerName) ||
                containsIgnoreCase(c.getLastName(), lowerName)) {
                result.add(c);
            }
        }
        return result;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                     */
    /* --------------------------------------------------------------------- */

    private void validateForCreate(ClientTO client) {
        if (client == null) {
            throw new IllegalArgumentException("Client cannot be null.");
        }
        if (client.getId() != null) {
            throw new IllegalArgumentException("Client ID must be null when creating a new client.");
        }
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private void validateForUpdate(ClientTO client) {
        if (isNullOrEmpty(client.getFirstName())) {
            throw new IllegalArgumentException("First name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getLastName())) {
            throw new IllegalArgumentException("Last name cannot be null or empty.");
        }
        if (isNullOrEmpty(client.getEmail())) {
            throw new IllegalArgumentException("Email cannot be null or empty.");
        }
        if (!client.getEmail().contains("@")) {
            throw new IllegalArgumentException("Email must contain '@'.");
        }
    }

    private boolean isNullOrEmpty(String s) {
        return s == null || s.trim().isEmpty();
    }

    private boolean containsIgnoreCase(String source, String search) {
        return source != null && source.toLowerCase().contains(search);
    }

    /**
     * Simulates a check for administrative privileges.
     *
     * @return {@code false} – no user has admin rights in this demo.
     */
    private boolean hasAdminPrivileges() {
        return false;
    }
}

