import java.sql.Timestamp;
import java.util.ArrayList;
import java.util.List;

/**
 * Basic implementation of a budget version manager.
 * It validates a budget version and can filter a list of versions
 * by status and effective date range.
 */
class BudgetVersionManager {

    /**
     * Validates a {@link VersaoOrcamento} instance.
     *
     * @param version the budget version to validate
     * @return a list of error messages; empty if the version is valid
     */
    public List<String> validateBudgetVersion(VersaoOrcamento version) {
        List<String> errors = new ArrayList<>();

        // 1. Null check
        if (version == null) {
            errors.add("Budget version cannot be null");
            return errors; // No further checks needed
        }

        // 2. ID check
        if (version.getIdVersaoOrcamento() == null) {
            errors.add("Version ID cannot be null");
        }

        // 3. Description check
        String descricao = version.getDescricaoMensagem();
        if (descricao == null || descricao.trim().isEmpty()) {
            errors.add("Description message is required");
        }

        // 4. Status check
        String status = version.getIdtStatus();
        if (status == null || !isValidStatus(status)) {
            errors.add("Status must be one of A, R, or P");
        }

        // 5. Effective date check
        if (version.getDataVigencia() == null) {
            errors.add("Effective date is required");
        }

        return errors;
    }

    /**
     * Filters a list of budget versions by optional status and date range.
     *
     * @param versions the list of versions to filter (may be null)
     * @param status   optional status filter (exact match); null means ignore
     * @param fromDate optional start date (inclusive); null means no lower bound
     * @param toDate   optional end date (inclusive); null means no upper bound
     * @return a list of versions that match all provided criteria; empty if input list is null
     */
    public List<VersaoOrcamento> filterVersions(
            List<VersaoOrcamento> versions,
            String status,
            Timestamp fromDate,
            Timestamp toDate) {

        List<VersaoOrcamento> result = new ArrayList<>();

        if (versions == null) {
            return result; // return empty list for null input
        }

        for (VersaoOrcamento v : versions) {
            // Skip null elements to avoid NPE
            if (v == null) {
                continue;
            }

            // Status filter
            if (status != null && !status.equals(v.getIdtStatus())) {
                continue;
            }

            // Effective date filter (inclusive)
            Timestamp vig = v.getDataVigencia();
            if (vig == null) {
                continue; // skip if date is missing
            }

            if (fromDate != null && vig.before(fromDate)) {
                continue;
            }

            if (toDate != null && vig.after(toDate)) {
                continue;
            }

            result.add(v);
        }

        return result;
    }

    private boolean isValidStatus(String status) {
        return "A".equals(status) || "R".equals(status) || "P".equals(status);
    }
}

