import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PaginationService<T> {

    /**
     * Paginates the given list of items.
     *
     * @param items       the full list of items to paginate
     * @param page        the page number (1-based)
     * @param rowsPerPage the number of items per page
     * @return a PaginatedResult containing the items for the requested page and the total item count
     */
    public PaginatedResult<T> paginate(List<T> items, int page, int rowsPerPage) {
        if (items == null) {
            items = Collections.emptyList();
        }

        int total = items.size();
        int startIndex = (page - 1) * rowsPerPage;
        if (startIndex < 0) {
            startIndex = 0;
        }

        if (startIndex >= total) {
            // Requested page is beyond the available data
            return new PaginatedResult<>(Collections.emptyList(), total);
        }

        int endIndex = Math.min(startIndex + rowsPerPage, total);
        List<T> pageItems = items.subList(startIndex, endIndex);

        return new PaginatedResult<>(pageItems, total);
    }

    /**
     * Holds the result of a pagination operation.
     *
     * @param <T> the type of items in the result
     */
    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            // Defensive copy to prevent external modification
            this.items = new ArrayList<>(items);
            this.total = total;
        }

        /**
         * @return the list of items for the current page
         */
        public List<T> getItems() {
            return items;
        }

        /**
         * @return the total number of items across all pages
         */
        public int getTotal() {
            return total;
        }
    }
}

