                }
            });
            return sorted;
        } catch (Exception e) {
            // Any exception (e.g., security, illegal access) results in unsorted list
            return items;
        }
    }

    /**
     * Holds the result of a pagination operation.
     *
     * @param <T> the type of items in the result
     */
    public static class PaginatedResult<T> {
        private final List<T> items;
        private final int total;

        public PaginatedResult(List<T> items, int total) {
            // Defensive copy to prevent external modification
            this.items = new ArrayList<>(items);
            this.total = total;
        }

        /**
         * @return the list of items for the current page
         */
        public List<T> getItems() {
            return items;
        }

        /**
         * @return the total number of items across all pages (after filtering and sorting)
         */
        public int getTotal() {
            return total;
        }
    }
