import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class AdvancedFileProcessor {

    private final Path directoryPath;

    /**
     * Creates a processor for the given directory.
     *
     * @param dirPath the path to the directory
     * @throws IllegalArgumentException if the path does not exist or is not a directory
     */
    public AdvancedFileProcessor(String dirPath) {
        Path path = Paths.get(dirPath);
        if (!Files.isDirectory(path)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + dirPath);
        }
        this.directoryPath = path;
    }

    /**
     * Processes files in the directory and returns statistics.
     *
     * @return a map containing fileCount, totalSize, largestFile, and wordFrequency
     */
    public Map<String, Object> processFiles() {
        Map<String, Object> stats = new HashMap<>();

        int fileCount = 0;
        long totalSize = 0L;
        Path largestFile = null;
        long largestSize = -1L;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directoryPath)) {
            for (Path entry : stream) {
                if (Files.isRegularFile(entry)) {
                    fileCount++;
                    long size = Files.size(entry);
                    totalSize += size;
                    if (size > largestSize) {
                        largestSize = size;
                        largestFile = entry;
                    }
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Error while processing files", e);
        }

        stats.put("fileCount", fileCount);
        stats.put("totalSize", totalSize);
        stats.put("largestFile", largestFile);
        stats.put("wordFrequency", Collections.emptyMap()); // placeholder

        return stats;
    }
}

