import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class AdvancedFileProcessor {

    private final Path directoryPath;

    /**
     * Creates a processor for the given directory.
     *
     * @param dirPath the path to the directory
     * @throws IllegalArgumentException if the path does not exist or is not a directory
     */
    public AdvancedFileProcessor(String dirPath) {
        Path path = Paths.get(dirPath);
        if (!Files.isDirectory(path)) {
            throw new IllegalArgumentException("Provided path is not a directory: " + dirPath);
        }
        this.directoryPath = path;
    }

    /**
     * Processes files in the directory and returns statistics.
     *
     * @return a map containing fileCount, totalSize, largestFile, and wordFrequency
     */
    public Map<String, Object> processFiles() {
        Map<String, Object> stats = new HashMap<>();

        int fileCount = 0;
        long totalSize = 0L;
        Path largestFile = null;
        long largestSize = -1L;
        Map<String, Integer> wordFrequency = new HashMap<>();

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directoryPath)) {
            for (Path entry : stream) {
                if (Files.isRegularFile(entry)) {
                    fileCount++;
                    long size = Files.size(entry);
                    totalSize += size;
                    if (size > largestSize) {
                        largestSize = size;
                        largestFile = entry;
                    }
                    processFileContent(entry, wordFrequency);
                }
            }
        } catch (IOException e) {
            throw new RuntimeException("Error while processing files", e);
        }

        stats.put("fileCount", fileCount);
        stats.put("totalSize", totalSize);
        stats.put("largestFile",
                largestFile != null ? largestFile.getFileName().toString() : "N/A");
        stats.put("wordFrequency", wordFrequency);

        return stats;
    }

    /**
     * Reads the content of the given file, splits it into words, normalizes them,
     * and updates the provided word frequency map.
     *
     * @param file          the file to read
     * @param wordFrequency the map to update with word counts
     */
    private void processFileContent(Path file, Map<String, Integer> wordFrequency) {
        try {
            // Read all lines as a single string
            String content = Files.readString(file, StandardCharsets.UTF_8);

            // Split by whitespace
            String[] tokens = content.split("\\s+");

            for (String token : tokens) {
                // Remove non‑alphabetic characters and convert to lowercase
                String word = token.replaceAll("[^a-zA-Z]", "").toLowerCase();

                if (!word.isEmpty()) {
                    wordFrequency.merge(word, 1, Integer::sum);
                }
            }
        } catch (IOException e) {
            // If a file cannot be read, we simply skip it
            // In a real application you might log this event
        }
    }
}

