/**
 * Represents the travel class configuration of an airplane.
 */
class TravelClass {
    private int economySeats;
    private int businessSeats;
    private int firstClassSeats;

    public TravelClass(int economySeats, int businessSeats, int firstClassSeats) {
        this.economySeats = economySeats;
        this.businessSeats = businessSeats;
        this.firstClassSeats = firstClassSeats;
    }

    public int getEconomySeats() {
        return economySeats;
    }

    public int getBusinessSeats() {
        return businessSeats;
    }

    public int getFirstClassSeats() {
        return firstClassSeats;
    }

    /**
     * Returns the total number of seats across all classes.
     */
    public int getTotalSeats() {
        return economySeats + businessSeats + firstClassSeats;
    }
}

/**
 * Represents an airplane with a model name and a travel class configuration.
 */
class Airplane {
    private String model;
    private TravelClass travelClass;

    public Airplane(String model, TravelClass travelClass) {
        this.model = model;
        this.travelClass = travelClass;
    }

    public String getModel() {
        return model;
    }

    public TravelClass getTravelClass() {
        return travelClass;
    }
}

