    private List<Airplane> fleet = new ArrayList<>();

    /**
     * Adds an airplane to the fleet.
     */
    public void addAirplane(Airplane airplane) {
        fleet.add(airplane);
    }

    /**
     * Returns the current list of airplanes in the fleet.
     */
    public List<Airplane> getFleet() {
        return fleet;
    }
}

