/**
 * Manages a collection of User objects.
 */
public class UserManager {
    private final Map<String, User> users = new HashMap<>();

    // Pre‑compiled pattern for Steam community URLs
    private static final Pattern STEAM_URL_PATTERN =
            Pattern.compile("^(https?://)?(www\\.)?steamcommunity\\.com/.*$");

    /**
     * Adds a new user to the manager after validating all fields.
     *
     * @param steam32Id   the Steam 32‑bit ID
     * @param username    the user's display name
     * @param profileURL  the URL to the user's Steam profile
     * @param avatarMedium URL of the medium‑sized avatar
     * @param avatarFull   URL of the full‑sized avatar
     * @throws IllegalArgumentException if any validation fails
     */
    public void addUser(String steam32Id, String username, String profileURL,
                        String avatarMedium, String avatarFull) {
        // Validate Steam ID: must be exactly 17 digits
        if (steam32Id == null || !steam32Id.matches("\\d{17}")) {
            throw new IllegalArgumentException("Invalid Steam ID format");
        }

        // Validate username: not null, length 2‑32 characters
        if (username == null || username.length() < 2 || username.length() > 32) {
            throw new IllegalArgumentException("Username must be 2-32 characters");
        }

        // Validate profile URL against Steam community pattern
        if (profileURL == null || !STEAM_URL_PATTERN.matcher(profileURL).matches()) {
            throw new IllegalArgumentException("Invalid Steam profile URL");
        }

        // Validate avatarMedium: non‑null and non‑empty
        if (avatarMedium == null || avatarMedium.isEmpty()) {
            throw new IllegalArgumentException("Avatar medium URL cannot be null or empty");
        }

        // Validate avatarFull: non‑null and non‑empty
        if (avatarFull == null || avatarFull.isEmpty()) {
            throw new IllegalArgumentException("Avatar full URL cannot be null or empty");
        }

        User user = new User(steam32Id, username, profileURL, avatarMedium, avatarFull);
        users.put(steam32Id, user);
    }

    /**
     * Retrieves a user by their Steam ID.
     *
     * @param steam32Id the Steam 32‑bit ID
     * @return the User object, or null if not found
     */
    public User getUserBySteamId(String steam32Id) {
        return users.get(steam32Id);
