import java.util.*;

public class FinancialReportAnalyzer {

    /**
     * Analyzes a list of PolicyData objects and returns a map containing
     * the total premium amount and the number of policies processed.
     *
     * @param policies List of PolicyData objects to analyze.
     * @return Map with keys "totalPremium" (Double) and "policyCount" (Integer).
     */
    public static Map<String, Object> analyze(List<PolicyData> policies) {
        Map<String, Object> result = new HashMap<>();
        double totalPremium = 0.0;
        int policyCount = 0;

        if (policies != null) {
            for (PolicyData pd : policies) {
                if (pd != null) {
                    totalPremium += pd.getPremiumAmount();
                    policyCount++;
                }
            }
        }

        result.put("totalPremium", totalPremium);
        result.put("policyCount", policyCount);
        return result;
    }

    /**
     * Inner class that keeps a summary of policies for a specific risk category.
     */
    public static class RiskSummary {
        private final String riskName;
        private double totalPremium;
        private int policyCount;

        public RiskSummary(String riskName) {
            this.riskName = riskName;
            this.totalPremium = 0.0;
            this.policyCount = 0;
        }

        /**
         * Adds a policy to this summary, updating the total premium and policy count.
         *
         * @param premium The premium amount of the policy to add.
         */
        public void addPolicy(double premium) {
            this.totalPremium += premium;
            this.policyCount++;
        }

        public String getRiskName() {
            return riskName;
        }

        public double getTotalPremium() {
            return totalPremium;
        }

        public int getPolicyCount() {
            return policyCount;
        }

        @Override
        public String toString() {
            return "RiskSummary{" +
                    "riskName='" + riskName + '\'' +
                    ", totalPremium=" + totalPremium +
                    ", policyCount=" + policyCount +
                    '}';
        }
    }

    // Example usage
    public static void main(String[] args) {
        List<PolicyData> list = new ArrayList<>();
        list.add(new PolicyData("RC1", "Risk1", "RC2", "Risk2", 1000.0));
        list.add(new PolicyData("RC3", "Risk3", "RC4", "Risk4", 2000.0));
        list.add(new PolicyData("RC5", "Risk5", "RC6", "Risk6", 1500.0));

        Map<String, Object> report = analyze(list);
        System.out.println("Total Premium: " + report.get("totalPremium"));
        System.out.println("Policy Count: " + report.get("policyCount"));

        // Demonstrate RiskSummary usage
        Map<String, RiskSummary> riskSummaries = new HashMap<>();
        for (PolicyData pd : list) {
            String riskName = pd.getCurrentRiskName();
            RiskSummary summary = riskSummaries.computeIfAbsent(riskName,
                    k -> new RiskSummary(k));
            summary.addPolicy(pd.getPremiumAmount());
        }

        System.out.println("\nRisk Summaries:");
        riskSummaries.values().forEach(System.out::println);
    }
}

