}

// Enhanced product manager with logging, validation, and restricted categories
class EnhancedProductManager {
    private final Map<Integer, Product> productDatabase;
    private final LoggerService logger;
    private final Set<Integer> restrictedCategories;

    public EnhancedProductManager(LoggerService logger, List<Integer> restrictedCategories) {
        this.productDatabase = new HashMap<>();
        this.logger = logger;
        this.restrictedCategories = new HashSet<>(restrictedCategories);
    }

    public Map<String, String> addProduct(Product product) {
        Map<String, String> result = new HashMap<>();

        // Validate product object
        if (product == null) {
            result.put("status", "error");
            result.put("message", "Product cannot be null");
            return result;
        }

        // Validate product name
        String name = product.getName();
        if (name == null || name.trim().isEmpty()) {
            result.put("status", "error");
            result.put("message", "Product name cannot be empty");
            return result;
        }

        // Validate restricted category
        int categoryId = product.getCategoryId();
        if (restrictedCategories.contains(categoryId)) {
            result.put("status", "error");
            result.put("message", "Products in category " + categoryId + " are not allowed");
            return result;
        }

        // Add product to database
        productDatabase.put(product.getId(), product);
        result.put("status", "success");
        result.put("message", "Product added successfully");

        // Log the successful addition
        if (logger != null) {
            logger.log("Product added: " + product.getName());
        }

        return result;
    }

    public List<Product> getAllProducts() {
        return new ArrayList<>(productDatabase.values());
    }
}

// Demo application
public class Main {
    public static void main(String[] args) {
        LoggerService logger = new ConsoleLogger();

        // Restricted categories: 101 and 102
        List<Integer> restricted = Arrays.asList(101, 102);
        EnhancedProductManager manager = new EnhancedProductManager(logger, restricted);

        Product p1 = new Product(1, "Laptop", 101);          // Restricted
        Product p2 = new Product(2, "Smartphone", 103);      // Allowed
        Product p3 = new Product(3, "", 104);               // Invalid name
        Product p4 = new Product(4, "Tablet", 102);          // Restricted
        Product p5 = new Product(5, "Camera", 105);         // Allowed

        System.out.println(manager.addProduct(p1)); // Error: restricted
        System.out.println(manager.addProduct(p2)); // Success
        System.out.println(manager.addProduct(p3)); // Error: empty name
        System.out.println(manager.addProduct(p4)); // Error: restricted
        System.out.println(manager.addProduct(p5)); // Success

        System.out.println("\nAll products in the database:");
        for (Product p : manager.getAllProducts()) {
            System.out.println("ID: " + p.getId() + ", Name: " + p.getName() + ", Category ID: " + p.getCategoryId());
        }
    }
}

