class MatrixProcessor {
    public MatrixResult processMatrix(int[][] matrix) {
        if (matrix == null || matrix.length == 0) {
            return new MatrixResult(new int[0][0]);
        }

        int rows = matrix.length;
        int cols = matrix[0].length;

        boolean[] zeroRows = new boolean[rows];
        boolean[] zeroCols = new boolean[cols];

        // First pass: identify rows and columns that contain a zero
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (matrix[r][c] == 0) {
                    zeroRows[r] = true;
                    zeroCols[c] = true;
                }
            }
        }

        // Second pass: build the processed matrix
        int[][] processed = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (zeroRows[r] || zeroCols[c]) {
                    processed[r][c] = 0;
                } else {
                    processed[r][c] = matrix[r][c];
                }
            }
        }

        return new MatrixResult(processed);
    }

    static class MatrixResult {
        final int[][] processedMatrix;

        public MatrixResult(int[][] processedMatrix) {
            this.processedMatrix = processedMatrix;
        }
    }
}

