import java.util.*;
import java.time.*;
import java.time.format.DateTimeFormatter;

class TaskDatabaseManager {
    private List<Map<String, Object>> taskCache;
    private static final DateTimeFormatter TIMESTAMP_FORMAT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    public TaskDatabaseManager() {
        this.taskCache = new ArrayList<>();
    }

    /**
     * Inserts a new task into the in-memory cache.
     *
     * @param taskType    the type of the task (e.g., 1 for assignment, 2 for quiz)
     * @param taskName    the name/title of the task
     * @param taskContent the content or description of the task
     * @param studentId   the ID of the student associated with the task
     * @param studentName the name of the student
     * @return a map containing the status ("success"), the generated taskId,
     *         and the number of affected rows (always 1)
     */
    public Map<String, Object> insertTask(int taskType, String taskName, String taskContent,
                                          int studentId, String studentName) {
        // Generate a UUID-based task ID
        String taskId = UUID.randomUUID().toString();

        // Current timestamp in the required format
        String createdAt = LocalDateTime.now().format(TIMESTAMP_FORMAT);

        // Build the task record
        Map<String, Object> task = new HashMap<>();
        task.put("taskId", taskId);
        task.put("taskType", taskType);
        task.put("taskName", taskName);
        task.put("taskContent", taskContent);
        task.put("studentId", studentId);
        task.put("studentName", studentName);
        task.put("createdAt", createdAt);
        task.put("successCount", 0);
        task.put("failCount", 0);
        task.put("score", 0);
        task.put("status", "pending");

        // Store the task in the cache
        taskCache.add(task);

        // Prepare the response map
        Map<String, Object> response = new HashMap<>();
        response.put("status", "success");
        response.put("taskId", taskId);
        response.put("affectedRows", 1);

        return response;
    }

    /**
     * Queries tasks that match all key/value pairs in the provided criteria.
     * Supports 1‑based pagination. Invalid page numbers are clamped to the
     * nearest valid page.
     *
     * @param criteria   a map of key/value pairs that each returned task must
     *                   match exactly. If null or empty, all tasks are returned.
     * @param pageNumber the 1‑based page number to retrieve
     * @param pageSize   the maximum number of items per page
     * @return a map containing:
     *         - "tasks"      : List of task maps for the requested page
     *         - "currentPage": The actual page number returned
     *         - "totalPages" : Total number of pages available
     *         - "totalItems" : Total number of items matching the criteria
     */
    public Map<String, Object> queryTasks(Map<String, Object> criteria,
                                          int pageNumber, int pageSize) {
        // Validate pageSize
        if (pageSize <= 0) {
            pageSize = 10; // default page size
        }

        // Filter tasks based on criteria
        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Map<String, Object> task : taskCache) {
            boolean matches = true;
            if (criteria != null) {
                for (Map.Entry<String, Object> entry : criteria.entrySet()) {
                    Object taskValue = task.get(entry.getKey());
                    if (taskValue == null || !taskValue.equals(entry.getValue())) {
                        matches = false;
                        break;
                    }
                }
            }
            if (matches) {
                filtered.add(task);
            }
        }

        int totalItems = filtered.size();
        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        if (totalPages == 0) {
            totalPages = 0;
        }

        // Clamp pageNumber to valid range
        int currentPage = pageNumber;
        if (currentPage < 1) {
            currentPage = 1;
        }
        if (currentPage > totalPages && totalPages > 0) {
            currentPage = totalPages;
        }
        if (totalPages == 0) {
            currentPage = 0;
        }

        // Determine slice indices
        int startIndex = (currentPage - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, totalItems);
        List<Map<String, Object>> pageTasks = new ArrayList<>();
        if (startIndex < endIndex) {
            pageTasks = filtered.subList(startIndex, endIndex);
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("tasks", pageTasks);
        result.put("currentPage", currentPage);
        result.put("totalPages", totalPages);
        result.put("totalItems", totalItems);

        return result;
    }

    // Optional helper methods for further functionality

    /**
     * Retrieves a task by its UUID.
     *
     * @param taskId the UUID of the task to retrieve
     * @return the task map if found, otherwise null
     */
    public Map<String, Object> getTaskById(String taskId) {
        for (Map<String, Object> task : taskCache) {
            if (task.get("taskId").equals(taskId)) {
                return task;
            }
        }
        return null;
    }

    /**
     * Returns the total number of tasks stored.
     *
     * @return the size of the task cache
     */
    public int getTaskCount() {
        return taskCache.size();
    }
}

