    // Set of all variables that appear in clauses
    private final Set<Integer> variables = new HashSet<>();

    // Set of all literals that appear in the implication graph
    private final Set<Integer> literals = new HashSet<>();

    // List of clauses (optional, for inspection)
    private final List<int[]> clauses = new ArrayList<>();

    // Implication graph: literal -> list of literals it implies
    private final Map<Integer, List<Integer>> graph = new HashMap<>();

    // Reverse implication graph: literal -> list of literals that imply it
    private final Map<Integer, List<Integer>> reverseGraph = new HashMap<>();

    // Finishing times computed during the first pass of Kosaraju
    private final Map<Integer, Integer> finishingTimes = new HashMap<>();

    // Leader of each literal after the second pass
    private final Map<Integer, Integer> leaders = new HashMap<>();

    public TwoSatSolver() {
        // No special initialization needed
    }

    /**
     * Adds a clause (a ∨ b) to the solver.
     * Stores the clause, updates the set of variables,
     * and adds the implication edges (-a → b) and (-b → a)
     * to both the normal and reverse graphs.
     *
     * @param a first literal (positive for the variable, negative for its negation)
     * @param b second literal
     */
    public void addClause(int a, int b) {
        // Record the variables involved
        variables.add(Math.abs(a));
        variables.add(Math.abs(b));

        // Record all literals that appear
        literals.add(a);
        literals.add(b);
        literals.add(-a);
        literals.add(-b);

        // Store the clause itself
        clauses.add(new int[]{a, b});

        // Add implication edges to the graph
        // (-a) → b
        graph.computeIfAbsent(-a, k -> new ArrayList<>()).add(b);
        // (-b) → a
        graph.computeIfAbsent(-b, k -> new ArrayList<>()).add(a);

        // Add reverse implication edges to the reverse graph
        // b → (-a)
        reverseGraph.computeIfAbsent(b, k -> new ArrayList<>()).add(-a);
        // a → (-b)
        reverseGraph.computeIfAbsent(a, k -> new ArrayList<>()).add(-b);
    }

    /**
     * Performs both passes of Kosaraju's algorithm:
     * 1. First pass on the reverse graph to compute finishing times.
     * 2. Second pass on the original graph to determine strongly connected components.
     * After the second pass, checks for contradictions: if any variable and its negation
     * share the same leader, the instance is unsatisfiable.
     *
     * @return true if the set of clauses is satisfiable, false otherwise
     */
    public boolean isSatisfiable() {
        // ---------- First pass ----------
        Set<Integer> visited = new HashSet<>();
        int time = 0;
        for (int node : literals) {
            if (!visited.contains(node)) {
                time = dfsFirstPass(node, visited, time);
            }
        }

        // ---------- Second pass ----------
        visited.clear();
        // Order nodes by decreasing finishing time
        List<Integer> order = new ArrayList<>(literals);
        order.sort((x, y) -> Integer.compare(finishingTimes.get(y), finishingTimes.get(x)));

        for (int node : order) {
            if (!visited.contains(node)) {
                dfsSecondPass(node, visited, node);
            }
        }

        // ---------- Contradiction check ----------
        for (int var : variables) {
            int posLeader = leaders.get(var);
            int negLeader = leaders.get(-var);
            if (posLeader == negLeader) {
                return false; // variable and its negation in the same SCC
            }
        }
        return true;
    }

    // Helper DFS for the first pass (reverse graph)
    private int dfsFirstPass(int node, Set<Integer> visited, int time) {
        visited.add(node);
        for (int neighbor : reverseGraph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                time = dfsFirstPass(neighbor, visited, time);
            }
        }
        finishingTimes.put(node, time);
        return time + 1;
    }

    // Helper DFS for the second pass (original graph)
    private void dfsSecondPass(int node, Set<Integer> visited, int leader) {
        visited.add(node);
        leaders.put(node, leader);
        for (int neighbor : graph.getOrDefault(node, Collections.emptyList())) {
            if (!visited.contains(neighbor)) {
                dfsSecondPass(neighbor, visited, leader);
            }
        }
    }

    // Optional helper methods for inspection

    public Set<Integer> getVariables() {
        return Collections.unmodifiableSet(variables);
    }

    public List<int[]> getClauses() {
        return Collections.unmodifiableList(clauses);
    }

    public Map<Integer, List<Integer>> getGraph() {
        return Collections.unmodifiableMap(graph);
    }

    public Map<Integer, List<Integer>> getReverseGraph() {
        return Collections.unmodifiableMap(reverseGraph);
    }

    public Map<Integer, Integer> getFinishingTimes() {
        return Collections.unmodifiableMap(finishingTimes);
    }

    public Map<Integer, Integer> getLeaders() {
        return Collections.unmodifiableMap(leaders);
    }
}
