import java.util.ArrayList;
import java.util.List;

/**
 * Represents a frequency assignment with a required bandwidth.
 */
class FrequencyAssignment {
    private final double requiredBandwidth;

    public FrequencyAssignment(double requiredBandwidth) {
        this.requiredBandwidth = requiredBandwidth;
    }

    public double getRequiredBandwidth() {
        return requiredBandwidth;
    }
}

/**
 * Represents a channel with an available bandwidth.
 */
class Channel {
    private final double availableBandwidth;

    public Channel(double availableBandwidth) {
        this.availableBandwidth = availableBandwidth;
    }

    public double getAvailableBandwidth() {
        return availableBandwidth;
    }
}

/**
 * Represents a plan consisting of frequency assignments and channels.
 */
class Plan {
    private final List<FrequencyAssignment> assignments;
    private final List<Channel> channels;

    public Plan(List<FrequencyAssignment> assignments, List<Channel> channels) {
        this.assignments = assignments;
        this.channels = channels;
    }

    public List<FrequencyAssignment> getAssignments() {
        return assignments;
    }

    public List<Channel> getChannels() {
        return channels;
    }

    /**
     * Calculates the total required bandwidth from all assignments.
     */
    public double getTotalRequiredBandwidth() {
        double sum = 0.0;
        for (FrequencyAssignment fa : assignments) {
            sum += fa.getRequiredBandwidth();
        }
        return sum;
    }

    /**
     * Calculates the total available bandwidth from all channels.
     */
    public double getTotalAvailableBandwidth() {
        double sum = 0.0;
        for (Channel ch : channels) {
            sum += ch.getAvailableBandwidth();
        }
        return sum;
    }

    /**
     * Creates a plan from arrays of required and available bandwidths.
     * Only positive bandwidth values are considered; others are ignored.
     */
    public static Plan createPlan(double[] requiredBandwidths, double[] availableBandwidths) {
        List<FrequencyAssignment> assignments = new ArrayList<>();
        for (double bw : requiredBandwidths) {
            if (bw > 0) {
                assignments.add(new FrequencyAssignment(bw));
            }
        }

        List<Channel> channels = new ArrayList<>();
        for (double bw : availableBandwidths) {
            if (bw > 0) {
                channels.add(new Channel(bw));
            }
        }

        return new Plan(assignments, channels);
    }
}

/**
 * Example usage of the FrequencyPlanner system.
 */
public class FrequencyPlannerDemo {
    public static void main(String[] args) {
        double[] required = { 10.5, -2.0, 5.0, 0.0, 7.5 };
        double[] available = { 20.0, 15.0, -5.0, 8.0 };

        Plan plan = Plan.createPlan(required, available);

        System.out.println("Total Required Bandwidth: " + plan.getTotalRequiredBandwidth());
        System.out.println("Total Available Bandwidth: " + plan.getTotalAvailableBandwidth());
    }
}

