import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class AdvancedDotProductCalculator {

    public static int calculateDotProduct(int[] first, int[] second) {
        if (first == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (second == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (first.length != second.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }

        int dotProduct = 0;
        for (int i = 0; i < first.length; i++) {
            dotProduct += first[i] * second[i];
        }
        return dotProduct;
    }

    public static int calculateDotProduct(int[] first, int[] second, int threadCount) {
        if (first == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (second == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (first.length != second.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
        if (threadCount <= 0) {
            throw new IllegalArgumentException("Thread count must be positive");
        }

        int length = first.length;
        if (length == 0) {
            return 0;
        }

        ExecutorService executor = Executors.newFixedThreadPool(threadCount);
        List<Future<Integer>> futures = new ArrayList<>();

        int chunkSize = (length + threadCount - 1) / threadCount; // ceil division

        for (int i = 0; i < threadCount; i++) {
            final int start = i * chunkSize;
            if (start >= length) {
                break; // no more data to process
            }
            final int end = Math.min(start + chunkSize, length);

            Callable<Integer> task = () -> {
                int partialSum = 0;
                for (int j = start; j < end; j++) {
                    partialSum += first[j] * second[j];
                }
                return partialSum;
            };
            futures.add(executor.submit(task));
        }

        int total = 0;
        try {
            for (Future<Integer> future : futures) {
                total += future.get();
            }
        } catch (InterruptedException | ExecutionException e) {
            // In case of exception, rethrow as unchecked
            throw new RuntimeException("Error computing dot product in parallel", e);
        } finally {
            executor.shutdown();
        }

        return total;
    }
}

