class NeuralNetworkCalculator {
    private final int inputSize;
    private final int hiddenSize;
    private final int outputSize;
    private final double[] weights;
    private final double[][] inputNormalizationParams;
    private final double[][] outputNormalizationParams;
    private final double[][] weightIH; // input -> hidden
    private final double[][] weightHO; // hidden -> output

    public NeuralNetworkCalculator(int inputSize, int hiddenSize, int outputSize,
                                   double[] weights,
                                   double[][] inputNormParams,
                                   double[][] outputNormParams) {
        if (weights == null) {
            throw new IllegalArgumentException("Weights array cannot be null");
        }
        if (inputNormParams == null || inputNormParams.length != inputSize) {
            throw new IllegalArgumentException("Input normalization parameters are invalid");
        }
        if (outputNormParams == null || outputNormParams.length != outputSize) {
            throw new IllegalArgumentException("Output normalization parameters are invalid");
        }

        this.inputSize = inputSize;
        this.hiddenSize = hiddenSize;
        this.outputSize = outputSize;
        this.weights = weights;
        this.inputNormalizationParams = inputNormParams;
        this.outputNormalizationParams = outputNormParams;

        int ihCount = inputSize * hiddenSize;
        int hoCount = hiddenSize * outputSize;
        if (weights.length < ihCount + hoCount) {
            throw new IllegalArgumentException("Weights array is too short for the network configuration");
        }

        // Initialize weight matrices
        this.weightIH = new double[inputSize][hiddenSize];
        this.weightHO = new double[hiddenSize][outputSize];

        // Fill input -> hidden weights
        int idx = 0;
        for (int i = 0; i < inputSize; i++) {
            for (int h = 0; h < hiddenSize; h++) {
                weightIH[i][h] = weights[idx++];
            }
        }

        // Fill hidden -> output weights
        for (int h = 0; h < hiddenSize; h++) {
            for (int o = 0; o < outputSize; o++) {
                weightHO[h][o] = weights[idx++];
            }
        }
    }

    public double[] calculate(double[] input) {
        if (input == null || input.length != inputSize) {
            throw new IllegalArgumentException("Input array must have length " + inputSize);
        }

        // Normalize input
        double[] normInput = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double mean = inputNormalizationParams[i][0];
            double std = inputNormalizationParams[i][1];
            if (std == 0) {
                throw new IllegalArgumentException("Standard deviation for input feature " + i + " is zero");
            }
            normInput[i] = (input[i] - mean) / std;
        }

        // Compute hidden layer activations
        double[] hidden = new double[hiddenSize];
        for (int h = 0; h < hiddenSize; h++) {
            double sum = 0.0;
            for (int i = 0; i < inputSize; i++) {
                sum += normInput[i] * weightIH[i][h];
            }
            hidden[h] = sigmoid(sum);
        }

        // Compute output layer activations
        double[] outputNorm = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0.0;
            for (int h = 0; h < hiddenSize; h++) {
                sum += hidden[h] * weightHO[h][o];
            }
            outputNorm[o] = sigmoid(sum);
        }

        // Denormalize output
        double[] output = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double mean = outputNormalizationParams[o][0];
            double std = outputNormalizationParams[o][1];
            output[o] = outputNorm[o] * std + mean;
        }

        return output;
    }

    private static double sigmoid(double x) {
        return 1.0 / (1.0 + Math.exp(-x));
    }
}

