                weightIH[i][h] = weights[idx++];
            }
        }

        // Fill hidden → output weights
        for (int h = 0; h < hiddenSize; h++) {
            for (int o = 0; o < outputSize; o++) {
                weightHO[h][o] = weights[idx++];
            }
        }
