    /**
     * Normalizes the input array using min‑max scaling to the range [-1, 1].
     *
     * @param input the raw input values
     * @return a new array with each value scaled to [-1, 1]
     */
    private double[] normalizeInput(double[] input) {
        double[] norm = new double[inputSize];
        for (int i = 0; i < inputSize; i++) {
            double min = inputNormalizationParams[i][0];
            double max = inputNormalizationParams[i][1];
            if (max == min) {
                // Avoid division by zero; set to 0 (midpoint of [-1,1])
                norm[i] = 0.0;
            } else {
                norm[i] = 2.0 * (input[i] - min) / (max - min) - 1.0;
            }
        }
        return norm;
    }

    public double[] calculate(double[] input) {
        if (input == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        if (input.length != inputSize) {
            throw new IllegalArgumentException(
                "Input array length " + input.length +
                " does not match expected input size " + inputSize);
        }

        // Normalize input to [-1, 1]
        double[] normInput = normalizeInput(input);

        // Compute hidden layer activations
        double[] hidden = new double[hiddenSize];
        for (int h = 0; h < hiddenSize; h++) {
            double sum = 0.0;
            for (int i = 0; i < inputSize; i++) {
                sum += normInput[i] * weightIH[i][h];
            }
            hidden[h] = sigmoid(sum);
        }

        // Compute output layer activations
        double[] outputNorm = new double[outputSize];
        for (int o = 0; o < outputSize; o++) {
            double sum = 0.0;
            for (int h = 0; h < hiddenSize; h++) {
                sum += hidden[h] * weightHO[h][o];
            }
            outputNorm[o] = sigmoid(sum);
        }

        // Denormalize output
