import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

class DataProcessor {

    public static Map<String, Object> processEcommerceData(String categoriesJson, String cartJson) {
        // Prepare regex patterns
        Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]*)\"");
        Pattern quantityPattern = Pattern.compile("\"quantity\"\\s*:\\s*(\\d+)");

        // Extract category names
        List<String> categoryNames = new ArrayList<>();
        Matcher nameMatcher = namePattern.matcher(categoriesJson);
        while (nameMatcher.find()) {
            categoryNames.add(nameMatcher.group(1));
        }

        // Determine if any category name is empty
        boolean hasEmptyCategories = categoryNames.stream().anyMatch(String::isEmpty);

        // Compute lengths of each category name
        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Extract product quantities and compute total
        int totalCartItems = 0;
        Matcher quantityMatcher = quantityPattern.matcher(cartJson);
        while (quantityMatcher.find()) {
            totalCartItems += Integer.parseInt(quantityMatcher.group(1));
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryNames.size());
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }
}

