        if (catSuccessMatcher.find()) {
            catSuccess = "1".equals(catSuccessMatcher.group(1));
        }
        if (cartSuccessMatcher.find()) {
            cartSuccess = "1".equals(cartSuccessMatcher.group(1));
        }

        // If either success flag is not 1, return default result
        if (!catSuccess || !cartSuccess) {
            return defaultResult;
        }

        // Extract categories array
        List<String> categoryNames = new ArrayList<>();
        Pattern categoriesArrayPattern = Pattern.compile("\"categories\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher categoriesArrayMatcher = categoriesArrayPattern.matcher(categoriesJson);
        if (categoriesArrayMatcher.find()) {
            String categoriesContent = categoriesArrayMatcher.group(1);
            Pattern objectPattern = Pattern.compile("\\{[^}]*\\}");
            Matcher objectMatcher = objectPattern.matcher(categoriesContent);
            while (objectMatcher.find()) {
                String obj = objectMatcher.group();
                // Find name field
                Pattern namePattern = Pattern.compile("\"name\"\\s*:\\s*(null|\"([^\"]*)\")");
                Matcher nameMatcher = namePattern.matcher(obj);
                String name = "";
                if (nameMatcher.find()) {
                    if (!"null".equals(nameMatcher.group(1))) {
                        name = nameMatcher.group(2);
                    }
                }
                // If name field missing, treat as empty string
                categoryNames.add(name);
            }
        }

        // Determine if any category name is empty or if there are no categories
        boolean hasEmptyCategories = categoryNames.isEmpty() || categoryNames.stream().anyMatch(String::isEmpty);

        // Compute lengths of each category name
        List<Integer> categoryNameLengths = new ArrayList<>();
        for (String name : categoryNames) {
            categoryNameLengths.add(name.length());
        }

        // Extract products array and compute total quantity
        int totalCartItems = 0;
        Pattern productsArrayPattern = Pattern.compile("\"products\"\\s*:\\s*\\[(.*?)\\]", Pattern.DOTALL);
        Matcher productsArrayMatcher = productsArrayPattern.matcher(cartJson);
        if (productsArrayMatcher.find()) {
            String productsContent = productsArrayMatcher.group(1);
            Pattern objectPattern = Pattern.compile("\\{[^}]*\\}");
            Matcher objectMatcher = objectPattern.matcher(productsContent);
            while (objectMatcher.find()) {
                String obj = objectMatcher.group();
                // Find quantity field
                Pattern quantityPattern = Pattern.compile("\"quantity\"\\s*:\\s*(\\d+|null)");
                Matcher quantityMatcher = quantityPattern.matcher(obj);
                int quantity = 0;
                if (quantityMatcher.find()) {
                    if (!"null".equals(quantityMatcher.group(1))) {
                        quantity = Integer.parseInt(quantityMatcher.group(1));
                    }
                }
                // If quantity field missing, treat as 0
                totalCartItems += quantity;
            }
        }

        // Build result map
        Map<String, Object> result = new HashMap<>();
        result.put("categoryCount", categoryNames.size());
        result.put("totalCartItems", totalCartItems);
        result.put("categoryNames", categoryNames);
        result.put("hasEmptyCategories", hasEmptyCategories);
        result.put("categoryNameLengths", categoryNameLengths);

        return result;
    }

    /**
     * Very simple JSON format validator.
     * Checks that the string starts with '{', ends with '}', and that braces and quotes are balanced.
     *
     * @param json JSON string to validate.
     * @return true if the format looks valid, false otherwise.
     */
    private static boolean isValidJson(String json) {
        json = json.trim();
        if (json.isEmpty() || json.charAt(0) != '{' || json.charAt(json.length() - 1) != '}') {
            return false;
        }

        int braceCount = 0;
        boolean inQuote = false;
        for (int i = 0; i < json.length(); i++) {
            char c = json.charAt(i);
            if (c == '\\') {
                // Skip escaped character
                i++;
                continue;
            }
            if (c == '\"') {
                inQuote = !inQuote;
                continue;
            }
            if (!inQuote) {
                if (c == '{') {
                    braceCount++;
                } else if (c == '}') {
                    braceCount--;
                    if (braceCount < 0) {
                        return false;
                    }
                }
            }
        }
        return braceCount == 0 && !inQuote;
    }
