import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

class RegionTextureManager {
    private final Map<String, TexturePack> regionPacks = new HashMap<>();
    private TexturePack defaultPack;

    public RegionTextureManager(TexturePack defaultPack) {
        this.defaultPack = defaultPack;
    }

    /** Associates a texture pack with a region. */
    public void addRegionPack(String regionId, TexturePack pack) {
        regionPacks.put(regionId, pack);
    }

    /** Retrieves the texture pack for a region, falling back to the default pack. */
    public TexturePack getPackForRegion(String regionId) {
        return regionPacks.getOrDefault(regionId, defaultPack);
    }

    /** Removes the association for a region. */
    public void removeRegionPack(String regionId) {
        regionPacks.remove(regionId);
    }

    /** Returns an unmodifiable view of all region IDs that have a custom pack. */
    public Set<String> getAllRegionIds() {
        return Collections.unmodifiableSet(regionPacks.keySet());
    }

    /** Returns an unmodifiable view of the region‑to‑pack mapping. */
    public Map<String, TexturePack> getAllRegionPacks() {
        return Collections.unmodifiableMap(regionPacks);
    }

    /** Sets a new default pack. */
    public void setDefaultPack(TexturePack pack) {
        this.defaultPack = pack;
    }

    /** Returns the current default pack. */
    public TexturePack getDefaultPack() {
        return defaultPack;
    }
}

class TexturePack {
    private final String name;
    private final boolean isCustom;

    public TexturePack(String name, boolean isCustom) {
        this.name = name;
        this.isCustom = isCustom;
    }

    public String getName() {
        return name;
    }

    public boolean isCustom() {
        return isCustom;
    }

    @Override
    public String toString() {
        return "TexturePack{name='" + name + "', isCustom=" + isCustom + "}";
    }
}

/** Example usage of the RegionTextureManager. */
public class Main {
    public static void main(String[] args) {
        TexturePack defaultPack = new TexturePack("Default", false);
        RegionTextureManager manager = new RegionTextureManager(defaultPack);

        TexturePack desertPack = new TexturePack("Desert", true);
        TexturePack forestPack = new TexturePack("Forest", true);

        manager.addRegionPack("desert", desertPack);
        manager.addRegionPack("forest", forestPack);

        System.out.println("Desert pack: " + manager.getPackForRegion("desert"));
        System.out.println("Ocean pack (default): " + manager.getPackForRegion("ocean"));
    }
}

