     * Excludes or includes a player from automatic texture changes.
     *
     * @param playerId the unique identifier of the player
     * @param excluded true to exclude, false to include
     */
    public void setPlayerExcluded(String playerId, boolean excluded) {
        if (excluded) {
            excludedPlayers.add(playerId);
        } else {
            excludedPlayers.remove(playerId);
        }
    }

    /** Checks whether a player is excluded. */
    private boolean isExcluded(String playerId) {
        return excludedPlayers.contains(playerId);
    }

    /**
     * Handles a player's movement into a region.
     *
     * @param playerId the unique identifier of the player
     * @param regionId the identifier of the region the player moves into; may be null
     * @return a message indicating the action taken
     */
    public String handlePlayerMovement(String playerId, String regionId) {
        // 1. Exclusion check – highest priority
        if (isExcluded(playerId)) {
            return "Player " + playerId + " is excluded from automatic texture changes";
        }

        // 2. Resolve previous and new texture packs
        TexturePack previousPack = playerCurrentPack.get(playerId); // may be null (default)
        TexturePack newPack = regionId == null ? null : regionPacks.get(regionId); // null means default

        // 3. Special handling for custom texture packs
        boolean prevIsCustom = previousPack != null && previousPack.isCustom();
        boolean newIsCustom = newPack != null && newPack.isCustom();

        if (!prevIsCustom && newIsCustom) {
            // Entering a custom region – auto‑exclude and notify
            setPlayerExcluded(playerId, true);
            playerCurrentPack.put(playerId, newPack);
            return "NOTE: Player " + playerId + " entered custom region and is excluded from automatic changes";
