        if (newPack == null) {
            message = "Applied default texture pack to player " + playerId;
        } else {
            message = "Applied texture pack " + newPack.getName() + " to player " + playerId;
        }

        playerCurrentPack.put(playerId, newPack);
        return message;
    }
