import java.math.BigDecimal;
import java.math.RoundingMode;

class TaxPriceCalculator {

    /**
     * Calculates the price and tax amounts based on the total amount, tax rate, and whether the total includes tax.
     *
     * @param totalAmount   The total amount (either including or excluding tax).
     * @param taxRate       The tax rate as a percentage (e.g., 10 for 10%).
     * @param isTaxIncluded If true, the totalAmount includes tax; otherwise, it does not.
     * @return A BigDecimal array where index 0 is the price amount and index 1 is the tax amount.
     */
    public static BigDecimal[] calculatePriceAndTax(BigDecimal totalAmount, BigDecimal taxRate, boolean isTaxIncluded) {
        // Ensure non-null inputs
        if (totalAmount == null || taxRate == null) {
            throw new IllegalArgumentException("totalAmount and taxRate must not be null");
        }

        // Define scale and rounding mode for monetary calculations
        final int SCALE = 2;
        final RoundingMode ROUNDING = RoundingMode.HALF_UP;

        BigDecimal price;
        BigDecimal tax;

        if (!isTaxIncluded) {
            // Total amount does not include tax
            price = totalAmount.setScale(SCALE, ROUNDING);
            tax = totalAmount.multiply(taxRate).divide(BigDecimal.valueOf(100), SCALE, ROUNDING);
        } else {
            // Total amount includes tax
            BigDecimal divisor = BigDecimal.ONE.add(taxRate.divide(BigDecimal.valueOf(100), SCALE + 2, ROUNDING));
            price = totalAmount.divide(divisor, SCALE, ROUNDING);
            tax = totalAmount.subtract(price).setScale(SCALE, ROUNDING);
        }

        return new BigDecimal[]{price, tax};
    }
}

