import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class EnhancedBlockingQueue<T> {
    private final Queue<T> queue;
    private final int capacity;
    private final Lock lock = new ReentrantLock();
    private final Condition notFull  = lock.newCondition();
    private final Condition notEmpty = lock.newCondition();

    public EnhancedBlockingQueue(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        this.capacity = capacity;
        this.queue = new LinkedList<>();
    }

    /* Blocking put */
    public void put(T element) throws InterruptedException {
        lock.lock();
        try {
            while (queue.size() == capacity) {
                notFull.await();
            }
            queue.add(element);
            notEmpty.signal(); // wake one waiting taker
        } finally {
            lock.unlock();
        }
    }

    /* Blocking take */
    public T take() throws InterruptedException {
        lock.lock();
        try {
            while (queue.isEmpty()) {
                notEmpty.await();
            }
            T item = queue.remove();
            notFull.signal(); // wake one waiting putter
            return item;
        } finally {
            lock.unlock();
        }
    }

    /* Timed offer */
    public boolean offer(T element, long timeout, TimeUnit unit) throws InterruptedException {
        long nanos = unit.toNanos(timeout);
        lock.lock();
        try {
            while (queue.size() == capacity) {
                if (nanos <= 0L) {
                    return false; // timeout elapsed
                }
                nanos = notFull.awaitNanos(nanos);
            }
            queue.add(element);
            notEmpty.signal(); // wake one waiting taker
            return true;
        } finally {
            lock.unlock();
        }
    }

    /* Timed poll */
    public T poll(long timeout, TimeUnit unit) throws InterruptedException {
        long nanos = unit.toNanos(timeout);
        lock.lock();
        try {
            while (queue.isEmpty()) {
                if (nanos <= 0L) {
                    return null; // timeout elapsed
                }
                nanos = notEmpty.awaitNanos(nanos);
            }
            T item = queue.remove();
            notFull.signal(); // wake one waiting putter
            return item;
        } finally {
            lock.unlock();
        }
    }

    /* Non‑blocking peek */
    public T peek() {
        lock.lock();
        try {
            return queue.isEmpty() ? null : queue.peek();
        } finally {
            lock.unlock();
        }
    }

    /* Non‑blocking size */
    public int size() {
        lock.lock();
        try {
            return queue.size();
        } finally {
            lock.unlock();
        }
    }

    /* Non‑blocking remaining capacity */
    public int remainingCapacity() {
        lock.lock();
        try {
            return capacity - queue.size();
        } finally {
            lock.unlock();
        }
    }

    /* Non‑blocking clear – returns number of removed elements */
    public int clear() {
        lock.lock();
        try {
            int removed = queue.size();
            queue.clear();
            notFull.signalAll(); // wake any waiting putters
            return removed;
        } finally {
            lock.unlock();
        }
    }
}

