import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * A thread‑safe generic key‑value store that tracks access counts and
 * the last access time for each key.
 *
 * @param <K> the type of keys maintained by this store
 * @param <V> the type of mapped values
 */
public class KeyValueStore<K, V> {

    // Concurrent map for key‑value pairs
    private final ConcurrentHashMap<K, V> store = new ConcurrentHashMap<>();

    // Concurrent map for access counts (key → number of get() calls)
    private final ConcurrentHashMap<K, AtomicInteger> accessCounts = new ConcurrentHashMap<>();

    // Concurrent map for last access times (key → epoch millis)
    private final ConcurrentHashMap<K, Long> lastAccessTime = new ConcurrentHashMap<>();

    /**
     * Stores the specified key‑value pair in the store.
     *
     * @param key   the key with which the specified value is to be associated
     * @param value the value to be associated with the specified key
     * @throws IllegalArgumentException if the key is {@code null}
     */
    public void put(K key, V value) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        store.put(key, value);
    }

    /**
     * Retrieves the value associated with the specified key and updates
     * the access count and last access time for that key.
     *
     * @param key the key whose associated value is to be returned
     * @return the value associated with the specified key, or {@code null}
     *         if no mapping exists
     * @throws IllegalArgumentException if the key is {@code null}
     */
    public V get(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        // Increment access count atomically
        accessCounts.computeIfAbsent(key, k -> new AtomicInteger(0)).incrementAndGet();

        // Update last access time
        lastAccessTime.put(key, System.currentTimeMillis());

        return store.get(key);
    }

    /**
     * Returns how many times the specified key has been accessed via {@link #get(Object)}.
     *
     * @param key the key whose access count is requested
     * @return the number of times {@code get(key)} has been called; {@code 0} if the key
     *         has never been accessed or does not exist
     * @throws IllegalArgumentException if the key is {@code null}
     */
    public int getAccessCount(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        AtomicInteger count = accessCounts.get(key);
        return count == null ? 0 : count.get();
    }

    /**
     * Returns the last access time for the specified key in milliseconds since the epoch.
     *
     * @param key the key whose last access time is requested
     * @return the last access time in milliseconds since epoch, or {@code 0} if the key
     *         has never been accessed
     * @throws IllegalArgumentException if the key is {@code null}
     */
    public long getLastAccessTime(K key) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }

        Long time = lastAccessTime.get(key);
        return time == null ? 0L : time;
    }
}

