     */
    public Statistics computeStatistics() {
        int totalEntries = store.size();

        // Find key with maximum access count
        K keyWithMaxAccess = null;
        int maxAccess = -1;
        for (Map.Entry<K, AtomicInteger> entry : accessCounts.entrySet()) {
            int count = entry.getValue().get();
            if (count > maxAccess) {
                maxAccess = count;
                keyWithMaxAccess = entry.getKey();
            }
        }

        // Copy type distribution
        Map<Class<?>, Integer> typeDistribution = new HashMap<>();
        for (Map.Entry<Class<?>, AtomicInteger> entry : typeCounts.entrySet()) {
            typeDistribution.put(entry.getKey(), entry.getValue().get());
        }

        // Rough estimate of memory usage: 64 bytes per entry (key + value + overhead)
        long estimatedMemoryUsage = totalEntries * 64L;

        return new Statistics(totalEntries, keyWithMaxAccess, typeDistribution, estimatedMemoryUsage);
    }

