     * Returns all keys whose associated values are instances of the specified type.
     *
     * @param type the {@link Class} object representing the type to search for
     * @return a {@link Set} of keys whose values are instances of {@code type};
     *         an empty set if no such keys exist
     * @throws IllegalArgumentException if {@code type} is {@code null}
     */
    public Set<K> findKeysByType(Class<?> type) {
        if (type == null) {
            throw new IllegalArgumentException("Type cannot be null");
        }

        Set<K> result = new HashSet<>();
        for (Map.Entry<K, V> entry : store.entrySet()) {
            V value = entry.getValue();
            if (value != null && type.isInstance(value)) {
                result.add(entry.getKey());
            }
        }
        return result;
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods for type count manipulation                           */
    /* --------------------------------------------------------------------- */

    private void incrementTypeCount(Class<?> cls) {
        typeCounts.computeIfAbsent(cls, k -> new AtomicInteger(0)).incrementAndGet();
    }

    private void decrementTypeCount(Class<?> cls) {
        typeCounts.computeIfPresent(cls, (k, ai) -> {
            int newVal = ai.decrementAndGet();
            return newVal == 0 ? null : ai; // remove entry if count reaches zero
        });
    }

    /* --------------------------------------------------------------------- */
    /* Statistics data holder                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Immutable holder for statistics computed by {@link #computeStatistics()}.
     */
    public static class Statistics {
        private final int totalEntries;
        private final Object keyWithMaxAccess;
        private final Map<Class<?>, Integer> typeDistribution;
        private final long estimatedMemoryUsage;

        public Statistics(int totalEntries,
                          Object keyWithMaxAccess,
                          Map<Class<?>, Integer> typeDistribution,
                          long estimatedMemoryUsage) {
            this.totalEntries = totalEntries;
            this.keyWithMaxAccess = keyWithMaxAccess;
            this.typeDistribution = new HashMap<>(typeDistribution);
            this.estimatedMemoryUsage = estimatedMemoryUsage;
        }

        public int getTotalEntries() {
            return totalEntries;
        }

        public Object getKeyWithMaxAccess() {
            return keyWithMaxAccess;
        }

        public Map<Class<?>, Integer> getTypeDistribution() {
            return new HashMap<>(typeDistribution);
        }

        public long getEstimatedMemoryUsage() {
            return estimatedMemoryUsage;
        }
    }
}

