class WebSocketMessageHandler {
    private final Map<String, Consumer<Map<String, Object>>> messageHandlers;
    private final BiConsumer<String, String> errorLogger;

    public WebSocketMessageHandler(BiConsumer<String, String> errorLogger) {
        this.messageHandlers = new HashMap<>();
        this.errorLogger = errorLogger;
    }

    /**
     * Registers a handler for a specific message type.
     *
     * @param messageType the type of the message (e.g., "chat", "ping")
     * @param handler     the consumer that will process the message data
     */
    public void addMessageHandler(String messageType, Consumer<Map<String, Object>> handler) {
        messageHandlers.put(messageType, handler);
    }

    /**
     * Removes the handler for the given message type.
     *
     * @param messageType the type of the message to remove
     * @return true if a handler was removed, false otherwise
     */
    public boolean removeMessageHandler(String messageType) {
        return messageHandlers.remove(messageType) != null;
    }

    /**
     * Processes an incoming message by looking up the handler for its type.
     * Validates that the message type is not null/empty and that the message data is not null.
     *
     * @param messageType the type of the incoming message
     * @param messageData the payload of the message
     * @return true if a handler was found and executed, false otherwise
     */
    public boolean processMessage(String messageType, Map<String, Object> messageData) {
        // Validation
        if (messageType == null || messageType.isEmpty() || messageData == null) {
            if (errorLogger != null) {
                errorLogger.accept("ValidationError",
                        "Invalid message: type=" + messageType + ", data=" + messageData);
            }
            return false;
        }

        Consumer<Map<String, Object>> handler = messageHandlers.get(messageType);
        if (handler != null) {
            handler.accept(messageData);
            return true;
        } else {
            // Log an error if no handler is registered for this message type
            if (errorLogger != null) {
                errorLogger.accept("NoHandler",
                        "Message type: " + messageType);
            }
            return false;
        }
    }

    // Demo usage
    public static void main(String[] args) {
        // Simple error logger that prints to console
        BiConsumer<String, String> logger = (level, msg) -> System.err.println("[" + level + "] " + msg);

        WebSocketMessageHandler handler = new WebSocketMessageHandler(logger);

        // Register a handler for "chat" messages
        handler.addMessageHandler("chat", data -> {
            String user = (String) data.getOrDefault("user", "unknown");
            String text = (String) data.getOrDefault("text", "");
            System.out.println(user + " says: " + text);
