        // Register a handler for "ping" messages
        handler.addMessageHandler("ping", data -> System.out.println("Received ping!"));

        // Simulate receiving a chat message
        Map<String, Object> chatMsg = new HashMap<>();
        chatMsg.put("user", "Alice");
        chatMsg.put("text", "Hello, world!");
        handler.processMessage("chat", chatMsg);

        // Simulate receiving a ping message
        handler.processMessage("ping", Collections.emptyMap());

        // Simulate receiving an unknown message type
        handler.processMessage("unknown", Collections.emptyMap());

        // Simulate validation failures
        handler.processMessage(null, chatMsg);          // null type
        handler.processMessage("", chatMsg);           // empty type
        handler.processMessage("chat", null);          // null data
    }
