/**
 * A simple authentication service that allows user registration and authentication.
 */
public class AuthenticationService {

    // Stores username -> password mappings
    private final Map<String, String> credentials = new HashMap<>();

    /**
     * Registers a new user with the given username and password.
     *
     * @param username the desired username
     * @param password the desired password
     * @return true if registration succeeded, false if the username is already taken
     */
    public boolean registerUser(String username, String password) {
        if (username == null || password == null) {
            return false;
        }
        synchronized (credentials) {
            if (credentials.containsKey(username)) {
                return false; // Username already exists
            }
            credentials.put(username, password);
            return true;
        }
    }

    /**
     * Authenticates a user with the given username and password.
     *
     * @param username the username to authenticate
     * @param password the password to verify
     * @return true if the credentials match an existing user, false otherwise
     */
    public boolean authenticate(String username, String password) {
        if (username == null || password == null) {
            return false;
        }
        synchronized (credentials) {
            String storedPassword = credentials.get(username);
            return password.equals(storedPassword);
        }
    }
}

