    /**
     * Returns the in-order successor of the given node in a binary tree that
     * contains parent pointers.
     *
     * @param node the node whose successor is to be found
     * @return the in-order successor node, or {@code null} if none exists
     * @throws IllegalArgumentException if {@code node} is {@code null}
     */
    public static BinaryTreeNode findNextNode(BinaryTreeNode node) {
