            throw new IllegalArgumentException("Input node cannot be null");
        }

        // Case 1: Node has a right child – successor is the leftmost node
        // in the right subtree.
        if (node.right != null) {
            BinaryTreeNode current = node.right;
            while (current.left != null) {
                current = current.left;
            }
            return current;
        }

        // Case 2: No right child – walk up using parent pointers until we
        // find an ancestor where the current node is a left child.
        BinaryTreeNode current = node;
        while (current.parent != null && current == current.parent.right) {
            current = current.parent;
        }

        // If current.parent is null, the node is the rightmost node in the tree.
        return current.parent;
    }

    /**
     * Builds a binary tree from an array of nodes and a list of parent-child
     * relationships.
     *
     * @param nodes          array of {@link BinaryTreeNode} objects; the first
     *                       element (index 0) is the root
     * @param relationships  2‑D array where each entry is
     *                       {@code [parentIndex, childIndex, 'L'/'R']}. The
     *                       third element is stored as an {@code int} whose
     *                       value is the ASCII code of the character 'L' or 'R'.
     * @return the root node of the constructed tree
     * @throws IllegalArgumentException if {@code nodes} is {@code null} or empty,
     *                                  or if any index in {@code relationships}
     *                                  is out of bounds
     */
    public static BinaryTreeNode buildTree(BinaryTreeNode[] nodes, int[][] relationships) {
        if (nodes == null || nodes.length == 0) {
            throw new IllegalArgumentException(
                "Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid."
            );
        }

        // If relationships is null or empty, simply return the root.
        if (relationships == null || relationships.length == 0) {
            return nodes[0];
        }

        for (int[] rel : relationships) {
            if (rel == null || rel.length < 3) {
                throw new IllegalArgumentException(
                    "Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid."
                );
            }

            int parentIdx = rel[0];
            int childIdx = rel[1];
            char dir = (char) rel[2];

            if (parentIdx < 0 || parentIdx >= nodes.length ||
                childIdx < 0 || childIdx >= nodes.length) {
                throw new IllegalArgumentException(
                    "Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid."
                );
            }

            BinaryTreeNode parent = nodes[parentIdx];
            BinaryTreeNode child = nodes[childIdx];

            if (dir == 'L') {
                parent.left = child;
            } else if (dir == 'R') {
                parent.right = child;
            } else {
                // If an unexpected direction character is encountered, treat it as invalid.
                throw new IllegalArgumentException(
                    "Invalid input: nodes array must be non-null and non-empty, and all indices in relationships must be valid."
                );
            }

            child.parent = parent;
        }

        // Ensure the root has no parent.
        nodes[0].parent = null;
        return nodes[0];
    }
