public class ThreadManager {

    public ThreadStatistics manageThreads(int threadCount,
                                          long workDurationMs,
                                          long interruptAfterMs) {
        List<Thread> workers = new ArrayList<>();
        AtomicInteger completedTasks = new AtomicInteger(0);
        AtomicInteger interruptedTasks = new AtomicInteger(0);

        // Create and start worker threads
        for (int i = 0; i < threadCount; i++) {
            Thread worker = new Thread(() -> {
                System.out.println(Thread.currentThread().getName() + " started");
                try {
                    Thread.sleep(workDurationMs);
                    completedTasks.incrementAndGet(); // successful completion
                } catch (InterruptedException e) {
                    interruptedTasks.incrementAndGet(); // interrupted during sleep
                }
            }, "Worker-" + i);
            workers.add(worker);
            worker.start();
        }

        // Optional: start a thread that will interrupt all workers after a delay
        Thread interrupter = null;
        if (interruptAfterMs > 0) {
            interrupter = new Thread(() -> {
                try {
                    Thread.sleep(interruptAfterMs);
                } catch (InterruptedException ignored) {
                }
                for (Thread w : workers) {
                    w.interrupt();
                }
            }, "Interrupter");
            interrupter.start();
        }

        // Wait for all workers to finish
        for (Thread w : workers) {
            try {
                w.join();
            } catch (InterruptedException ignored) {
            }
        }

        // Wait for the interrupter to finish (if it was started)
        if (interrupter != null) {
            try {
                interrupter.join();
            } catch (InterruptedException ignored) {
            }
        }

        return new ThreadStatistics(threadCount,
