import java.util.HashMap;
import java.util.Map;

/**
 * Definition for a binary tree node.
 */
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

/**
 * TreeAnalyzer provides analysis utilities for binary trees.
 */
public class TreeAnalyzer {

    /**
     * Analyzes the given binary tree and returns a map containing the total node count.
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with a single entry: key "nodeCount" -> total number of nodes
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();
        int count = countNodes(root);
        result.put("nodeCount", count);
        return result;
    }

    /**
     * Recursively counts the number of nodes in the binary tree.
     *
     * @param node the current node
     * @return the number of nodes in the subtree rooted at node
     */
    private int countNodes(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + countNodes(node.left) + countNodes(node.right);
    }
}

