     * @return a map with the analysis results
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();
        if (root == null) {
            result.put("nodeCount", 0);
            result.put("maxDiff", 0);
            result.put("minDiff", 0);
            return result;
        }

        ResultHelper helper = new ResultHelper();
        helper.traverse(root, root.val, root.val);

        // For a single node tree, minDiff should be 0
        if (helper.nodeCount <= 1) {
            helper.minDiff = 0;
        }

        result.put("nodeCount", helper.nodeCount);
        result.put("maxDiff", helper.maxDiff);
        result.put("minDiff", helper.minDiff);
        return result;
    }

    /**
     * Helper class to store intermediate results during traversal.
     */
    private static class ResultHelper {
        int nodeCount = 0;
        int maxDiff = 0;
        int minDiff = Integer.MAX_VALUE;
        TreeSet<Integer> ancestors = new TreeSet<>();

        void traverse(TreeNode node, int currentMin, int currentMax) {
            if (node == null) {
                return;
            }

            // Update node count
            nodeCount++;

            // Update max difference using current node value and path min/max
            int diffWithMin = Math.abs(node.val - currentMin);
            int diffWithMax = Math.abs(node.val - currentMax);
            maxDiff = Math.max(maxDiff, Math.max(diffWithMin, diffWithMax));

            // Update min difference using nearest ancestor values
            Integer lower = ancestors.floor(node.val);
            Integer higher = ancestors.ceiling(node.val);
            if (lower != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - lower));
            }
            if (higher != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - higher));
            }

            // Add current node to ancestors set
            ancestors.add(node.val);

            // Update min and max for the path to children
            int newMin = Math.min(currentMin, node.val);
            int newMax = Math.max(currentMax, node.val);

            // Recurse on children
            traverse(node.left, newMin, newMax);
            traverse(node.right, newMin, newMax);

            // Remove current node after exploring its subtrees
            ancestors.remove(node.val);
        }
    }
}

