import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeSet;

/**
 * Definition for a binary tree node.
 */
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

/**
 * TreeAnalyzer provides analysis utilities for binary trees.
 */
public class TreeAnalyzer {

    /**
     * Analyzes the given binary tree and returns a map containing:
     * - "nodeCount": total number of nodes in the tree
     * - "maxDiff": maximum absolute difference between any ancestor and descendant values
     * - "minDiff": minimum absolute difference between any ancestor and descendant values
     * - "avgDiff": floor of (sum of all ancestor differences / total node count)
     *
     * @param root the root of the binary tree (may be null)
     * @return a map with the analysis results
     */
    public Map<String, Integer> analyzeTree(TreeNode root) {
        Map<String, Integer> result = new HashMap<>();

        if (root == null) {
            result.put("nodeCount", 0);
            result.put("maxDiff", 0);
            result.put("minDiff", 0);
            result.put("avgDiff", 0);
            return result;
        }

        ResultHelper helper = new ResultHelper();
        helper.traverse(root, root.val, root.val);

        int nodeCount = helper.nodeCount;
        int maxDiff = helper.maxDiff;
        int minDiff = helper.minDiff;
        long sumDiffTotal = helper.sumDiffTotal;
        int avgDiff = nodeCount > 0 ? (int) (sumDiffTotal / nodeCount) : 0;

        if (nodeCount <= 1) {
            minDiff = 0;
        }

        result.put("nodeCount", nodeCount);
        result.put("maxDiff", maxDiff);
        result.put("minDiff", minDiff);
        result.put("avgDiff", avgDiff);
        return result;
    }

    /**
     * Helper class to store intermediate results during traversal.
     */
    private static class ResultHelper {
        int nodeCount = 0;
        int maxDiff = 0;
        int minDiff = Integer.MAX_VALUE;
        long sumDiffTotal = 0;

        // For minDiff calculation
        TreeSet<Integer> ancestorsSet = new TreeSet<>();

        // For sum of differences calculation
        ArrayList<Integer> ancestorsList = new ArrayList<>();

        void traverse(TreeNode node, int currentMin, int currentMax) {
            if (node == null) {
                return;
            }

            // Update node count
            nodeCount++;

            // Update max difference
            int diffWithMin = Math.abs(node.val - currentMin);
            int diffWithMax = Math.abs(node.val - currentMax);
            maxDiff = Math.max(maxDiff, Math.max(diffWithMin, diffWithMax));

            // Update min difference
            Integer lower = ancestorsSet.floor(node.val);
            Integer higher = ancestorsSet.ceiling(node.val);
            if (lower != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - lower));
            }
            if (higher != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - higher));
            }

            // Compute sum of differences with all ancestors
            long sumDiffNode = 0;
            for (int anc : ancestorsList) {
                sumDiffNode += Math.abs(node.val - anc);
            }
            sumDiffTotal += sumDiffNode;

            // Add current node to ancestor structures
            ancestorsSet.add(node.val);
            ancestorsList.add(node.val);

            // Update min and max for children
            int newMin = Math.min(currentMin, node.val);
            int newMax = Math.max(currentMax, node.val);

            // Recurse on children
            traverse(node.left, newMin, newMax);
            traverse(node.right, newMin, newMax);

            // Remove current node after exploring
            ancestorsSet.remove(node.val);
            ancestorsList.remove(ancestorsList.size() - 1);
        }
    }
}

