            Integer higher = ancestorsSet.ceiling(node.val);
            if (lower != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - lower));
            }
            if (higher != null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - higher));
            }

            // Compute sum of differences with all ancestors
            long sumDiffNode = 0;
            for (int anc : ancestorsList) {
                sumDiffNode += Math.abs(node.val - anc);
            }
            sumDiffTotal += sumDiffNode;

            // Add current node to ancestor structures
            ancestorsSet.add(node.val);
            ancestorsList.add(node.val);

            // Update min and max for children
            int newMin = Math.min(currentMin, node.val);
            int newMax = Math.max(currentMax, node.val);

            // Recurse on children
            traverse(node.left, newMin, newMax);
            traverse(node.right, newMin, newMax);

            // Remove current node after exploring
            ancestorsSet.remove(node.val);
            ancestorsList.remove(ancestorsList.size() - 1);
        }
    }
}
