public class StringProcessor {

    public static String processString(String input) {
        // Step 1: Handle null or empty input
        if (input == null || input.isEmpty()) {
            return "Empty";
        }

        // Step 2: Remove all non-letter characters
        StringBuilder lettersOnly = new StringBuilder();
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isLetter(ch)) {
                lettersOnly.append(ch);
            }
        }

        // If no letters remain, return "Empty"
        if (lettersOnly.length() == 0) {
            return "Empty";
        }

        // Step 3: Convert to title case (first letter uppercase, rest lowercase)
        char firstChar = Character.toUpperCase(lettersOnly.charAt(0));
        String rest = lettersOnly.substring(1).toLowerCase();
        String titleCase = firstChar + rest;

        // Step 4: Reverse if length > 5
        if (titleCase.length() > 5) {
            titleCase = new StringBuilder(titleCase).reverse().toString();
        }

        // Step 5: Apply length-based markers
        int len = titleCase.length();
        if (len == 0) {
            return "Empty";
        } else if (len < 3) {
            return "Short_" + titleCase;
        } else if (len <= 5) {
            return titleCase + "_Medium";
        } else { // len >= 6
            return "Long_" + titleCase + "_Processed";
        }
    }
}

