    /**
     * Writes each string from the list as a separate line to the specified file using UTF-8 encoding.
     *
     * @param filePath the path of the file to write to
     * @param lines    the list of strings to write
     * @param append   if true, the content is appended to the file; otherwise the file is overwritten
     * @return true if the operation succeeds, false otherwise
     */
    public boolean writeToFile(String filePath, List<String> lines, boolean append) {
        Path path = Paths.get(filePath);
        try {
            // Ensure parent directories exist
            Path parent = path.getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }

            // Determine open options
            StandardOpenOption[] options = append
                    ? new StandardOpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND}
                    : new StandardOpenOption[]{StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.TRUNCATE_EXISTING};

            try (BufferedWriter writer = Files.newBufferedWriter(path, StandardCharsets.UTF_8, options)) {
                for (String line : lines) {
                    writer.write(line);
                    writer.newLine();
                }
            }
            return true;
        } catch (IOException e) {
            return false;
        }
    }
