    public ChatMessageProcessor() {
        this.userMessages = new HashMap<>();
        this.activeUsers = new ArrayList<>();
    }

    /**
     * Adds a user to the active users list.
     *
     * @param username the name of the user joining
     * @return a list of notifications; if the username is already taken,
     *         the list contains the error message "Error: Username <username> is already taken".
     *         Otherwise, the list is empty.
     */
    public List<String> userJoins(String username) {
        if (activeUsers.contains(username)) {
            return Collections.singletonList(
                "Error: Username " + username + " is already taken");
        }
        activeUsers.add(username);
        userMessages.putIfAbsent(username, new ArrayList<>());
        return Collections.emptyList();
    }

    /**
     * Removes a user from the active users list.
     *
     * @param username the name of the user leaving
     * @return a list of notifications. If the user does not exist, the list contains
     *         the error message "Error: User <username> not found". Otherwise, the list
     *         contains the message "[Server] - <username> has left" repeated for each
     *         remaining active user.
     */
    public List<String> userLeaves(String username) {
        if (!activeUsers.contains(username)) {
            return Collections.singletonList(
                "Error: User " + username + " not found");
        }

        // Remove the user from active users and their message history
        activeUsers.remove(username);
        userMessages.remove(username);

        // Prepare the notification message
        String notification = "[Server] - " + username + " has left";

        // Notify all remaining users
        List<String> notifications = new ArrayList<>();
        for (String remainingUser : activeUsers) {
            notifications.add(notification);
        }

        return notifications;
    }

    /**
     * Processes a message sent by a user.
     *
     * @param sender  the username of the sender
     * @param message the message content
     * @return a list of delivered messages. If the sender is not active, the list
     *         contains the error message "Error: User <sender> is not active".
     *         Otherwise, the message "[<sender>] <message>" is delivered to all
     *         other active users and the list of delivered messages is returned.
     */
    public List<String> processMessage(String sender, String message) {
        if (!activeUsers.contains(sender)) {
            return Collections.singletonList(
                "Error: User " + sender + " is not active");
        }

        String formattedMessage = "[" + sender + "] " + message;
