class BSTValidator {
    /* ---------- Standard BST validation (recursive with bounds) ---------- */
    public static boolean isValidBST(BSTNode root) {
        return isValidBST(root, null, null);
    }

    // Recursive helper that uses Integer bounds.
    // `lower` is exclusive, `upper` is inclusive.
    private static boolean isValidBST(BSTNode node, Integer lower, Integer upper) {
        if (node == null) {
            return true; // An empty subtree is always valid
        }

        // Check against the lower bound (exclusive)
        if (lower != null && node.value <= lower) {
            return false;
        }

        // Check against the upper bound (inclusive)
        if (upper != null && node.value > upper) {
            return false;
        }

        // Validate left subtree: all values <= node.value
        if (!isValidBST(node.left, lower, node.value)) {
            return false;
        }

        // Validate right subtree: all values > node.value
        if (node.value == Integer.MAX_VALUE) {
            // No integer can be greater than Integer.MAX_VALUE
            if (node.right != null) {
                return false;
            }
        } else {
            if (!isValidBST(node.right, node.value + 1, upper)) {
                return false;
            }
        }

        return true;
    }

