     * are processed recursively.
     *
     * @param tree   the BinaryTree to insert into
     * @param sorted the sorted list of elements
     * @param start  start index of the current sublist
     * @param end    end index of the current sublist
     */
    private void loadBalanced(BinaryTree<T> tree, List<T> sorted, int start, int end) {
        if (start > end) {
            return;
        }
        int mid = start + (end - start) / 2;
        tree.insert(sorted.get(mid));
        loadBalanced(tree, sorted, start, mid - 1);
        loadBalanced(tree, sorted, mid + 1, end);
    }
