     * @param count  the number of messages to generate
     * @throws InterruptedException if the thread is interrupted during queue operations
     *                               or sleep; the interrupt status is preserved.
     */
    public void sendMessages(String prefix, int count) throws InterruptedException {
        // Clear the list of sent messages at the start
        sentMessages.clear();

        for (int i = 1; i <= count; i++) {
            String message = prefix + " " + i;
            boolean offered = false;
            int attempts = 0;

            while (!offered && attempts <= maxRetries) {
                try {
                    offered = messageQueue.offer(message, 100, TimeUnit.MILLISECONDS);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); // preserve interrupt status
                    throw e; // propagate the interruption
                }

                if (!offered) {
                    attempts++;
                    if (attempts <= maxRetries) {
                        try {
                            Thread.sleep(retryDelayMillis);
                        } catch (InterruptedException e) {
                            Thread.currentThread().interrupt(); // preserve interrupt status
                            throw e; // propagate the interruption
                        }
                    }
                }
            }

            if (offered) {
                // Record the message only if it was successfully queued
                sentMessages.add(message);
            } else {
                // All attempts failed – report the failure
                System.err.println("Failed to send message after " + attempts + " attempts: " + message);
            }
        }
    }

    /**
     * Returns the internal message queue.
     *
     * @return the LinkedBlockingQueue containing the messages
     */
    public LinkedBlockingQueue<String> getMessageQueue() {
        return messageQueue;
    }

    // Optional getters for configuration values
    public int getMaxRetries() {
        return maxRetries;
    }

    public long getRetryDelayMillis() {
        return retryDelayMillis;
    }

    public List<String> getSentMessages() {
        return Collections.unmodifiableList(sentMessages);
    }
}
