            throw new IllegalArgumentException("minOctave cannot be greater than maxOctave");
        }
        this.minOctave = minOctave;
        this.maxOctave = maxOctave;
        this.currentOctave = clamp(initialOctave, minOctave, maxOctave);
    }

    /**
     * Returns the current octave.
     *
     * @return the current octave
     */
    public int getCurrentOctave() {
        return currentOctave;
    }

    /**
     * Increases the current octave by 1 if it does not exceed {@code maxOctave}.
     *
     * @return {@code true} if the octave was increased, {@code false} otherwise
     */
    public boolean incrementOctave() {
        if (currentOctave < maxOctave) {
            setCurrentOctave(currentOctave + 1);
            return true;
        }
        return false;
    }

    /**
     * Decreases the current octave by 1 if it does not go below {@code minOctave}.
     *
     * @return {@code true} if the octave was decreased, {@code false} otherwise
     */
    public boolean decrementOctave() {
        if (currentOctave > minOctave) {
            setCurrentOctave(currentOctave - 1);
            return true;
        }
        return false;
    }

    /**
     * Adds a listener that will be notified when the octave changes.
     *
     * @param listener the listener to add
     */
    public void addListener(OctaveChangeListener listener) {
        if (listener != null && !listeners.contains(listener)) {
            listeners.add(listener);
        }
    }

    /**
     * Removes a previously added listener.
     *
     * @param listener the listener to remove
     */
    public void removeListener(OctaveChangeListener listener) {
        listeners.remove(listener);
    }

    /**
     * Private helper that updates the current octave and notifies listeners.
     *
     * @param newOctave the new octave value
     */
    private void setCurrentOctave(int newOctave) {
        int oldOctave = currentOctave;
        currentOctave = newOctave;
        notifyListeners(oldOctave, newOctave);
    }

    /**
     * Notifies all registered listeners of an octave change.
     *
     * @param oldOctave the previous octave value
     * @param newOctave the new octave value
     */
    private void notifyListeners(int oldOctave, int newOctave) {
        for (OctaveChangeListener listener : listeners) {
            listener.octaveChanged(oldOctave, newOctave);
        }
    }

    /**
     * Utility method to clamp a value between min and max inclusive.
     */
    private int clamp(int value, int min, int max) {
        if (value < min) return min;
        if (value > max) return max;
        return value;
    }

    /**
     * Listener interface for octave change events.
     */
    public interface OctaveChangeListener {
        void octaveChanged(int oldOctave, int newOctave);
    }

    // Optional demonstration
    public static void main(String[] args) {
        PianoOctaveManager manager = new PianoOctaveManager(4, 0, 8);
        manager.addListener((old, newVal) -> System.out.println("Octave changed from " + old + " to " + newVal));

        System.out.println("Initial octave: " + manager.getCurrentOctave()); // 4
        manager.incrementOctave(); // 5
        manager.decrementOctave(); // 4

        manager.setCurrentOctave(10); // will clamp to 8
        System.out.println("After clamped set: " + manager.getCurrentOctave()); // 8
    }
}

