     * Performs an enhanced match between two datasets based on specified key indices.
     *
     * @param dataset1     the first dataset, a list of string arrays
     * @param dataset2     the second dataset, a list of string arrays
     * @param matchStrategy the matching strategy (currently only 1 = exact match is supported)
     * @param keyIndices   the indices of the fields to use as keys for matching
     * @return a map containing three entries:
     *         "matched"   -> list of concatenated matched records
     *         "unmatched1" -> list of records from dataset1 that had no match
     *         "unmatched2" -> list of records from dataset2 that had no match
     */
    public Map<String, List<String[]>> enhancedMatch(
            List<String[]> dataset1,
            List<String[]> dataset2,
            int matchStrategy,
            int[] keyIndices) {

        Map<String, List<String[]>> result = new HashMap<>();
        List<String[]> matched = new ArrayList<>();
        List<String[]> unmatched1 = new ArrayList<>();
        List<String[]> unmatched2 = new ArrayList<>();

        // Only exact matching is implemented for now
        if (matchStrategy != 1) {
            // If strategy is not supported, treat all records as unmatched
            unmatched1.addAll(dataset1);
            unmatched2.addAll(dataset2);
            result.put("matched", matched);
            result.put("unmatched1", unmatched1);
            result.put("unmatched2", unmatched2);
            return result;
        }

        // Build key maps for both datasets
        Map<String, List<String[]>> map1 = buildKeyMap(dataset1, keyIndices);
        Map<String, List<String[]>> map2 = buildKeyMap(dataset2, keyIndices);

        // Process matches
        for (Map.Entry<String, List<String[]>> entry : map1.entrySet()) {
            String key = entry.getKey();
            List<String[]> list1 = entry.getValue();
            List<String[]> list2 = map2.get(key);

            if (list2 != null) {
                int matchCount = Math.min(list1.size(), list2.size());

                // Pair up records
                for (int i = 0; i < matchCount; i++) {
                    String[] combined = concatenateArrays(list1.get(i), list2.get(i));
                    matched.add(combined);
                }

                // Remaining unmatched from dataset1
                for (int i = matchCount; i < list1.size(); i++) {
                    unmatched1.add(list1.get(i));
                }

                // Remaining unmatched from dataset2
                for (int i = matchCount; i < list2.size(); i++) {
                    unmatched2.add(list2.get(i));
                }
            } else {
                // No match for any record in this key
                unmatched1.addAll(list1);
            }
        }

        // Any keys in dataset2 that were not processed yet are unmatched
        for (Map.Entry<String, List<String[]>> entry : map2.entrySet()) {
            String key = entry.getKey();
            if (!map1.containsKey(key)) {
                unmatched2.addAll(entry.getValue());
            }
        }

        result.put("matched", matched);
        result.put("unmatched1", unmatched1);
        result.put("unmatched2", unmatched2);
        return result;
    }

    /**
     * Builds a map from a composite key (based on trimmed values at keyIndices) to the list of records.
     */
    private Map<String, List<String[]>> buildKeyMap(List<String[]> dataset, int[] keyIndices) {
        Map<String, List<String[]>> keyMap = new HashMap<>();
        for (String[] record : dataset) {
            String key = buildKey(record, keyIndices);
            keyMap.computeIfAbsent(key, k -> new ArrayList<>()).add(record);
        }
        return keyMap;
    }

    /**
     * Constructs a composite key by concatenating trimmed values at the specified indices.
     */
    private String buildKey(String[] record, int[] keyIndices) {
        StringBuilder sb = new StringBuilder();
        for (int idx : keyIndices) {
            if (idx >= 0 && idx < record.length) {
                sb.append(record[idx].trim()).append('\0'); // use null char as delimiter
            } else {
                sb.append("").append('\0'); // placeholder for missing index
            }
        }
        return sb.toString();
    }

    /**
     * Concatenates two string arrays into one.
     */
    private String[] concatenateArrays(String[] a, String[] b) {
        String[] result = new String[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }
}

