import java.util.*;

class AuthService {
    public Map<String, Object> processOAuth2User(String provider,
                                                Map<String, Object> userAttributes,
                                                Map<String, User> existingUsers,
                                                Set<Role> availableRoles) {
        // Extract email from user attributes
        Object emailObj = userAttributes.get("email");
        if (emailObj == null || !(emailObj instanceof String)) {
            throw new IllegalArgumentException("User attributes must contain a valid 'email' field.");
        }
        String email = (String) emailObj;

        User user = existingUsers.get(email);
        String status;

        if (user == null) {
            // Create new user
            String prefix = email.split("@")[0];
            String username = prefix + "_" + provider;
            user = new User(email, username);

            // Optionally assign a default role if available
            if (!availableRoles.isEmpty()) {
                user.setRoles(new HashSet<>(availableRoles));
            }

            existingUsers.put(email, user);
            status = "registered";
        } else {
            status = "authenticated";
        }

        Map<String, Object> result = new HashMap<>();
        result.put("status", status);
        result.put("user", user);
        result.put("provider", provider);
        return result;
    }
}

