class PostCreator {
    // Regex pattern for validating email addresses
    private static final Pattern EMAIL_PATTERN =
            Pattern.compile("^[A-Za-z0-9+_.-]+@(.+)$");

    public Map<String, Object> createPost(
            String title, String description, String price,
            String country, String stateProvince, String city,
            String contactEmail, Object imageData) {

        // Collect validation errors
        Map<String, Object> errors = new HashMap<>();

        // ---- Title validation ----
        if (title == null || title.isEmpty() || title.length() > 100) {
            errors.put("title",
                    "Title must not be null or empty and must be at most 100 characters long.");
        }

        // ---- Description validation ----
        if (description == null || description.isEmpty()) {
            errors.put("description",
                    "Description must not be null or empty.");
        }

        // ---- Price validation ----
        if (price != null && !price.isEmpty()) {
            try {
                double p = Double.parseDouble(price);
                if (p < 0) {
                    errors.put("price",
                            "Price must be a non‑negative number.");
                }
            } catch (NumberFormatException e) {
                errors.put("price",
                        "Price must be a valid number.");
            }
        }

        // ---- Contact email validation ----
        if (contactEmail != null && !contactEmail.isEmpty()) {
            if (!EMAIL_PATTERN.matcher(contactEmail).matches()) {
                errors.put("contactEmail",
                        "contactEmail must match the pattern '^[A-Za-z0-9+_.-]+@(.+)$'.");
            }
        }

        // ---- Image data validation ----
        if (imageData == null) {
            errors.put("imageData",
                    "imageData must not be null.");
        } else if (!(imageData instanceof String) && !(imageData instanceof byte[])) {
            errors.put("imageData",
                    "imageData must be a String or a byte array.");
        }

        // If any validation errors exist, return them
        if (!errors.isEmpty()) {
            Map<String, Object> result = new HashMap<>();
            result.put("success", false);
            result.put("errors", errors);
            return result;
        }

