import java.util.*;

class MessageSystemSimulator {
    // Maps a unique address to its ServiceNode
    private final Map<String, ServiceNode> nodes = new HashMap<>();
    // Maps a service type to its unique address
    private final Map<String, String> addressMap = new HashMap<>();
    // Counter for generating unique addresses
    private long addressCounter = 0;

    /**
     * Registers a new service with the given type and handler.
     * If the service type is already registered, the existing address is returned.
     *
     * @param serviceType the type/name of the service
     * @param handler     the handler that will process incoming messages
     * @return the unique address assigned to the service
     */
    public String registerService(String serviceType, MessageHandler handler) {
        if (serviceType == null || handler == null) {
            throw new IllegalArgumentException("Service type and handler must not be null");
        }

        // If the service type is already registered, return its address
        if (addressMap.containsKey(serviceType)) {
            return addressMap.get(serviceType);
        }

        // Generate a unique address (e.g., "svc-1", "svc-2", ...)
        String address = "svc-" + (++addressCounter);
        ServiceNode node = new ServiceNode(address, handler);
        nodes.put(address, node);
        addressMap.put(serviceType, address);
        return address;
    }

    /**
     * Sends a message from one service to another identified by service type.
     *
     * @param fromAddress   the address of the sender
     * @param toServiceType the type of the recipient service
     * @param messageContent the content of the message
     * @return true if the message was delivered and processed successfully; false otherwise
     */
    public boolean sendMessage(String fromAddress, String toServiceType, String messageContent) {
        if (fromAddress == null || toServiceType == null || messageContent == null) {
            return false;
        }

        // Verify that the sender exists
        if (!nodes.containsKey(fromAddress)) {
            return false;
        }

        // Resolve the recipient address
        String toAddress = addressMap.get(toServiceType);
        if (toAddress == null) {
            return false; // recipient not found
        }

        ServiceNode recipientNode = nodes.get(toAddress);
        if (recipientNode == null) {
            return false; // should not happen, but guard anyway
        }

        Message msg = new Message(fromAddress, toAddress, messageContent);
        return recipientNode.getHandler().process(msg);
    }

    // Helper to expose the nodes map for testing or introspection (optional)
    Map<String, ServiceNode> getNodes() {
        return Collections.unmodifiableMap(nodes);
    }
}

class ServiceNode {
    private final String address;
    private final MessageHandler handler;

    public ServiceNode(String address, MessageHandler handler) {
        if (address == null || handler == null) {
            throw new IllegalArgumentException("Address and handler must not be null");
        }
        this.address = address;
        this.handler = handler;
    }

    public String getAddress() {
        return address;
    }

    public MessageHandler getHandler() {
        return handler;
    }
}

interface MessageHandler {
    /**
     * Processes an incoming message.
     *
     * @param message the message to process
     * @return true if the message was processed successfully; false otherwise
     */
    boolean process(Message message);
}

class Message {
    private final String from;
    private final String to;
    private final String content;

    public Message(String from, String to, String content) {
        if (from == null || to == null || content == null) {
            throw new IllegalArgumentException("Message fields must not be null");
        }
        this.from = from;
        this.to = to;
        this.content = content;
    }

    public String getFrom() {
        return from;
    }

    public String getTo() {
        return to;
    }

    public String getContent() {
        return content;
    }
}

