import java.util.*;

/**
 * A simple deterministic finite automaton (DFA) implementation.
 *
 * <p>Usage example:
 * <pre>
 *     DFA dfa = new DFA();
 *     dfa.addState("q0");
 *     dfa.addState("q1");
 *     dfa.setFinal("q1");
 *     dfa.addTransition("q0", 'a', "q1");
 *     dfa.addTransition("q1", 'b', "q0");
 *
 *     System.out.println(dfa.accepts("a"));      // true
 *     System.out.println(dfa.accepts("ab"));     // false
 *     System.out.println(dfa.accepts("aba"));    // true
 * </pre>
 */
public class DFA {

    /** Represents a state in the DFA. */
    public static class State {
        private final String name;
        private final Map<Character, State> transitions = new HashMap<>();

        public State(String name) {
            this.name = Objects.requireNonNull(name);
        }

        /** Adds a transition for a given input symbol. */
        public void addTransition(char symbol, State target) {
            transitions.put(symbol, Objects.requireNonNull(target));
        }

        /** Returns the next state for the given input symbol, or null if none. */
        public State next(char symbol) {
            return transitions.get(symbol);
        }

        public String getName() {
            return name;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    private final Map<String, State> states = new LinkedHashMap<>();
    private State initial = null;
    private final Set<State> finals = new HashSet<>();

    /** Adds a new state. The first added state becomes the initial state. */
    public void addState(String name) {
        if (states.containsKey(name)) {
            throw new IllegalArgumentException("State already exists: " + name);
        }
        State s = new State(name);
        states.put(name, s);
        if (initial == null) {
            initial = s;
        }
    }

    /** Marks a state as an accepting (final) state. */
    public void setFinal(String name) {
        State s = getState(name);
        finals.add(s);
    }

    /** Adds a transition from one state to another on a given symbol. */
    public void addTransition(String fromName, char symbol, String toName) {
        State from = getState(fromName);
        State to = getState(toName);
        from.addTransition(symbol, to);
    }

    /** Returns the state object by name. */
    private State getState(String name) {
        State s = states.get(name);
        if (s == null) {
            throw new IllegalArgumentException("Unknown state: " + name);
        }
        return s;
    }

    /** Simulates the DFA on the given input string. */
    public boolean accepts(String input) {
        if (initial == null) {
            throw new IllegalStateException("DFA has no states.");
        }
        State current = initial;
        for (char c : input.toCharArray()) {
            current = current.next(c);
            if (current == null) {
                return false; // no valid transition
            }
        }
        return finals.contains(current);
    }

    /** Simple demonstration of the DFA. */
    public static void main(String[] args) {
        DFA dfa = new DFA();

        // Example DFA that accepts strings ending with 'a'
        dfa.addState("q0"); // initial state
        dfa.addState("q1");
        dfa.setFinal("q1");

        dfa.addTransition("q0", 'a', "q1");
        dfa.addTransition("q0", 'b', "q0");
        dfa.addTransition("q1", 'a', "q1");
        dfa.addTransition("q1", 'b', "q0");

        String[] tests = {"", "a", "b", "ab", "ba", "aba", "baa"};
        for (String s : tests) {
            System.out.printf("Input \"%s\" accepted? %b%n", s, dfa.accepts(s));
        }
    }
}

