    public EnhancedSpotLight(Vector3 position, double intensity, Vector3 direction,
                             double cutoff, double outerCutoff, Vector3 color,
                             double falloffExponent) {
        if (position == null) throw new IllegalArgumentException("Position cannot be null");
        super(position, intensity);
        setDirection(direction);
        setCutoff(cutoff);
        setOuterCutoff(outerCutoff);
        setColor(color);
        setFalloffExponent(falloffExponent);
