    public void setColor(Vector3 color) {
        if (color == null) throw new IllegalArgumentException("Color cannot be null");
        this.color = color;
    }

    public double getFalloffExponent() { return falloffExponent; }
    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0)
            throw new IllegalArgumentException("FalloffExponent must be positive");
        this.falloffExponent = falloffExponent;
    }

    @Override
    public void setPosition(Vector3 position) {
        if (position == null) throw new IllegalArgumentException("Position cannot be null");
        super.setPosition(position);
    }

    /**
     * Computes the intensity at a given point, combining angular attenuation
     * (spotlight cone) with distance attenuation (point light falloff).
     *
     * @param point The point in space to evaluate.
     * @return The final intensity value between 0 and the base intensity.
     */
    public double calculateIntensity(Vector3 point) {
        // Angular attenuation
        Vector3 lightPos = getPosition();
        Vector3 dir = getDirection().normalized();
        Vector3 toPoint = point.sub(lightPos).normalized();

        double cosTheta = dir.dot(toPoint);

        double cosInner = Math.cos(Math.toRadians(getCutoff()));
        double cosOuter = Math.cos(Math.toRadians(getOuterCutoff()));

        double angularAttenuation;
        if (cosTheta >= cosInner) {
            angularAttenuation = 1.0;
        } else if (cosTheta <= cosOuter) {
            angularAttenuation = 0.0;
        } else {
            double factor = (cosTheta - cosOuter) / (cosInner - cosOuter);
            angularAttenuation = Math.pow(factor, getFalloffExponent());
        }

        // Distance attenuation
        double distance = point.sub(lightPos).length();
        double denom = getConstantAttenuation()
                     + getLinearAttenuation() * distance
                     + getExponentAttenuation() * distance * distance;
        double distanceAttenuation = 1.0 / denom;

        // Final intensity
        return getIntensity() * angularAttenuation * distanceAttenuation;
    }
