public class EnhancedSpotLight extends PointLight {
    private Vector3 direction;
    private double cutoff;
    private double outerCutoff;
    private Vector3 color;
    private double falloffExponent;

    public EnhancedSpotLight() {
        super();
        this.direction = new Vector3();
        this.cutoff = 0;
        this.outerCutoff = 0;
        this.color = new Vector3();
        this.falloffExponent = 1.0;
    }

    public EnhancedSpotLight(Vector3 position, double intensity, Vector3 direction,
                             double cutoff, double outerCutoff, Vector3 color,
                             double falloffExponent) {
        if (position == null) throw new IllegalArgumentException("Position cannot be null");
        super(position, intensity);
        setDirection(direction);
        setCutoff(cutoff);
        setOuterCutoff(outerCutoff);
        setColor(color);
        setFalloffExponent(falloffExponent);
    }

    public Vector3 getDirection() { return direction; }
    public void setDirection(Vector3 direction) {
        if (direction == null) throw new IllegalArgumentException("Direction cannot be null");
        this.direction = direction;
    }

    public double getCutoff() { return cutoff; }
    public void setCutoff(double cutoff) {
        if (cutoff < 0 || cutoff > 90)
            throw new IllegalArgumentException("Cutoff must be between 0 and 90 degrees");
        if (outerCutoff > 0 && cutoff >= outerCutoff)
            throw new IllegalArgumentException("Cutoff must be less than outerCutoff");
        this.cutoff = cutoff;
    }

    public double getOuterCutoff() { return outerCutoff; }
    public void setOuterCutoff(double outerCutoff) {
        if (outerCutoff < 0 || outerCutoff > 90)
            throw new IllegalArgumentException("OuterCutoff must be between 0 and 90 degrees");
        if (cutoff > 0 && outerCutoff <= cutoff)
            throw new IllegalArgumentException("OuterCutoff must be greater than cutoff");
        this.outerCutoff = outerCutoff;
    }

    public Vector3 getColor() { return color; }
    public void setColor(Vector3 color) {
        if (color == null) throw new IllegalArgumentException("Color cannot be null");
        this.color = color;
    }

    public double getFalloffExponent() { return falloffExponent; }
    public void setFalloffExponent(double falloffExponent) {
        if (falloffExponent <= 0)
            throw new IllegalArgumentException("FalloffExponent must be positive");
        this.falloffExponent = falloffExponent;
    }

    @Override
    public void setPosition(Vector3 position) {
        if (position == null) throw new IllegalArgumentException("Position cannot be null");
        super.setPosition(position);
    }

    /**
     * Computes the intensity at a given point, combining angular attenuation
     * (spotlight cone) with distance attenuation (point light falloff).
     *
     * @param point The point in space to evaluate.
     * @return The final intensity value between 0 and the base intensity.
     */
    public double calculateIntensity(Vector3 point) {
        // Angular attenuation
        Vector3 lightPos = getPosition();
        Vector3 dir = getDirection().normalized();
        Vector3 toPoint = point.sub(lightPos).normalized();

        double cosTheta = dir.dot(toPoint);

        double cosInner = Math.cos(Math.toRadians(getCutoff()));
        double cosOuter = Math.cos(Math.toRadians(getOuterCutoff()));

        double angularAttenuation;
        if (cosTheta >= cosInner) {
            angularAttenuation = 1.0;
        } else if (cosTheta <= cosOuter) {
            angularAttenuation = 0.0;
        } else {
            double factor = (cosTheta - cosOuter) / (cosInner - cosOuter);
            angularAttenuation = Math.pow(factor, getFalloffExponent());
        }

        // Distance attenuation
        double distance = point.sub(lightPos).length();
        double denom = getConstantAttenuation()
                     + getLinearAttenuation() * distance
                     + getExponentAttenuation() * distance * distance;
        double distanceAttenuation = 1.0 / denom;

        // Final intensity
        return getIntensity() * angularAttenuation * distanceAttenuation;
    }
}
