import java.util.LinkedList;
import java.util.Queue;
import java.util.ArrayList;
import java.util.List;

class BSTOperations {
    static class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int x) { val = x; }
    }

    public TreeNode deleteNode(TreeNode root, int key) {
        if (root == null) return null;

        if (key < root.val) {
            root.left = deleteNode(root.left, key);
        } else if (key > root.val) {
            root.right = deleteNode(root.right, key);
        } else { // Found the node to delete
            // Case 1: No child
            if (root.left == null && root.right == null) {
                return null;
            }
            // Case 2: One child
            if (root.left == null) {
                return root.right;
            }
            if (root.right == null) {
                return root.left;
            }
            // Case 3: Two children
            int successorVal = minValue(root.right);
            root.val = successorVal;
            root.right = deleteNode(root.right, successorVal);
        }
        return root;
    }

    // Private helper that returns the minimum value in a BST/subtree
    private int minValue(TreeNode root) {
        // Assume root is not null
        while (root.left != null) {
            root = root.left;
        }
        return root.val;
    }

    /**
     * Returns a string representation of the tree's level-order traversal.
     * Format: [val1,val2,...,valn] where null represents missing nodes.
     * Trailing nulls are omitted. If the tree is empty, returns "[]".
     */
    public String levelOrder(TreeNode root) {
        if (root == null) {
            return "[]";
        }

        List<String> result = new ArrayList<>();
        Queue<TreeNode> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            if (node != null) {
                result.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            } else {
                result.add("null");
            }
        }

        // Remove trailing "null" entries
        int i = result.size() - 1;
        while (i >= 0 && result.get(i).equals("null")) {
            i--;
        }
        result = result.subList(0, i + 1);

        return "[" + String.join(",", result) + "]";
    }
}

