import java.util.*;

public class PaginationProcessor<T> {
    private final List<T> dataset;
    private final int defaultPageSize;

    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        this.dataset = new ArrayList<>(dataset);
        this.defaultPageSize = defaultPageSize;
    }

    public Result<T> getPaginatedData(int pageNumber, int itemsPerPage) {
        if (pageNumber < 1) {
            throw new IllegalArgumentException("Page number must be >= 1");
        }
        if (itemsPerPage < 1) {
            throw new IllegalArgumentException("Items per page must be >= 1");
        }

        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / itemsPerPage);

        int startIndex = (pageNumber - 1) * itemsPerPage;
        if (startIndex >= totalItems) {
            return new Result<>(Collections.emptyList(), pageNumber, itemsPerPage, totalPages, totalItems);
        }
        int endIndex = Math.min(startIndex + itemsPerPage, totalItems);
        List<T> pageData = dataset.subList(startIndex, endIndex);

        return new Result<>(pageData, pageNumber, itemsPerPage, totalPages, totalItems);
    }

    public static class Result<T> {
        private final List<T> data;
        private final int currentPage;
        private final int itemsPerPage;
        private final int totalPages;
        private final int totalItems;

        public Result(List<T> data, int currentPage, int itemsPerPage, int totalPages, int totalItems) {
            this.data = data;
            this.currentPage = currentPage;
            this.itemsPerPage = itemsPerPage;
            this.totalPages = totalPages;
            this.totalItems = totalItems;
        }

        public List<T> getData() {
            return data;
        }

        public int getCurrentPage() {
            return currentPage;
        }

        public int getItemsPerPage() {
            return itemsPerPage;
        }

        public int getTotalPages() {
            return totalPages;
        }

        public int getTotalItems() {
            return totalItems;
        }

        @Override
        public String toString() {
            return "Result{" +
                    "data=" + data +
                    ", currentPage=" + currentPage +
                    ", itemsPerPage=" + itemsPerPage +
                    ", totalPages=" + totalPages +
                    ", totalItems=" + totalItems +
                    '}';
        }
    }

    // Example usage
    public static void main(String[] args) {
        List<Integer> numbers = new ArrayList<>();
        for (int i = 1; i <= 25; i++) {
            numbers.add(i);
        }

        PaginationProcessor<Integer> processor = new PaginationProcessor<>(numbers, 10);
        PaginationProcessor.Result<Integer> page1 = processor.getPaginatedData(1, 10);
        System.out.println(page1);

        PaginationProcessor.Result<Integer> page3 = processor.getPaginatedData(3, 10);
        System.out.println(page3);
    }
}

