import java.util.*;

/**
 * Generic pagination processor that can paginate any type of dataset.
 *
 * @param <T> the type of elements in the dataset
 */
public class PaginationProcessor<T> {

    private final List<T> dataset;
    private final int defaultPageSize;

    /**
     * Creates a new processor for the given dataset and default page size.
     *
     * @param dataset        the data to paginate
     * @param defaultPageSize the default number of items per page
     * @throws IllegalArgumentException if defaultPageSize is less than 1
     */
    public PaginationProcessor(List<T> dataset, int defaultPageSize) {
        if (defaultPageSize < 1) {
            throw new IllegalArgumentException("Default page size must be >= 1");
        }
        this.dataset = new ArrayList<>(Objects.requireNonNull(dataset, "Dataset cannot be null"));
        this.defaultPageSize = defaultPageSize;
    }

    /**
     * Returns a paginated view of the dataset.
     *
     * @param pageNumber   the 1‑based page number to retrieve
     * @param itemsPerPage the number of items per page; if {@code null} the default page size is used
     * @return a {@link Result} containing the page data and metadata
     * @throws IllegalArgumentException if pageNumber < 1 or itemsPerPage != null && itemsPerPage < 1
     */
    public Result<T> getPaginatedData(int pageNumber, Integer itemsPerPage) {
        if (pageNumber < 1) {
            throw new IllegalArgumentException("Page number must be >= 1");
        }

        int effectiveItemsPerPage = (itemsPerPage == null) ? defaultPageSize : itemsPerPage;
        if (effectiveItemsPerPage < 1) {
            throw new IllegalArgumentException("Items per page must be >= 1");
        }

        int totalItems = dataset.size();
        int totalPages = (int) Math.ceil((double) totalItems / effectiveItemsPerPage);

        int startIndex = (pageNumber - 1) * effectiveItemsPerPage;
        if (startIndex >= totalItems) {
            // Return an empty page if the requested page is beyond the last page
            return new Result<>(Collections.emptyList(), pageNumber, effectiveItemsPerPage, totalPages, totalItems);
        }

        int endIndex = Math.min(startIndex + effectiveItemsPerPage, totalItems);
