import java.util.Arrays;

public class EnhancedBinaryHeap<T extends Comparable<T>> {
    private static final int INITIAL_CAPACITY = 10;
    private T[] heap;
    private int size;

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap() {
        heap = (T[]) new Comparable[INITIAL_CAPACITY];
        size = 0;
    }

    @SuppressWarnings("unchecked")
    public EnhancedBinaryHeap(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        heap = (T[]) new Comparable[capacity];
        size = 0;
    }

    public void insert(T element) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        if (size == heap.length) {
            resize();
        }
        heap[size] = element;
        siftUp(size);
        size++;
    }

    public T peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap[0];
    }

    public T deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            siftDown(0);
        }
        heap[size] = null; // help GC
        return root;
    }

