import java.util.Arrays;

public class EnhancedBinaryHeap<T extends Comparable<T>> {
    private static final int INITIAL_CAPACITY = 10;

    private T[] heap;
    private int[] v1Array;
    private int[] v2Array;
    private int size;
    private final boolean isMinHeap;

    /*--------------------- Constructors ---------------------*/

    /** Default constructor – creates an empty min‑heap. */
    public EnhancedBinaryHeap() {
        this(true);
    }

    /** Constructor that specifies the heap type. */
    public EnhancedBinaryHeap(boolean isMinHeap) {
        this.isMinHeap = isMinHeap;
        heap = (T[]) new Comparable[INITIAL_CAPACITY];
        v1Array = new int[INITIAL_CAPACITY];
        v2Array = new int[INITIAL_CAPACITY];
        size = 0;
    }

    /** Constructor with initial capacity and heap type. */
    public EnhancedBinaryHeap(int capacity, boolean isMinHeap) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        this.isMinHeap = isMinHeap;
        heap = (T[]) new Comparable[capacity];
        v1Array = new int[capacity];
        v2Array = new int[capacity];
        size = 0;
    }

    /**
     * Builds a heap from an existing array of Comparable items.
     * The heap is built in O(n) time using the buildHeap method.
     *
     * @param items    the array of items to heapify
     * @param isMinHeap true for min‑heap, false for max‑heap
     */
    public EnhancedBinaryHeap(T[] items, boolean isMinHeap) {
        if (items == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        this.isMinHeap = isMinHeap;
        heap = (T[]) new Comparable[items.length];
        v1Array = new int[items.length];
        v2Array = new int[items.length];
        System.arraycopy(items, 0, heap, 0, items.length);
        // Default vertex values are 0
        Arrays.fill(v1Array, 0);
        Arrays.fill(v2Array, 0);
        size = items.length;
        buildHeap();
    }

    /*--------------------- Core Operations ---------------------*/

    /**
     * Inserts an element with its associated vertex pair.
     *
     * @param element the element to insert
     * @param v1      first vertex of the association
     * @param v2      second vertex of the association
     */
    public void insert(T element, int v1, int v2) {
        if (element == null) {
            throw new IllegalArgumentException("Null elements not allowed");
        }
        if (size == heap.length) {
            resize();
        }
        heap[size] = element;
        v1Array[size] = v1;
        v2Array[size] = v2;
        siftUp(size);
        size++;
    }

    /** Returns the root element without removing it. */
    public T peekRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return heap[0];
    }

    /** Returns the vertex pair of the root element. */
    public int[] peekRootVertices() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        return new int[]{v1Array[0], v2Array[0]};
    }

    /** Removes and returns the root element. */
    public T deleteRoot() {
        if (isEmpty()) {
            throw new IllegalStateException("Heap is empty");
        }
        T root = heap[0];
        size--;
        if (size > 0) {
            heap[0] = heap[size];
            v1Array[0] = v1Array[size];
            v2Array[0] = v2Array[size];
            siftDown(0);
        }
        heap[size] = null;
        v1Array[size] = 0;
        v2Array[size] = 0;
        return root;
    }

    /** Checks whether the heap is empty. */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Returns the number of elements in the heap. */
    public int size() {
        return size;
    }

    /** Removes all elements from the heap. */
    public void makeEmpty() {
        Arrays.fill(heap, null);
        Arrays.fill(v1Array, 0);
        Arrays.fill(v2Array, 0);
        size = 0;
    }

    /*--------------------- Heap Sort ---------------------*/

    /**
     * Performs heap sort on the current heap.
     * The heap is destroyed during the process.
     *
     * @return an array containing the sorted elements
     */
    public T[] heapSort() {
        if (size == 0) {
            return (T[]) new Comparable[0];
        }
        @SuppressWarnings("unchecked")
        T[] sorted = (T[]) new Comparable[size];
        int originalSize = size;
        for (int i = 0; i < originalSize; i++) {
            sorted[i] = deleteRoot();
        }
        return sorted;
    }

    /*--------------------- Internal Helpers ---------------------*/

    /** Builds the heap in O(n) time. */
    private void buildHeap() {
        for (int i = (size / 2) - 1; i >= 0; i--) {
            siftDown(i);
        }
    }

    /** Restores heap property by moving the element at index up. */
    private void siftUp(int index) {
        int parent = (index - 1) / 2;
        while (index > 0 && compare(heap[index], heap[parent]) < 0) {
            swap(index, parent);
            index = parent;
            parent = (index - 1) / 2;
        }
    }

    /** Restores heap property by moving the element at index down. */
    private void siftDown(int index) {
        while (true) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int target = index;

            if (left < size && compare(heap[left], heap[target]) < 0) {
                target = left;
            }
            if (right < size && compare(heap[right], heap[target]) < 0) {
                target = right;
            }
            if (target == index) {
                break;
            }
            swap(index, target);
            index = target;
        }
    }

