     * @param currentPage the requested page number (1‑based)
     * @return a PaginationResult containing all pagination details
     */
    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than 0");
        }
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems cannot be negative");
        }

        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        if (totalPages == 0) {
            totalPages = 1; // Ensure at least one page exists
        }

        // Clamp currentPage to valid range
        if (currentPage < 1) {
            currentPage = 1;
        } else if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        int startItem = (currentPage - 1) * pageSize + 1;
        int endItem = Math.min(currentPage * pageSize, totalItems);
        if (totalItems == 0) {
            startItem = 0;
            endItem = 0;
        }

        List<Integer> visiblePages = new ArrayList<>();
        for (int i = 1; i <= totalPages; i++) {
            visiblePages.add(i);
        }

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages,
