/**
 * Provides a method to calculate pagination details.
 */
public class PaginationManager {

    public PaginationResult calculatePagination(int totalItems, int pageSize, int currentPage) {
        if (totalItems < 0) {
            throw new IllegalArgumentException("totalItems cannot be negative");
        }
        if (pageSize <= 0) {
            throw new IllegalArgumentException("pageSize must be greater than 0");
        }
        if (totalItems == 0) {
            // No items: no pages, no items displayed
            return new PaginationResult(0, pageSize, 0, 0, 0, 0, new ArrayList<>());
        }
        if (currentPage <= 0) {
            throw new IllegalArgumentException("currentPage must be greater than 0");
        }

        int totalPages = (int) Math.ceil((double) totalItems / pageSize);
        if (currentPage > totalPages) {
            currentPage = totalPages;
        }

        int startItem = (currentPage - 1) * pageSize + 1;
        int endItem = Math.min(currentPage * pageSize, totalItems);

        List<Integer> visiblePages = calculateVisiblePages(totalPages, currentPage);

        return new PaginationResult(totalItems, pageSize, currentPage, totalPages,
                startItem, endItem, visiblePages);
    }

    /**
     * Builds a list of page numbers to display in a pagination control.
     * The list contains the first page, an ellipsis (-1) if there is a gap,
     * up to two pages before and after the current page, another ellipsis if needed,
     * and the last page.
     *
     * @param totalPages  total number of pages (must be >= 0)
     * @param currentPage current page number (1‑based, must be <= totalPages)
     * @return list of page numbers and -1 for ellipses
     */
    private List<Integer> calculateVisiblePages(int totalPages, int currentPage) {
        List<Integer> pages = new ArrayList<>();
        if (totalPages <= 0) {
            return pages;
        }

        int startRange = Math.max(1, currentPage - 2);
        int endRange = Math.min(totalPages, currentPage + 2);

        // Add first page if it's not in the range
        if (startRange > 1) {
            pages.add(1);
            if (startRange > 2) {
                pages.add(-1); // ellipsis
            }
        }

        // Add the range of pages around the current page
        for (int i = startRange; i <= endRange; i++) {
            pages.add(i);
        }

        // Add last page if it's not in the range
        if (endRange < totalPages) {
            if (endRange < totalPages - 1) {
                pages.add(-1); // ellipsis
            }
            pages.add(totalPages);
        }

        return pages;
    }
}

