public interface Observer {
    void takeAction(String msg);
}

public class ObservableSubject {
    private java.util.List<Observer> observers = new java.util.ArrayList<>();

    public void addObserver(Observer observer) {
        observers.add(observer);
    }

    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    public void notifyObservers(String msg) {
        for (Observer o : observers) {
            o.takeAction(msg);
        }
    }
}

public class ConcreteObserver implements Observer {
    private String name;

    public ConcreteObserver(String name) {
        this.name = name;
    }

    @Override
    public void takeAction(String msg) {
        System.out.println(name + " received: " + msg);
    }
}

public class Main {
    public static void main(String[] args) {
        ObservableSubject subject = new ObservableSubject();

        Observer obs1 = new ConcreteObserver("Observer1");
        Observer obs2 = new ConcreteObserver("Observer2");

        subject.addObserver(obs1);
        subject.addObserver(obs2);

        subject.notifyObservers("Hello Observers!");

        subject.removeObserver(obs1);

        subject.notifyObservers("Second message");
    }
}

