public class UserManager {
    private List<User> users;
    private Map<String, Integer> failedAttempts;   // key: lower‑case username
    private Set<String> lockedAccounts;            // key: lower‑case username
    private static final int MAX_ATTEMPTS = 3;

    public UserManager() {
        this.users = new ArrayList<>();
        this.failedAttempts = new HashMap<>();
        this.lockedAccounts = new HashSet<>();
    }

    public Map<String, Object> registerUser(User user) {
        Map<String, Object> result = new HashMap<>();

        // Validate username
        if (user.getUsername() == null || user.getUsername().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Username cannot be empty.");
            return result;
        }

        // Validate password
        if (user.getPassword() == null || user.getPassword().trim().isEmpty()) {
            result.put("success", false);
            result.put("message", "Password cannot be empty.");
            return result;
        }

        // Check for unique username (case‑insensitive)
        String newUsernameLower = user.getUsername().toLowerCase();
        for (User existing : users) {
            if (existing.getUsername().toLowerCase().equals(newUsernameLower)) {
                result.put("success", false);
                result.put("message", "Username already exists.");
                return result;
            }
        }

        // All checks passed; register user
        users.add(user);
        result.put("success", true);
        result.put("message", "User registered successfully.");
        return result;
    }

    public Map<String, Object> loginUser(String username, String password) {
        Map<String, Object> response = new HashMap<>();

        if (username == null || username.trim().isEmpty()) {
            response.put("success", false);
            response.put("message", "Username cannot be empty.");
            response.put("attemptsRemaining", MAX_ATTEMPTS);
            return response;
        }

        String usernameKey = username.toLowerCase();
        User foundUser = null;
        for (User u : users) {
            if (u.getUsername().toLowerCase().equals(usernameKey)) {
                foundUser = u;
                break;
            }
        }

        if (foundUser == null) {
            response.put("success", false);
            response.put("message", "User not found.");
            response.put("attemptsRemaining", MAX_ATTEMPTS);
            return response;
        }

        // Check if account is locked
        if (lockedAccounts.contains(usernameKey)) {
            response.put("success", false);
            response.put("message", "Account locked due to multiple failed attempts.");
            response.put("attemptsRemaining", 0);
            return response;
        }

        // Verify password
        if (foundUser.getPassword().equals(password)) {
            // Successful login: reset attempts
            failedAttempts.remove(usernameKey);
            response.put("success", true);
            response.put("message", "Login successful.");
            response.put("user", foundUser);
            return response;
        } else {
            // Failed login: increment attempts
            int attempts = failedAttempts.getOrDefault(usernameKey, 0) + 1;
            failedAttempts.put(usernameKey, attempts);

            int attemptsRemaining = MAX_ATTEMPTS - attempts;
            if (attemptsRemaining <= 0) {
                // Lock account
                lockedAccounts.add(usernameKey);
                attemptsRemaining = 0;
                response.put("success", false);
                response.put("message", "Account locked due to multiple failed attempts.");
            } else {
                response.put("success", false);
                response.put("message", "Invalid credentials.");
            }
            response.put("attemptsRemaining", attemptsRemaining);
            return response;
        }
    }
}

