/**
 * PathFinder computes the number of unique paths from the top‑left corner
 * to the bottom‑right corner of a rectangular grid. Movement is allowed
 * only to the right or down. In addition to the total number of paths,
 * it provides analysis information such as the maximum and minimum
 * path lengths (which are identical for a grid with only right/down
 * moves) and a sample path.
 */
public class PathFinder {

    /**
     * Inner class that holds analysis data for the path‑finding problem.
     */
    public static class PathAnalysis {
        public final long totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(long totalPaths, int maxPathLength, int minPathLength,
                            List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = Collections.unmodifiableList(new ArrayList<>(samplePath));
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Total Paths: ").append(totalPaths).append('\n');
            sb.append("Max Path Length: ").append(maxPathLength).append('\n');
            sb.append("Min Path Length: ").append(minPathLength).append('\n');
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the number of unique paths and returns a {@link PathAnalysis}
     * object containing the total number of paths, the maximum and minimum
     * path lengths, and a sample path.
     *
     * @param grid a 2D integer array representing the grid (values are ignored)
     * @return a {@code PathAnalysis} instance with the analysis data
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // The number of steps in any path is fixed: (rows-1)+(cols-1)
        int pathLength = (rows - 1) + (cols - 1);

        // Compute total number of unique paths using combinatorics:
        // C(rows+cols-2, rows-1)
        long totalPaths = binomialCoefficient(rows + cols - 2, rows - 1);

        // Build a sample path: all rights followed by all downs
        List<String> samplePath = new ArrayList<>();
        for (int i = 0; i < cols - 1; i++) {
            samplePath.add("R");
        }
        for (int i = 0; i < rows - 1; i++) {
            samplePath.add("D");
        }

        return new PathAnalysis(totalPaths, pathLength, pathLength, samplePath);
    }

    /**
     * Computes the binomial coefficient C(n, k) using an efficient
     * multiplicative approach to avoid overflow for moderate values.
     *
     * @param n the total number of items
     * @param k the number of items to choose
     * @return the binomial coefficient as a long
     */
    private long binomialCoefficient(int n, int k) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        k = Math.min(k, n - k); // take advantage of symmetry
        long result = 1;
        for (int i = 1; i <= k; i++) {
            result = result * (n - k + i) / i;
        }
        return result;
    }
}

