/**
 * PathFinder computes the number of unique paths from the top‑left corner
 * to the bottom‑right corner of a rectangular grid. Movement is allowed
 * only to the right or down. Cells with a value of 1 are considered
 * obstacles and cannot be traversed. The class also provides analysis
 * information such as the maximum and minimum path lengths (which are
 * identical for a grid with only right/down moves) and a sample path
 * expressed as a list of coordinates.
 */
public class PathFinder {

    /**
     * Inner class that holds analysis data for the path‑finding problem.
     */
    public static class PathAnalysis {
        public final long totalPaths;
        public final int maxPathLength;
        public final int minPathLength;
        public final List<String> samplePath;

        public PathAnalysis(long totalPaths, int maxPathLength, int minPathLength,
                            List<String> samplePath) {
            this.totalPaths = totalPaths;
            this.maxPathLength = maxPathLength;
            this.minPathLength = minPathLength;
            this.samplePath = Collections.unmodifiableList(new ArrayList<>(samplePath));
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            sb.append("Total Paths: ").append(totalPaths).append('\n');
            sb.append("Max Path Length: ").append(maxPathLength).append('\n');
            sb.append("Min Path Length: ").append(minPathLength).append('\n');
            sb.append("Sample Path: ").append(samplePath);
            return sb.toString();
        }
    }

    /**
     * Computes the number of unique paths avoiding obstacles and returns a
     * {@link PathAnalysis} object containing the total number of paths,
     * the maximum and minimum path lengths, and a sample path expressed
     * as a list of coordinates.
     *
     * @param grid a 2D integer array representing the grid (1 = obstacle, 0 = free)
     * @return a {@code PathAnalysis} instance with the analysis data
     */
    public PathAnalysis findUniquePathsWithAnalysis(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // If start or end is an obstacle, no path exists.
        if (grid[0][0] == 1 || grid[rows - 1][cols - 1] == 1) {
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        long[][] dp = new long[rows][cols];
        dp[0][0] = 1;

        // Initialize first column
        for (int i = 1; i < rows; i++) {
            dp[i][0] = (grid[i][0] == 0) ? dp[i - 1][0] : 0;
        }

        // Initialize first row
        for (int j = 1; j < cols; j++) {
            dp[0][j] = (grid[0][j] == 0) ? dp[0][j - 1] : 0;
        }

        // Fill the rest of the DP table
        for (int i = 1; i < rows; i++) {
            for (int j = 1; j < cols; j++) {
                if (grid[i][j] == 1) {
                    dp[i][j] = 0;
                } else {
                    dp[i][j] = dp[i - 1][j] + dp[i][j - 1];
                }
            }
        }

        long totalPaths = dp[rows - 1][cols - 1];
        if (totalPaths == 0) {
            return new PathAnalysis(0, 0, 0, Collections.emptyList());
        }

        int pathLength = (rows - 1) + (cols - 1); // same for all valid paths

        // Build a sample path using the DP table
        List<String> samplePath = new ArrayList<>();
        int r = 0, c = 0;
        samplePath.add("(" + r + "," + c + ")");

        while (r < rows - 1 || c < cols - 1) {
            boolean moved = false;
            // Prefer moving right if it leads to a reachable cell
            if (c + 1 < cols && grid[r][c + 1] == 0 && dp[r][c + 1] > 0) {
                c++;
                moved = true;
            }
            // Otherwise try moving down
            if (!moved && r + 1 < rows && grid[r + 1][c] == 0 && dp[r + 1][c] > 0) {
                r++;
                moved = true;
            }
            // If neither move is possible, break (should not happen if path exists)
            if (!moved) {
                break;
            }
            samplePath.add("(" + r + "," + c + ")");
        }

        return new PathAnalysis(totalPaths, pathLength, pathLength, samplePath);
    }
}

