class EggDropSolver {
    /**
     * Returns the minimum number of attempts needed in the worst case
     * to determine the critical floor with k eggs and n floors.
     *
     * @param k number of eggs
     * @param n number of floors
     * @return minimum number of attempts
     */
    public static int solveEggDrop(int k, int n) {
        if (n == 0 || n == 1) return n;
        if (k == 1) return n;

        // dp[i] will hold the maximum number of floors that can be tested
        // with i eggs and current number of moves.
        long[] dp = new long[k + 1];
        int moves = 0;

        while (dp[k] < n) {
            moves++;
            // Update dp array from high to low to use previous values
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }
}

