    public static class Result {
        public final int dpResult;
        public final long dpTimeMs;
        public final int mathResult;
        public final long mathTimeMs;

        public Result(int dpResult, long dpTimeMs, int mathResult, long mathTimeMs) {
            this.dpResult = dpResult;
            this.dpTimeMs = dpTimeMs;
            this.mathResult = mathResult;
            this.mathTimeMs = mathTimeMs;
        }
    }

    /**
     * Computes the minimum number of attempts using dynamic programming.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return minimum number of attempts
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static int solveEggDropDP(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1];
        int moves = 0;
        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /**
     * Computes the minimum number of attempts using a mathematical
     * approach based on binomial coefficients.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return minimum number of attempts
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static int solveEggDropMath(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        long sum = 0;
        while (sum < n) {
            moves++;
            long binom = 1; // C(moves, 0)
            for (int i = 1; i <= k; i++) {
                binom = binom * (moves - i + 1) / i;
                if (binom > n) binom = n; // cap to avoid overflow
                sum += binom;
                if (sum >= n) break;
            }
        }
        return moves;
    }

    /**
     * Computes both DP and mathematical solutions, measuring the
     * computation time for each, and returns them in a Result object.
     *
     * @param k number of eggs (must be > 0)
     * @param n number of floors (must be > 0)
     * @return Result containing both solutions and their times
     * @throws IllegalArgumentException if k <= 0 or n <= 0
     */
    public static Result solveEggDropBoth(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }

        long startDP = System.nanoTime();
        int dpResult = solveEggDropDP(k, n);
        long endDP = System.nanoTime();
        long dpTimeMs = (endDP - startDP) / 1_000_000;

        long startMath = System.nanoTime();
        int mathResult = solveEggDropMath(k, n);
        long endMath = System.nanoTime();
        long mathTimeMs = (endMath - startMath) / 1_000_000;

        return new Result(dpResult, dpTimeMs, mathResult, mathTimeMs);
    }
}

