class EggDropSolver {

    /** Result container holding all three solutions and their computation times. */
    public static class Result {
        public final int dpResult;
        public final long dpTimeMs;
        public final int mathResult;
        public final long mathTimeMs;
        public final int bsResult;
        public final long bsTimeMs;

        public Result(int dpResult, long dpTimeMs,
                      int mathResult, long mathTimeMs,
                      int bsResult, long bsTimeMs) {
            this.dpResult = dpResult;
            this.dpTimeMs = dpTimeMs;
            this.mathResult = mathResult;
            this.mathTimeMs = mathTimeMs;
            this.bsResult = bsResult;
            this.bsTimeMs = bsTimeMs;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 1. Dynamic‑Programming (iterative) solution                            */
    /* --------------------------------------------------------------------- */
    public static int solveEggDropDP(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        if (n == 1) return 1;
        if (k == 1) return n;

        long[] dp = new long[k + 1];
        int moves = 0;
        while (dp[k] < n) {
            moves++;
            for (int i = k; i >= 1; i--) {
                dp[i] = dp[i] + dp[i - 1] + 1;
            }
        }
        return moves;
    }

    /* --------------------------------------------------------------------- */
    /* 2. Mathematical (binomial‑coefficient) solution                       */
    /* --------------------------------------------------------------------- */
    public static int solveEggDropMath(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        if (n == 1) return 1;
        if (k == 1) return n;

        int moves = 0;
        long sum = 0;
        while (sum < n) {
            moves++;
            long binom = 1; // C(moves, 0)
            for (int i = 1; i <= k; i++) {
                binom = binom * (moves - i + 1) / i;
                if (binom > n) binom = n;          // avoid overflow
                sum += binom;
                if (sum >= n) break;
            }
        }
        return moves;
    }

    /* --------------------------------------------------------------------- */
    /* 3. Binary‑search + memoization solution                               */
    /* --------------------------------------------------------------------- */
    private static int[][] memo;

    public static int solveEggDropBinarySearch(int k, int n) {
        if (k <= 0 || n <= 0) {
            throw new IllegalArgumentException("Number of eggs and floors must be positive.");
        }
        memo = new int[k + 1][n + 1];
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = -1;
            }
        }
        return solveEggDropBinarySearchRec(k, n);
    }

    private static int solveEggDropBinarySearchRec(int k, int n) {
        if (n == 0 || n == 1) return n;
        if (k == 1) return n;
        if (memo[k][n] != -1) return memo[k][n];

        int low = 1, high = n;
        int best = Integer.MAX_VALUE;

        while (low <= high) {
            int mid = (low + high) >>> 1; // avoid overflow
            int breakCase = solveEggDropBinarySearchRec(k - 1, mid - 1);
            int notBreakCase = solveEggDropBinarySearchRec(k, n - mid);
            int temp = 1 + Math.max(breakCase, notBreakCase);

            if (temp < best) best = temp;

            if (breakCase > notBreakCase) {
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        memo[k][n] = best;
        return best;
    }

