import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * Holds the results of the egg‑drop problem solved by three different
 * algorithms and formats them into a single, locale‑independent string.
 */
public class EggDropResult {

    private final int dpResult;
    private final long dpTimeNs;
    private final int mathResult;
    private final long mathTimeNs;
    private final int bsResult;
    private final long bsTimeNs;

    public EggDropResult(int dpResult, long dpTimeNs,
                         int mathResult, long mathTimeNs,
                         int bsResult, long bsTimeNs) {
        this.dpResult = dpResult;
        this.dpTimeNs = dpTimeNs;
        this.mathResult = mathResult;
        this.mathTimeNs = mathTimeNs;
        this.bsResult = bsResult;
        this.bsTimeNs = bsTimeNs;
    }

    /**
     * Returns a string that contains each solution value and its
     * execution time in nanoseconds.  Numbers are formatted with
     * comma separators for thousands (pattern "#,##0") and the
     * formatting is independent of the system locale.
     *
     * Example:
     * {@code DP: 10 (1,234,567 ns), Math: 10 (1,234,567 ns), Binary Search: 10 (1,234,567 ns)}
     */
    @Override
    public String toString() {
        // DecimalFormat that always uses comma as thousands separator
        DecimalFormatSymbols symbols = DecimalFormatSymbols.getInstance(Locale.US);
        DecimalFormat df = new DecimalFormat("#,##0", symbols);

        return String.format(
                "DP: %s (%s ns), Math: %s (%s ns), Binary Search: %s (%s ns)",
                df.format(dpResult), df.format(dpTimeNs),
                df.format(mathResult), df.format(mathTimeNs),
                df.format(bsResult), df.format(bsTimeNs));
    }
}

