    private static final String PASSWORD_DIGIT_REGEX     = ".*\\d.*";
    private static final String PASSWORD_SPECIAL_REGEX  = ".*[!@#$%^&*()].*";

    /* ---------- Error messages ---------- */
    private static final String MSG_INVALID_EMPLOYEE_DATA = "Invalid employee data";
    private static final String MSG_INVALID_EMAIL_FORMAT  = "Invalid email format";
    private static final String MSG_EMAIL_TOO_LONG        = "Email must be 30 characters or less";

    private static final String MSG_PASSWORD_TOO_SHORT   = "Password must be at least 8 characters long";
    private static final String MSG_PASSWORD_TOO_LONG    = "Password must be at most 255 characters long";
    private static final String MSG_PASSWORD_NO_UPPER    = "Password must contain at least one uppercase letter";
    private static final String MSG_PASSWORD_NO_LOWER    = "Password must contain at least one lowercase letter";
    private static final String MSG_PASSWORD_NO_DIGIT    = "Password must contain at least one digit";
    private static final String MSG_PASSWORD_NO_SPECIAL  = "Password must contain at least one special character (!@#$%^&*())";

    /**
     * Validates the employee data.
     *
     * @param email    the employee's email address
     * @param password the employee's password
     * @param fcmToken the employee's FCM token
     * @throws IllegalArgumentException if any argument is null/empty,
     *                                  if the email is longer than 30 characters,
     *                                  if the email format is invalid,
     *                                  or if the password does not satisfy any rule
     */
    public static void validateEmployee(String email, String password, String fcmToken) {
        /* ---- Null or empty check ---- */
        if (email == null || email.isEmpty() ||
            password == null || password.isEmpty() ||
            fcmToken == null || fcmToken.isEmpty()) {
            throw new IllegalArgumentException(MSG_INVALID_EMPLOYEE_DATA);
        }

        /* ---- Email length check ---- */
        if (email.length() > 30) {
            throw new IllegalArgumentException(MSG_EMAIL_TOO_LONG);
        }

        /* ---- Email format check ---- */
        if (!email.toUpperCase().matches(EMAIL_REGEX)) {
            throw new IllegalArgumentException(MSG_INVALID_EMAIL_FORMAT);
        }

        /* ---- Password length checks ---- */
        if (password.length() < PASSWORD_MIN_LENGTH) {
            throw new IllegalArgumentException(MSG_PASSWORD_TOO_SHORT);
        }
        if (password.length() > PASSWORD_MAX_LENGTH) {
            throw new IllegalArgumentException(MSG_PASSWORD_TOO_LONG);
        }

        /* ---- Password character checks ---- */
        if (!password.matches(PASSWORD_UPPERCASE_REGEX)) {
            throw new IllegalArgumentException(MSG_PASSWORD_NO_UPPER);
        }
        if (!password.matches(PASSWORD_LOWERCASE_REGEX)) {
            throw new IllegalArgumentException(MSG_PASSWORD_NO_LOWER);
        }
        if (!password.matches(PASSWORD_DIGIT_REGEX)) {
            throw new IllegalArgumentException(MSG_PASSWORD_NO_DIGIT);
        }
        if (!password.matches(PASSWORD_SPECIAL_REGEX)) {
            throw new IllegalArgumentException(MSG_PASSWORD_NO_SPECIAL);
        }
    }
}

