import java.util.*;

class AdvancedFlagProcessor {
    private final Set<String> validFlags;
    private final Set<String> mutuallyExclusiveGroups;

    public AdvancedFlagProcessor(Set<String> validFlags, Set<String> mutuallyExclusiveGroups) {
        this.validFlags = new HashSet<>(validFlags);
        this.mutuallyExclusiveGroups = mutuallyExclusiveGroups == null
                ? new HashSet<>() : new HashSet<>(mutuallyExclusiveGroups);
    }

    public Set<String> processFlags(String flagString) {
        Set<String> result = new HashSet<>();

        // Handle null or empty input: return all single-flag possibilities
        if (flagString == null || flagString.trim().isEmpty()) {
            for (String flag : validFlags) {
                result.add("|" + flag);
            }
            return result;
        }

        // Parse existing flags (ignore empty tokens)
        Set<String> existing = new HashSet<>();
        for (String token : flagString.split("\\|")) {
            if (!token.isEmpty()) {
                existing.add(token);
            }
        }

        // Validate mutually exclusive flags
        Set<String> presentMutuallyExclusive = new HashSet<>();
        for (String flag : existing) {
            if (mutuallyExclusiveGroups.contains(flag)) {
                presentMutuallyExclusive.add(flag);
            }
        }
        if (presentMutuallyExclusive.size() > 1) {
            throw new IllegalArgumentException("Mutually exclusive flags detected");
        }

        // Generate new combinations by adding one more valid flag
        for (String flag : validFlags) {
            if (!existing.contains(flag)) {
                StringBuilder sb = new StringBuilder(flagString);
                if (flagString.endsWith("|")) {
                    sb.append(flag);
                } else {
                    sb.append("|").append(flag);
                }
                result.add(sb.toString());
            }
        }

        return result;
    }
}

