import java.util.ArrayList;
import java.util.List;

class SubsetGenerator {

    // Helper class to keep a subset and the index of its last element
    private static class SubsetInfo {
        List<Integer> subset;
        int lastIndex;

        SubsetInfo(List<Integer> subset, int lastIndex) {
            this.subset = subset;
            this.lastIndex = lastIndex;
        }
    }

    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        // Start with the empty subset
        result.add(new ArrayList<>());

        // List of subsets with their last indices
        List<SubsetInfo> infos = new ArrayList<>();
        infos.add(new SubsetInfo(new ArrayList<>(), -1));

        for (int i = 0; i < nums.length; i++) {
            // Work on a snapshot of current infos to avoid interference
            int currentSize = infos.size();
            for (int j = 0; j < currentSize; j++) {
                SubsetInfo info = infos.get(j);
                // Only extend subsets that end before the current index
                // and are smaller than size 2
                if (info.lastIndex < i && info.subset.size() < 2) {
                    List<Integer> newSubset = new ArrayList<>(info.subset);
                    newSubset.add(nums[i]);
                    result.add(newSubset);
                    infos.add(new SubsetInfo(newSubset, i));
                }
            }
        }

        return result;
    }
}

