import java.util.Arrays;
import java.util.Comparator;

class EnhancedMergeSort {

    /**
     * Sorts the given Integer array in ascending order using merge sort.
     *
     * @param array the array to sort
     * @return a new sorted array
     * @throws IllegalArgumentException if the input array is null
     */
    public Integer[] sortIntegers(Integer[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }

        // Base case: arrays with 0 or 1 element are already sorted
        if (array.length <= 1) {
            return array;
        }

        // Divide the array into two halves
        int mid = array.length / 2;
        Integer[] left = Arrays.copyOfRange(array, 0, mid);
        Integer[] right = Arrays.copyOfRange(array, mid, array.length);

        // Recursively sort each half
        Integer[] sortedLeft = sortIntegers(left);
        Integer[] sortedRight = sortIntegers(right);

        // Merge the sorted halves
        return merge(sortedLeft, sortedRight);
    }

    /**
     * Merges two sorted Integer arrays into a single sorted array.
     *
     * @param left  the first sorted array
     * @param right the second sorted array
     * @return a new array containing all elements from left and right, sorted
     */
    private Integer[] merge(Integer[] left, Integer[] right) {
        Integer[] result = new Integer[left.length + right.length];
        int i = 0, j = 0, k = 0;

        // Merge elements from left and right in ascending order
        while (i < left.length && j < right.length) {
            if (Comparator.naturalOrder().compare(left[i], right[j]) <= 0) {
                result[k++] = left[i++];
            } else {
                result[k++] = right[j++];
            }
        }

        // Copy any remaining elements from left
        while (i < left.length) {
            result[k++] = left[i++];
        }

        // Copy any remaining elements from right
        while (j < right.length) {
            result[k++] = right[j++];
        }

        return result;
    }
}

