import java.util.Arrays;
import java.util.Comparator;
import java.lang.reflect.Array;

class EnhancedMergeSort {

    /* ---------- Integer specific sort (uses generic merge helper) ---------- */
    public Integer[] sortIntegers(Integer[] array) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        if (array.length <= 1) {
            return array;
        }

        int mid = array.length / 2;
        Integer[] left  = Arrays.copyOfRange(array, 0, mid);
        Integer[] right = Arrays.copyOfRange(array, mid, array.length);

        Integer[] sortedLeft  = sortIntegers(left);
        Integer[] sortedRight = sortIntegers(right);

        Integer[] result = new Integer[sortedLeft.length + sortedRight.length];
        merge(sortedLeft, sortedRight, result, Comparator.naturalOrder(), true);
        return result;
    }

    /* ---------- Generic merge‑sort implementation ---------- */
    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }
        if (array.length <= 1) {
            return array;
        }

        int mid = array.length / 2;
        T[] left  = Arrays.copyOfRange(array, 0, mid);
        T[] right = Arrays.copyOfRange(array, mid, array.length);

        T[] sortedLeft  = sort(left, comparator, ascending);
        T[] sortedRight = sort(right, comparator, ascending);

        @SuppressWarnings("unchecked")
        T[] result = (T[]) Array.newInstance(
                array.getClass().getComponentType(),
                sortedLeft.length + sortedRight.length);

        merge(sortedLeft, sortedRight, result, comparator, ascending);
        return result;
    }

    /* ---------- Generic stable merge helper ---------- */
    private <T> void merge(T[] left, T[] right, T[] target,
                           Comparator<? super T> comparator, boolean ascending) {
        int i = 0, j = 0, k = 0;
        while (i < left.length && j < right.length) {
            int cmp = comparator.compare(left[i], right[j]);

            boolean takeLeft;
            if (ascending) {
                // For ascending order, take left when cmp <= 0 (stable on equal)
                takeLeft = cmp <= 0;
            } else {
                // For descending order, take left when cmp >= 0 (stable on equal)
                takeLeft = cmp >= 0;
            }

            if (takeLeft) {
                target[k++] = left[i++];
            } else {
                target[k++] = right[j++];
            }
        }

        // Copy any remaining elements
        while (i < left.length) {
            target[k++] = left[i++];
        }
        while (j < right.length) {
            target[k++] = right[j++];
        }
    }
