import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

public class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private int realmId;
    private int imageId;
    private int hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, int realmId, int imageId, int hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    /**
     * Validates the configuration of the server.
     *
     * @return a map where the key is the configuration field name and the value is true if valid, false otherwise.
     */
    public Map<String, Boolean> validateConfiguration() {
        Map<String, Boolean> results = new HashMap<>();
        results.put("serverName", serverName != null && !serverName.isEmpty());
        results.put("serverIp", isValidIp(serverIp));
        results.put("realmId", realmId > 0);
        results.put("imageId", imageId > 0);
        results.put("hardwareProfileId", hardwareProfileId > 0);
        return results;
    }

    /**
     * Checks if the provided IP address is a valid IPv4 address.
     *
     * @param ip the IP address string
     * @return true if valid, false otherwise
     */
    private boolean isValidIp(String ip) {
        if (ip == null) return false;
        String[] parts = ip.split("\\.");
        if (parts.length != 4) return false;
        try {
            for (String part : parts) {
                int val = Integer.parseInt(part);
                if (val < 0 || val > 255) return false;
            }
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    /**
     * Processes the approval of the server configuration.
     *
     * @return a map containing the approval status, a message, and the validation results.
     */
    public Map<String, Object> processApproval() {
        Map<String, Boolean> validationResults = validateConfiguration();
        boolean allValid = validationResults.values().stream().allMatch(v -> v);
        String message = allValid ? "All configurations are valid." : "Some configurations are invalid.";
        approvalStatus.put("status", allValid ? "Approved" : "Rejected");

        Map<String, Object> result = new HashMap<>();
        result.put("approvalStatus", approvalStatus);
        result.put("message", message);
        result.put("validationResults", validationResults);
        return result;
    }

    // Optional: Getters for the fields (if needed)
    public String getServerName() { return serverName; }
    public String getServerIp() { return serverIp; }
    public int getRealmId() { return realmId; }
    public int getImageId() { return imageId; }
    public int getHardwareProfileId() { return hardwareProfileId; }
}

