        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    /**
     * Validates the configuration of the server.
     *
     * @return a map where the key is the configuration field name and the value is true if valid, false otherwise.
     */
    public Map<String, Boolean> validateConfiguration() {
        Map<String, Boolean> results = new HashMap<>();
        results.put("serverName", validateServerName().equals("Valid"));
        results.put("serverIp", validateIpAddress().equals("Valid"));
        results.put("realmId", validateRealmId().equals("Valid"));
        results.put("imageId", validateImageId().equals("Valid"));
        results.put("hardwareProfileId", validateHardwareProfile().equals("Valid"));
        return results;
    }

    /**
     * Validates the server name.
     *
     * @return "Valid" if the server name is non‑null, non‑empty, and at most 64 characters long;
     *         otherwise an error message describing the failure.
     */
    private String validateServerName() {
        if (serverName == null || serverName.isEmpty()) {
            return "Server name must not be null or empty.";
        }
        if (serverName.length() > 64) {
            return "Server name must not exceed 64 characters.";
        }
        return "Valid";
    }

    /**
     * Validates the IP address using a regular expression.
     *
     * @return "Valid" if the IP address matches the IPv4 pattern; otherwise an error message.
     */
    private String validateIpAddress() {
        if (serverIp == null) {
            return "IP address must not be null.";
        }
        String ipv4Pattern =
                "^(?:(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)\\.){3}" +
                "(?:25[0-5]|2[0-4]\\d|[01]?\\d?\\d)$";
        if (serverIp.matches(ipv4Pattern)) {
            return "Valid";
        } else {
            return "Invalid IP address format.";
        }
    }

