    private String validateRealmId() {
        if (realmId == null) {
            return "Realm ID must not be null.";
        }
        String realmPattern = "^[A-Za-z0-9-]{1,36}$";
        if (realmId.matches(realmPattern)) {
            return "Valid";
        } else {
            return "Realm ID must be 1-36 characters long and contain only alphanumeric characters or hyphens.";
        }
    }

    /**
     * Validates the image ID format: 'img-' followed by exactly 8 alphanumeric characters.
     *
     * @return "Valid" if the image ID matches the pattern; otherwise an error message.
     */
    private String validateImageId() {
        if (imageId == null) {
            return "Image ID must not be null.";
        }
        String imagePattern = "^img-[A-Za-z0-9]{8}$";
        if (imageId.matches(imagePattern)) {
            return "Valid";
        } else {
            return "Image ID must start with 'img-' followed by exactly 8 alphanumeric characters.";
        }
    }

    /**
     * Validates the hardware profile ID format: 'hw-' followed by 4 alphanumerics, a hyphen, and another 4 alphanumerics.
     *
     * @return "Valid" if the hardware profile ID matches the pattern; otherwise an error message.
     */
    private String validateHardwareProfile() {
        if (hardwareProfileId == null) {
            return "Hardware profile ID must not be null.";
        }
        String hwPattern = "^hw-[A-Za-z0-9]{4}-[A-Za-z0-9]{4}$";
        if (hardwareProfileId.matches(hwPattern)) {
            return "Valid";
        } else {
            return "Hardware profile ID must start with 'hw-' followed by 4 alphanumerics, a hyphen, and another 4 alphanumerics.";
        }
    }

    /**
     * Processes the approval of the server configuration.
     *
     * @return a map containing the approval status, a message, and the validation results.
     */
    public Map<String, Object> processApproval() {
        Map<String, Boolean> validationResults = validateConfiguration();
        boolean allValid = validationResults.values().stream().allMatch(v -> v);
        String message = allValid ? "All configurations are valid." : "Some configurations are invalid.";
        approvalStatus.put("status", allValid ? "Approved" : "Rejected");

        Map<String, Object> result = new HashMap<>();
        result.put("approvalStatus", approvalStatus);
        result.put("message", message);
        result.put("validationResults", validationResults);
        return result;
    }

    // Getters (optional)
    public String getServerName() { return serverName; }
    public String getServerIp() { return serverIp; }
    public String getRealmId() { return realmId; }
    public String getImageId() { return imageId; }
    public String getHardwareProfileId() { return hardwareProfileId; }
}

