import java.util.*;

class GraphAnalyzer {
    private final Map<String, List<Edge>> adjacencyList;
    private final boolean directed;
    private final boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.directed = directed;
        this.weighted = weighted;
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(String node) {
        adjacencyList.putIfAbsent(node, new ArrayList<>());
    }

    public void addEdge(String from, String to, int weight) {
        // Ensure both nodes exist
        addNode(from);
        addNode(to);

        int actualWeight = weighted ? weight : 1; // default weight for unweighted graphs
        adjacencyList.get(from).add(new Edge(to, actualWeight));

        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, actualWeight));
        }
    }

    // Optional helper to retrieve adjacency list (for testing or further analysis)
    public Map<String, List<Edge>> getAdjacencyList() {
        return adjacencyList;
    }

    static class Edge {
        private final String destination;
        private final int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }

        public String getDestination() {
            return destination;
        }

        public int getWeight() {
            return weight;
        }

        @Override
        public String toString() {
            return destination + (weight != 1 ? " (" + weight + ")" : "");
        }
    }
}

