import java.util.*;

class GraphAnalyzer {
    private final Map<String, List<Edge>> adjacencyList;
    private final boolean directed;
    private final boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.directed = directed;
        this.weighted = weighted;
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(String node) {
        adjacencyList.putIfAbsent(node, new ArrayList<>());
    }

    public void addEdge(String from, String to, int weight) {
        // Ensure both nodes exist
        addNode(from);
        addNode(to);

        int actualWeight = weighted ? weight : 1; // default weight for unweighted graphs
        adjacencyList.get(from).add(new Edge(to, actualWeight));

        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, actualWeight));
        }
    }

    /**
     * Returns the number of edges connected to the specified node.
     * For directed graphs this is the out‑degree (number of outgoing edges).
     *
     * @param node the node whose degree is requested
     * @return the degree of the node
     * @throws IllegalArgumentException if the node does not exist
     */
    public int getNodeDegree(String node) {
        List<Edge> edges = adjacencyList.get(node);
        if (edges == null) {
            throw new IllegalArgumentException("Node '" + node + "' does not exist in the graph.");
        }
        return edges.size();
    }

    /**
     * Detects whether the graph contains any cycle.
     *
     * @return true if a cycle exists, false otherwise
     */
    public boolean hasCycle() {
        if (directed) {
            return hasCycleDirected();
        } else {
            return hasCycleUndirected();
        }
    }

    /* ---------- Cycle detection for directed graphs ---------- */
    private boolean hasCycleDirected() {
        Set<String> visited = new HashSet<>();
        Set<String> recStack = new HashSet<>();

        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (dfsDirected(node, visited, recStack)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfsDirected(String node, Set<String> visited, Set<String> recStack) {
        visited.add(node);
        recStack.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsDirected(neighbor, visited, recStack)) {
                    return true;
                }
            } else if (recStack.contains(neighbor)) {
                return true; // back edge found
            }
        }

        recStack.remove(node);
        return false;
    }

    /* ---------- Cycle detection for undirected graphs ---------- */
    private boolean hasCycleUndirected() {
        Set<String> visited = new HashSet<>();

        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (dfsUndirected(node, visited, null)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfsUndirected(String node, Set<String> visited, String parent) {
        visited.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsUndirected(neighbor, visited, node)) {
                    return true;
                }
            } else if (!neighbor.equals(parent)) {
                return true; // found a back edge to a non-parent node
            }
        }
        return false;
    }

    /* ---------- Edge representation ---------- */
    static class Edge {
        private final String destination;
        private final int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }

        public String getDestination() {
            return destination;
        }

        public int getWeight() {
            return weight;
        }

        @Override
        public String toString() {
            return destination + (weight != 1 ? " (" + weight + ")" : "");
        }
    }

    /* ---------- Optional helper ---------- */
    public Map<String, List<Edge>> getAdjacencyList() {
        return adjacencyList;
    }
}

