import java.util.*;

class GraphAnalyzer {
    private final Map<String, List<Edge>> adjacencyList;
    private final boolean directed;
    private final boolean weighted;

    public GraphAnalyzer(boolean directed, boolean weighted) {
        this.directed = directed;
        this.weighted = weighted;
        this.adjacencyList = new HashMap<>();
    }

    public void addNode(String node) {
        adjacencyList.putIfAbsent(node, new ArrayList<>());
    }

    public void addEdge(String from, String to, int weight) {
        // Ensure both nodes exist
        addNode(from);
        addNode(to);

        int actualWeight = weighted ? weight : 1; // default weight for unweighted graphs
        adjacencyList.get(from).add(new Edge(to, actualWeight));

        if (!directed) {
            adjacencyList.get(to).add(new Edge(from, actualWeight));
        }
    }

    public int getNodeDegree(String node) {
        List<Edge> edges = adjacencyList.get(node);
        if (edges == null) {
            throw new IllegalArgumentException("Node '" + node + "' does not exist in the graph.");
        }
        return edges.size();
    }

    public boolean hasCycle() {
        if (directed) {
            return hasCycleDirected();
        } else {
            return hasCycleUndirected();
        }
    }

    /* ---------- Cycle detection for directed graphs ---------- */
    private boolean hasCycleDirected() {
        Set<String> visited = new HashSet<>();
        Set<String> recStack = new HashSet<>();

        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (dfsDirected(node, visited, recStack)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfsDirected(String node, Set<String> visited, Set<String> recStack) {
        visited.add(node);
        recStack.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsDirected(neighbor, visited, recStack)) {
                    return true;
                }
            } else if (recStack.contains(neighbor)) {
                return true; // back edge found
            }
        }

        recStack.remove(node);
        return false;
    }

    /* ---------- Cycle detection for undirected graphs ---------- */
    private boolean hasCycleUndirected() {
        Set<String> visited = new HashSet<>();

        for (String node : adjacencyList.keySet()) {
            if (!visited.contains(node)) {
                if (dfsUndirected(node, visited, null)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfsUndirected(String node, Set<String> visited, String parent) {
        visited.add(node);

        for (Edge e : adjacencyList.get(node)) {
            String neighbor = e.destination;
            if (!visited.contains(neighbor)) {
                if (dfsUndirected(neighbor, visited, node)) {
                    return true;
                }
            } else if (!neighbor.equals(parent)) {
                return true; // found a back edge to a non-parent node
            }
        }
        return false;
    }

    /**
     * Finds the shortest path between {@code start} and {@code end} using Dijkstra's algorithm.
     *
     * @param start the starting node
     * @param end   the destination node
     * @return a list of node names representing the shortest path (inclusive of start and end),
     *         or an empty list if no path exists.
     * @throws IllegalArgumentException if either {@code start} or {@code end} does not exist.
     */
    public List<String> findShortestPath(String start, String end) {
        if (!adjacencyList.containsKey(start) || !adjacencyList.containsKey(end)) {
            throw new IllegalArgumentException("Start or end node does not exist in the graph.");
        }

        // Dijkstra's algorithm
        Map<String, Integer> dist = new HashMap<>();
        Map<String, String> prev = new HashMap<>();
        PriorityQueue<NodeDist> pq = new PriorityQueue<>(Comparator.comparingInt(nd -> nd.distance));

        for (String node : adjacencyList.keySet()) {
            dist.put(node, Integer.MAX_VALUE);
        }
        dist.put(start, 0);
        pq.offer(new NodeDist(start, 0));

        while (!pq.isEmpty()) {
            NodeDist current = pq.poll();
            if (current.distance > dist.get(current.node)) {
                continue; // stale entry
            }
            if (current.node.equals(end)) {
                break; // reached destination
            }

            for (Edge e : adjacencyList.get(current.node)) {
                int alt = dist.get(current.node) + e.weight;
                if (alt < dist.get(e.destination)) {
                    dist.put(e.destination, alt);
                    prev.put(e.destination, current.node);
                    pq.offer(new NodeDist(e.destination, alt));
                }
            }
        }

        if (!prev.containsKey(end) && !start.equals(end)) {
            return Collections.emptyList(); // no path
        }

        // Reconstruct path
        LinkedList<String> path = new LinkedList<>();
        String at = end;
        path.addFirst(at);
        while (prev.containsKey(at)) {
            at = prev.get(at);
            path.addFirst(at);
        }

        return path;
    }

    /* ---------- Edge representation ---------- */
    static class Edge {
        private final String destination;
        private final int weight;

        public Edge(String destination, int weight) {
            this.destination = destination;
            this.weight = weight;
        }

        public String getDestination() {
            return destination;
        }

        public int getWeight() {
            return weight;
        }

        @Override
        public String toString() {
            return destination + (weight != 1 ? " (" + weight + ")" : "");
        }
    }

    /* ---------- Helper class for priority queue ---------- */
    private static class NodeDist {
        final String node;
        final int distance;

        NodeDist(String node, int distance) {
            this.node = node;
            this.distance = distance;
        }
    }

    /* ---------- Optional helper ---------- */
    public Map<String, List<Edge>> getAdjacencyList() {
        return adjacencyList;
    }
}

