import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {

    // Hexadecimal lookup table for uppercase conversion
    private static final char[] HEX_TABLE = "0123456789ABCDEF".toCharArray();

    /**
     * Generates a secure payment URL by appending the provided parameters
     * in alphabetical order. The method validates the base URL and secret,
     * and uses the secret to compute an MD5 hash of the non‑empty parameter
     * values (sorted by key). The hash is not added to the URL yet but
     * demonstrates how the secret can be used for future security checks.
     *
     * @param baseUrl    the base URL to which parameters will be appended
     * @param secret     a secret key used for hash generation
     * @param parameters a map of query parameters
     * @return the complete URL with encoded parameters
     * @throws IllegalArgumentException if baseUrl or secret is null/empty
     */
    public String generateSecurePaymentUrl(String baseUrl, String secret,
                                           Map<String, String> parameters) {
        // Input validation
        if (baseUrl == null || baseUrl.isEmpty()) {
            throw new IllegalArgumentException("baseUrl cannot be null or empty");
        }
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("secret cannot be null or empty");
        }

        // Compute the MD5 hash using the secret and sorted non‑empty values
        String hash = generateSecureHash(secret, parameters);
        // The hash can be used later for verification or added to the URL
        // For now, we simply compute it to satisfy the requirement of using the secret.

        // Build the URL with sorted, encoded parameters
        if (parameters == null || parameters.isEmpty()) {
            return baseUrl;
        }

        StringBuilder urlBuilder = new StringBuilder(baseUrl);
        boolean hasQuery = baseUrl.contains("?");
        urlBuilder.append(hasQuery ? "&" : "?");

        List<String> keys = new ArrayList<>(parameters.keySet());
        Collections.sort(keys);

        boolean first = true;
        for (String key : keys) {
            if (!first) {
                urlBuilder.append("&");
            }
            try {
                urlBuilder.append(URLEncoder.encode(key, "UTF-8"));
                urlBuilder.append("=");
                urlBuilder.append(URLEncoder.encode(parameters.get(key), "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // UTF‑8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
            first = false;
        }

        return urlBuilder.toString();
    }

    /**
     * Creates an MD5 hash from the secret key concatenated with all
     * non‑empty parameter values in sorted order.
     *
     * @param secret     the secret key
     * @param parameters the parameters to include in the hash
     * @return an uppercase hexadecimal string representation of the hash
     */
    private String generateSecureHash(String secret, Map<String, String> parameters) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            List<String> keys = new ArrayList<>(parameters.keySet());
            Collections.sort(keys);

            StringBuilder sb = new StringBuilder();
            sb.append(secret);
            for (String key : keys) {
                String value = parameters.get(key);
                if (value != null && !value.isEmpty()) {
                    sb.append(value);
                }
            }

            byte[] digest = md.digest(sb.toString().getBytes("UTF-8"));
            return bytesToHex(digest);
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            // These exceptions should never occur; wrap in unchecked exception
            throw new RuntimeException(e);
        }
    }

    /**
     * Converts a byte array to an uppercase hexadecimal string using HEX_TABLE.
     *
     * @param bytes the byte array to convert
     * @return the resulting hexadecimal string
     */
    private String bytesToHex(byte[] bytes) {
        char[] hexChars = new char[bytes.length * 2];
        for (int i = 0; i < bytes.length; i++) {
            int v = bytes[i] & 0xFF;
            hexChars[i * 2] = HEX_TABLE[v >>> 4];
            hexChars[i * 2 + 1] = HEX_TABLE[v & 0x0F];
        }
        return new String(hexChars);
