import java.util.*;
import java.net.URLEncoder;
import java.io.UnsupportedEncodingException;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;

class SecurePaymentProcessor {

    /**
     * Generates a secure payment URL by appending the provided parameters
     * in alphabetical order. A HMAC‑SHA256 hash of the sorted query string
     * (excluding empty values) is calculated using the supplied secret
     * and added to the URL as the parameter {@code vpc_SecureHash}.
     *
     * @param baseUrl the base URL to which parameters will be appended
     * @param params  a map of request parameters (excluding the hash)
     * @param secret  the secret key used for HMAC‑SHA256 hash generation
     * @return the complete URL with encoded parameters and the secure hash
     * @throws IllegalArgumentException if the secret is null or empty
     * @throws RuntimeException         if hash computation fails
     */
    public String generateSecurePaymentUrl(String baseUrl,
                                           Map<String, String> params,
                                           String secret) {
        // Validate secret
        if (secret == null || secret.isEmpty()) {
            throw new IllegalArgumentException("Secret key must not be null or empty");
        }

        // Prepare sorted keys (case‑sensitive)
        List<String> sortedKeys = new ArrayList<>();
        if (params != null) {
            sortedKeys.addAll(params.keySet());
        }
        Collections.sort(sortedKeys);

        // Build query string for hash calculation (skip empty values)
        StringBuilder queryForHash = new StringBuilder();
        for (String key : sortedKeys) {
            String value = params.get(key);
            if (value != null && !value.isEmpty()) {
                if (queryForHash.length() > 0) {
                    queryForHash.append('&');
                }
                queryForHash.append(key).append('=').append(value);
            }
        }

        // Compute HMAC‑SHA256 hash
        String hashHex;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(secret.getBytes("UTF-8"), "HmacSHA256");
            mac.init(keySpec);
            byte[] hashBytes = mac.doFinal(queryForHash.toString().getBytes("UTF-8"));
            hashHex = bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException | InvalidKeyException | UnsupportedEncodingException e) {
            throw new RuntimeException("Failed to generate secure hash: " + e.getMessage(), e);
        }

        // Build final URL with encoded parameters and the hash
        StringBuilder urlBuilder = new StringBuilder(baseUrl);
        boolean hasQuery = baseUrl.contains("?");
        urlBuilder.append(hasQuery ? "&" : "?");

        boolean firstParam = true;
        for (String key : sortedKeys) {
            String value = params.get(key);
            if (value == null || value.isEmpty()) {
                continue; // Skip empty values
            }
            if (!firstParam) {
                urlBuilder.append('&');
            }
            try {
                urlBuilder.append(URLEncoder.encode(key, "UTF-8"))
                          .append('=')
                          .append(URLEncoder.encode(value, "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                // UTF‑8 is guaranteed to be supported
                throw new RuntimeException(e);
            }
            firstParam = false;
        }

        // Append the secure hash parameter
        if (!firstParam) {
            urlBuilder.append('&');
        }
        try {
            urlBuilder.append(URLEncoder.encode("vpc_SecureHash", "UTF-8"))
                      .append('=')
                      .append(URLEncoder.encode(hashHex, "UTF-8"));
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }

        return urlBuilder.toString();
    }

    /**
     * Converts a byte array to a lowercase hexadecimal string.
     *
     * @param bytes the byte array to convert
     * @return the resulting hexadecimal string
     */
    private String bytesToHex(byte[] bytes) {
        StringBuilder hex = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            hex.append(String.format("%02x", b));
        }
        return hex.toString();
    }
}

