import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Utility class providing enhanced test utilities.
 */
public final class EnhancedTestUtils {

    // Private constructor to prevent instantiation
    private EnhancedTestUtils() {
        throw new AssertionError("Utility class");
    }

    /**
     * Creates a list containing {@code count} elements generated by the supplied {@link Supplier}.
     * If a {@link Consumer} validator is provided, it is invoked for each generated element.
     * Any {@link RuntimeException} thrown by the validator is wrapped in a new {@link RuntimeException}
     * and rethrown.
     *
     * @param count     the number of elements to generate; must be non‑negative
     * @param supplier  the supplier used to generate each element; must not be {@code null}
     * @param validator an optional validator invoked on each generated element; may be {@code null}
     * @param <T>       the type of elements in the resulting list
     * @return a {@link List} containing {@code count} elements produced by {@code supplier}
     * @throws IllegalArgumentException if {@code count} is negative
     * @throws NullPointerException     if {@code supplier} is {@code null}
     * @throws RuntimeException         if the validator throws a {@link RuntimeException}
     */
    public static <T> List<T> createEnhancedList(int count, Supplier<T> supplier, Consumer<T> validator) {
        if (count < 0) {
            throw new IllegalArgumentException("Count must be non-negative, but was: " + count);
        }
        if (supplier == null) {
            throw new NullPointerException("Supplier must not be null");
        }

        List<T> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            T element = supplier.get();
            if (validator != null) {
                try {
                    validator.accept(element);
                } catch (RuntimeException re) {
                    throw new RuntimeException(re);
                }
            }
            result.add(element);
        }
        return result;
    }
}

