import java.util.ArrayList;
import java.util.List;

/**
 * Interface representing a unit test.
 */
public interface UnitTest {
    /**
     * Executes the test logic.
     *
     * @throws Exception if the test fails.
     */
    void runTest() throws Exception;

    /**
     * Returns the name of the test.
     *
     * @return test name.
     */
    String getTestName();
}

/**
 * Runner that manages and executes unit tests.
 */
public class UnitTestRunner {
    private final List<UnitTest> tests = new ArrayList<>();

    /**
     * Adds a test to the runner.
     *
     * @param test the UnitTest to add.
     */
    public void addTest(UnitTest test) {
        tests.add(test);
    }

    /**
     * Runs all added tests and returns the number of tests executed.
     *
     * @return the count of tests run.
     */
    public int runAllTests() {
        int count = 0;
        for (UnitTest test : tests) {
            try {
                test.runTest();
                System.out.println("PASS: " + test.getTestName());
            } catch (Exception e) {
                System.out.println("FAIL: " + test.getTestName() + " - " + e.getMessage());
            }
            count++;
        }
        return count;
    }
}

/**
 * Example implementation of a simple unit test.
 */
class SampleTest implements UnitTest {
    private final String name;

    public SampleTest(String name) {
        this.name = name;
    }

    @Override
    public void runTest() throws Exception {
        // Simple assertion: name must not be null or empty.
        if (name == null || name.isEmpty()) {
            throw new Exception("Test name is invalid");
        }
    }

    @Override
    public String getTestName() {
        return name;
    }
}

/**
 * Demo of using the UnitTestRunner.
 */
class Main {
    public static void main(String[] args) {
        UnitTestRunner runner = new UnitTestRunner();

        // Add some sample tests
        runner.addTest(new SampleTest("Test 1"));
        runner.addTest(new SampleTest(""));          // This will fail
        runner.addTest(new SampleTest("Test 3"));

        int total = runner.runAllTests();
        System.out.println("Total tests run: " + total);
    }
}

