import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> result = new ArrayList<>();

        // Upper half (including the middle line)
        for (int line = 1; line <= size; line++) {
            result.add(buildLine(line, size));
        }

        // Lower half (mirror of the upper half, excluding the middle line)
        for (int line = size - 1; line >= 1; line--) {
            result.add(buildLine(line, size));
        }

        // Optional reverse of the entire pattern
        if (reverse) {
            Collections.reverse(result);
        }

        return result;
    }

    // Helper method to build a single line of the sand clock
