import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

/**
 * A simple alerting service that tracks the number of alerts per severity level,
 * stores the most recent alert message for each level, and notifies registered
 * listeners when an alert is triggered.
 */
public class AlertingService {

    /** Maps a severity level to the number of alerts triggered for that level. */
    private final Map<String, Integer> alertCounts = new HashMap<>();

    /** Maps a severity level to the most recent alert message for that level. */
    private final Map<String, String> lastAlertMessages = new HashMap<>();

    /**
     * Stores alert listeners. The key is a composite of {@code listenerId} and
     * {@code level} separated by a pipe character. The value is the callback
     * that should be invoked when an alert of that level is triggered.
     */
    private final Map<String, Consumer<String>> listeners = new HashMap<>();

    /**
     * Triggers an alert for the given severity level with the provided message.
     * The alert count for the level is incremented, the message is stored as the
     * most recent alert for that level, and all listeners registered for that
     * level are notified.
     *
     * @param level   the severity level of the alert (e.g., "INFO", "WARN", "ERROR")
     * @param message the alert message
     */
    public void triggerAlert(String level, String message) {
        if (level == null || message == null) {
            throw new IllegalArgumentException("Level and message must not be null");
        }

        // Increment the count for this level
        alertCounts.merge(level, 1, Integer::sum);

        // Store the most recent message
        lastAlertMessages.put(level, message);

        // Notify listeners registered for this level
        String levelKey = "|" + level;
        for (Map.Entry<String, Consumer<String>> entry : listeners.entrySet()) {
            if (entry.getKey().endsWith(levelKey)) {
                try {
                    entry.getValue().accept(message);
                } catch (Exception e) {
                    // Listener exceptions should not affect the service
                    System.err.println("Listener " + entry.getKey() + " threw an exception: " + e.getMessage());
                }
            }
        }
    }

    /**
     * Registers a listener callback for a specific alert level.
     *
     * @param listenerId a unique identifier for the listener
     * @param level      the severity level the listener is interested in
     * @param callback   the callback to invoke when an alert of the specified level is triggered
     */
    public void addAlertListener(String listenerId, String level, Consumer<String> callback) {
        if (listenerId == null || level == null || callback == null) {
            throw new IllegalArgumentException("Listener ID, level, and callback must not be null");
        }
        String key = listenerId + "|" + level;
        listeners.put(key, callback);
    }

    /**
