    private final Map<String, Consumer<String>> listeners = new ConcurrentHashMap<>();

    /**
     * Triggers an alert for the given severity level with the provided message.
     * The alert count for the level is incremented atomically, the message is
     * stored as the most recent alert for that level, and all listeners
     * registered for that level are notified.
     *
     * @param level   the severity level of the alert (e.g., "INFO", "WARN", "ERROR")
     * @param message the alert message
     */
    public void triggerAlert(String level, String message) {
        if (level == null || message == null) {
            throw new IllegalArgumentException("Level and message must not be null");
        }

        // Increment the count for this level atomically
        alertCounts.computeIfAbsent(level, k -> new AtomicInteger(0)).incrementAndGet();

        // Store the most recent message
        lastAlertMessages.put(level, message);

        // Notify listeners registered for this level
        String levelKey = "|" + level;
        for (Map.Entry<String, Consumer<String>> entry : listeners.entrySet()) {
            if (entry.getKey().endsWith(levelKey)) {
                try {
                    entry.getValue().accept(message);
                } catch (Exception e) {
                    // Listener exceptions should not affect the service
                    System.err.println("Listener " + entry.getKey() + " threw an exception: " + e.getMessage());
                }
            }
        }
    }

    /**
     * Registers a listener callback for a specific alert level.
     * If this is the first time the level is seen, its count is initialized to zero.
     *
     * @param listenerId a unique identifier for the listener
     * @param level      the severity level the listener is interested in
     * @param callback   the callback to invoke when an alert of the specified level is triggered
     */
    public void addAlertListener(String listenerId, String level, Consumer<String> callback) {
        if (listenerId == null || level == null || callback == null) {
            throw new IllegalArgumentException("Listener ID, level, and callback must not be null");
        }

        // Ensure the level is initialized in the count map
        alertCounts.computeIfAbsent(level, k -> new AtomicInteger(0));

        String key = listenerId + "|" + level;
        listeners.put(key, callback);
    }

    /**
     * Unregisters a listener for a specific alert level.
     * If no such listener is registered, the method does nothing.
     *
     * @param listenerId the unique identifier of the listener to remove
     * @param level      the severity level the listener was registered for
     */
    public void removeAlertListener(String listenerId, String level) {
        if (listenerId == null || level == null) {
            throw new IllegalArgumentException("Listener ID and level must not be null");
        }
        String key = listenerId + "|" + level;
        listeners.remove(key); // silently does nothing if key is absent
    }

    /**
     * Returns the number of alerts that have been triggered for the specified level.
     *
     * @param level the severity level
     * @return the alert count, or 0 if no alerts have been recorded for this level
     */
    public int getAlertCount(String level) {
        if (level == null) {
            throw new IllegalArgumentException("Level must not be null");
        }
        AtomicInteger count = alertCounts.get(level);
        return count == null ? 0 : count.get();
    }

    /**
     * Retrieves the most recent alert message for the specified level.
     *
     * @param level the severity level
     * @return the last alert message, or {@code null} if no alert has been recorded for this level
     */
    public String getLastAlertMessage(String level) {
        if (level == null) {
            throw new IllegalArgumentException("Level must not be null");
        }
        return lastAlertMessages.get(level);
    }

    /**
     * Resets all alert statistics, clearing both counts and last messages.
     */
    public void resetStatistics() {
        alertCounts.clear();
        lastAlertMessages.clear();
    }
}
