     * @param supplier a supplier that provides the bean instance
     * @param <T>      the type of the bean
     */
    public <T> void registerBean(String name, Supplier<T> supplier) {
        beans.put(name, supplier.get());
    }

    /**
     * Retrieves a bean by its name.
     *
     * @param name the name of the bean to retrieve
     * @return the bean instance, or {@code null} if no bean with that name exists
     */
    public Object getBean(String name) {
        return beans.get(name);
    }

    /**
     * Retrieves a bean by its name and casts it to the requested type.
     *
     * @param name  the name of the bean to retrieve
     * @param clazz the expected class of the bean
     * @param <T>   the type of the bean
     * @return the bean instance cast to {@code T}, or {@code null} if no bean
     *         with that name exists
     * @throws ClassCastException if the bean cannot be cast to {@code T}
     */
    @SuppressWarnings("unchecked")
    public <T> T getBean(String name, Class<T> clazz) {
        Object bean = beans.get(name);
        if (bean == null) {
            return null;
        }
        return clazz.cast(bean);
    }

    /* ---------- Property management ---------- */

    /** List of configuration file paths that have been loaded. */
    private final List<String> configFiles = new ArrayList<>();

    /** Internal properties store. */
    private final Properties properties = new Properties();

    /**
     * Simulates loading a properties file. The file path is stored in the
     * {@link #configFiles} list. If the path contains the substring
     * {@code "config.properties"}, dummy properties are added:
     * <ul>
     *   <li>url = http://example.com</li>
     *   <li>timeout = 30</li>
     * </ul>
     *
