class RoleManager {
    private Set<String> validRoles;
    private List<String> allowedRoles;
    private List<String> disallowedRoles;
    private boolean strictMode;

    public RoleManager(Set<String> validRoles, boolean strictMode) {
        this.validRoles = new HashSet<>(validRoles);
        this.allowedRoles = new ArrayList<>();
        this.disallowedRoles = new ArrayList<>();
        this.strictMode = strictMode;
    }

    /**
     * Checks whether a user has access.
     * <p>
     * Access is denied if any of the user's roles are in {@code disallowedRoles}.
     * If {@code allowedRoles} is empty, access is granted by default (unless a
     * disallowed role is present). Otherwise, access is granted only if at least
     * one of the user's roles is in {@code allowedRoles}.
     *
     * @param userRoles the set of roles possessed by the user
     * @return {@code true} if access is allowed, {@code false} otherwise
     */
    public boolean isAccessAllowed(Set<String> userRoles) {
        // Deny immediately if any disallowed role is present
        for (String role : disallowedRoles) {
            if (userRoles.contains(role)) {
                return false;
            }
        }

        // If no allowed roles are defined, grant access by default
        if (allowedRoles.isEmpty()) {
            return true;
        }

        // Grant if any allowed role is present
        for (String role : allowedRoles) {
            if (userRoles.contains(role)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Sets the allowed roles from a comma‑separated string.
     *
     * @param roles comma‑separated role names
     * @throws IllegalArgumentException if {@code strictMode} is true and
     *                                  any role is not in {@code validRoles}
     */
    public void setAllowedRoles(String roles) {
        List<String> list = stringToList(roles);
        if (strictMode && !areRolesValid(list)) {
            throw new IllegalArgumentException("Invalid roles in allowedRoles: " + list);
        }
        this.allowedRoles = list;
    }

    /**
     * Sets the disallowed roles from a comma‑separated string.
     *
     * @param roles comma‑separated role names
     * @throws IllegalArgumentException if {@code strictMode} is true and
     *                                  any role is not in {@code validRoles}
     */
    public void setDisallowedRoles(String roles) {
        List<String> list = stringToList(roles);
        if (strictMode && !areRolesValid(list)) {
            throw new IllegalArgumentException("Invalid roles in disallowedRoles: " + list);
        }
        this.disallowedRoles = list;
    }

    /**
     * Returns {@code true} only if every role in {@code roles} is present in
     * {@code validRoles}. {@code null} or an empty list is considered valid.
     *
     * @param roles list of roles to validate
     * @return {@code true} if all roles are valid, {@code false} otherwise
     */
    public boolean areRolesValid(List<String> roles) {
        if (roles == null || roles.isEmpty()) {
            return true;
        }
        for (String role : roles) {
            if (!validRoles.contains(role)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Converts a comma‑separated string into a list of trimmed strings.
     * Handles {@code null} or empty input by returning an empty list.
     *
     * @param val the input string
     * @return list of role names
     */
    private List<String> stringToList(String val) {
