import java.util.NoSuchElementException;

public class EnhancedQueue<E> {

    private static class Node<E> {
        E data;
        Node<E> next;

        Node(E data) {
            this.data = data;
            this.next = null;
        }
    }

    private Node<E> head;
    private Node<E> tail;
    private int size;

    /** Default constructor */
    public EnhancedQueue() {
        head = null;
        tail = null;
        size = 0;
    }

    /** Add an element to the end of the queue */
    public void enqueue(E newData) {
        Node<E> newNode = new Node<>(newData);
        if (isEmpty()) {
            head = tail = newNode;
        } else {
            tail.next = newNode;
            tail = newNode;
        }
        size++;
    }

    /** Remove and return the front element of the queue */
    public E dequeue() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        E data = head.data;
        head = head.next;
        if (head == null) { // queue became empty
            tail = null;
        }
        size--;
        return data;
    }

    /** Return the front element without removing it */
    public E peek() {
        if (isEmpty()) {
            throw new NoSuchElementException("Queue is empty");
        }
        return head.data;
    }

    /** Check if the queue is empty */
    public boolean isEmpty() {
        return size == 0;
    }

    /** Return the number of elements in the queue */
    public int size() {
        return size;
    }
}

