     * Finds the handler key for the first routing rule whose pattern matches
     * the given path. Returns null if no rule matches.
     *
     * @param path the request path to match against routing rules
     * @return the handler key of the first matching rule, or null if none match
     */
    public String findHandlerKey(String path) {
        if (path == null) {
            return null;
        }
        for (RoutingRule rule : routingRules) {
            if (rule.pattern.matcher(path).matches()) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    /* ----------------- Message processing ----------------- */

    /**
     * Processes a single message with deduplication and type-specific handling.
     *
     * @param messageId   unique identifier of the message
     * @param messageType exact type of the message
