        }

        // Apply handler to content
        return handler.apply(content);
    }

    /* ----------------- Internal helper classes ----------------- */

    /**
     * Represents a routing rule consisting of a compiled regex pattern
     * and the associated handler key.
     */
    private static class RoutingRule {
        final Pattern pattern;
        final String handlerKey;

        RoutingRule(Pattern pattern, String handlerKey) {
            this.pattern = pattern;
            this.handlerKey = handlerKey;
        }
    }

    /**
