import java.util.*;
import java.util.function.Function;
import java.util.regex.Pattern;

class MessageProcessor {
    /* ----------------- Core data structures ----------------- */
    private final Set<String> processedMessageIds;
    private final Map<String, Function<String, String>> handlers;
    private final List<RoutingRule> routingRules;
    private final Queue<String> messageQueue;   // FIFO queue for queued messages

    /* ----------------- Constructor ----------------- */
    public MessageProcessor() {
        this.processedMessageIds = new HashSet<>();
        this.handlers = new HashMap<>();
        this.routingRules = new ArrayList<>();
        this.messageQueue = new LinkedList<>();
    }

    /* ----------------- Handler registration ----------------- */
    public void addHandler(String messageType, Function<String, String> handler) {
        if (messageType == null || handler == null) {
            throw new IllegalArgumentException("Message type and handler must not be null");
        }
        handlers.put(messageType, handler);
    }

    /* ----------------- Routing rule registration ----------------- */
    public void addRoutingRule(String pattern, String handlerKey) {
        if (pattern == null || handlerKey == null) {
            throw new IllegalArgumentException("Pattern and handlerKey must not be null");
        }
        Pattern regex = Pattern.compile(convertPatternToRegex(pattern));
        routingRules.add(new RoutingRule(regex, handlerKey));
    }

    public String findHandlerKey(String path) {
        if (path == null) {
            return null;
        }
        for (RoutingRule rule : routingRules) {
            if (rule.pattern.matcher(path).matches()) {
                return rule.handlerKey;
            }
        }
        return null;
    }

    /* ----------------- Queue-based processing ----------------- */
    /**
     * Formats the message as 'messageId|messageType|content' and enqueues it.
     */
    public void enqueueMessage(String messageId, String messageType, String content) {
        if (messageId == null || messageType == null || content == null) {
            throw new IllegalArgumentException("Message components must not be null");
        }
        String formatted = messageId + "|" + messageType + "|" + content;
        messageQueue.offer(formatted);
    }

    /**
     * Processes all queued messages in FIFO order.
     *
     * @return a map of message IDs to their processing results
     */
    public Map<String, String> processQueue() {
        Map<String, String> results = new LinkedHashMap<>();
        while (!messageQueue.isEmpty()) {
            String formatted = messageQueue.poll();
            String[] parts = formatted.split("\\|", 3);
            if (parts.length != 3) {
                // Malformed entry; skip or record error
                continue;
            }
            String messageId = parts[0];
            String messageType = parts[1];
            String content = parts[2];
            String result = processMessage(messageId, messageType, content);
            results.put(messageId, result);
        }
        return results;
    }

    /* ----------------- Message processing ----------------- */
