import java.util.*;

public class BracketValidator {

    /**
     * Validates whether the brackets in the input string are balanced.
     * The result map contains:
     * - "balanced"   : true if all brackets are properly nested and matched, false otherwise
     * - "errorPosition" : index of the first error (closing mismatch or first unclosed opening),
     *                     -1 if the string is balanced
     * - "errorType"  : "mismatch" for a closing bracket that does not match,
     *                  "unclosed" for remaining opening brackets,
     *                  empty string if balanced
     *
     * @param input the string to validate
     * @return a map with the validation results
     */
    public static Map<String, Object> validateBrackets(String input) {
        Map<String, Object> result = new HashMap<>();

        if (input == null) {
            result.put("balanced", false);
            result.put("errorPosition", -1);
            result.put("errorType", "");
            return result;
        }

        Deque<BracketInfo> stack = new ArrayDeque<>();

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            switch (ch) {
                case '(':
                case '[':
                case '{':
                    stack.push(new BracketInfo(ch, i));
                    break;
                case ')':
                case ']':
                case '}':
                    if (stack.isEmpty() || !matches(stack.peek(), ch)) {
                        result.put("balanced", false);
                        result.put("errorPosition", i);
                        result.put("errorType", "mismatch");
                        return result;
                    }
                    stack.pop();
                    break;
                default:
                    // ignore non-bracket characters
                    break;
            }
        }

        if (!stack.isEmpty()) {
            BracketInfo firstUnclosed = stack.getLast(); // bottom of the stack
            result.put("balanced", false);
            result.put("errorPosition", firstUnclosed.index);
            result.put("errorType", "unclosed");
        } else {
            result.put("balanced", true);
            result.put("errorPosition", -1);
            result.put("errorType", "");
        }

        return result;
    }

    // Helper to check if an opening bracket matches a closing bracket
    private static boolean matches(BracketInfo info, char closing) {
        char open = info.bracket;
        return (open == '(' && closing == ')')
                || (open == '[' && closing == ']')
                || (open == '{' && closing == '}');
    }

    // Simple container for a bracket character and its position
    private static class BracketInfo {
        final char bracket;
        final int index;

        BracketInfo(char bracket, int index) {
            this.bracket = bracket;
            this.index = index;
        }
    }
}

