    /**
     * Checks if the given request URI and method match the provided permission.
     *
     * @param permission   the permission to validate against (may be null)
     * @param requestUri   the request URI to check
     * @param requestMethod the request HTTP method to check
     * @return true if both URI and method match (method comparison is case‑insensitive);
     *         false if permission is null or any mismatch occurs
     */
    public boolean hasPermission(PermissionInfo permission, String requestUri, String requestMethod) {
        if (permission == null) {
            return false;
        }
        return permission.getUri().equals(requestUri)
                && permission.getMethod().equalsIgnoreCase(requestMethod);
    }
}

