public class PermissionValidator {

    /**
     * Checks if the request URI and method match any permission in the provided list.
     * Supports the {@code {*} } wildcard in permission URIs, which matches exactly one
     * non‑empty alphanumeric segment.
     *
     * @param permissions   list of permissions to validate against (may be null or empty)
     * @param requestUri    the request URI to check
     * @param requestMethod the request HTTP method to check
     * @return true if any permission matches the URI and method (method comparison is case‑insensitive);
     *         false if the list is null, empty, or no match is found
     */
    public boolean hasPermission(List<PermissionInfo> permissions, String requestUri, String requestMethod) {
        if (permissions == null || permissions.isEmpty() || requestUri == null || requestMethod == null) {
            return false;
        }

        for (PermissionInfo permission : permissions) {
            if (permission == null) {
                continue;
            }

            String permUri = permission.getUri();
            String permMethod = permission.getMethod();

            if (permUri == null || permMethod == null) {
                continue;
            }

            if (!permMethod.equalsIgnoreCase(requestMethod)) {
                continue;
            }

            if (uriMatches(permUri, requestUri)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Determines whether a permission URI matches a request URI.
     * The permission URI may contain the {@code {*} } wildcard, which matches exactly one
     * non‑empty alphanumeric segment.
     *
     * @param permUri    the permission URI (may contain {@code {*} })
     * @param requestUri the request URI
     * @return true if the URIs match according to the rules; false otherwise
     */
    private boolean uriMatches(String permUri, String requestUri) {
        // Split by '/' keeping empty segments (e.g., leading/trailing slashes)
        String[] permSegments = permUri.split("/", -1);
        String[] reqSegments = requestUri.split("/", -1);

        if (permSegments.length != reqSegments.length) {
            return false;
        }

        for (int i = 0; i < permSegments.length; i++) {
            String pSeg = permSegments[i];
            String rSeg = reqSegments[i];

            if ("{*}".equals(pSeg)) {
                // Wildcard must match exactly one non‑empty alphanumeric segment
                if (rSeg.isEmpty() || !rSeg.matches("^[A-Za-z0-9]+$")) {
                    return false;
                }
            } else {
                if (!pSeg.equals(rSeg)) {
                    return false;
                }
            }
        }

        return true;
    }
}

