        if (!isShuttingDown.compareAndSet(false, true)) {
            return false; // another shutdown is already in progress
        }

        boolean allStopped = true;
        final long timeoutMs = timeoutUnit.toMillis(timeout);
        final long startTime = System.nanoTime(); // high‑resolution start time

        try {
            for (Map.Entry<String, Service> entry : services.entrySet()) {
                // Check timeout before attempting to stop the service
                long elapsedMs = (System.nanoTime() - startTime) / 1_000_000;
                if (elapsedMs > timeoutMs) {
                    System.out.println("Shutdown timeout exceeded for service: " + entry.getKey());
                    return false; // abort shutdown
                }

                try {
                    entry.getValue().stop();
                } catch (Exception e) {
                    allStopped = false;
                    // In a real implementation we might log the exception here.
                }
            }
        } finally {
            // Reset the flag regardless of success or failure
            isShuttingDown.set(false);
        }
        return allStopped;
    }

    public interface Service {
