import java.util.*;

public class ScenarioAnalyzer {

    public static class Node {
        String name;
        List<Node> children;

        public Node(String name) {
            this.name = name;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            children.add(child);
        }
    }

    public static Map<String, Object> analyzeScenario(Node root) {
        Map<String, Integer> nodeIndices = new HashMap<>();
        Queue<Node> queue = new LinkedList<>();
        int index = 0;

        if (root != null) {
            queue.add(root);
        }

        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.name, index++);
            for (Node child : current.children) {
                queue.add(child);
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        return result;
    }

    // Optional main method for demonstration
    public static void main(String[] args) {
        Node root = new Node("root");
        Node a = new Node("A");
        Node b = new Node("B");
        Node c = new Node("C");
        Node d = new Node("D");

        root.addChild(a);
        root.addChild(b);
        a.addChild(c);
        b.addChild(d);

        Map<String, Object> analysis = analyzeScenario(root);
        System.out.println(analysis);
    }
}
