import java.util.*;

public class ScenarioAnalyzer {

    /** Basic tree node with optional sync flag and server name. */
    public static class Node {
        String name;
        boolean isSync;
        String serverName;
        List<Node> children = new ArrayList<>();

        public Node(String name) {
            this(name, false, null);
        }

        public Node(String name, boolean isSync, String serverName) {
            this.name = name;
            this.isSync = isSync;
            this.serverName = serverName;
        }

        public void addChild(Node child) {
            children.add(child);
        }
    }

    /**
     * Analyzes the scenario tree.
     *
     * @param root the root node of the tree
     * @return a map containing:
     *   - "nodeIndices": Map<String,Integer> mapping node names to breadth‑first indices
     *   - "syncPairs":   Map<Integer,List<Integer>> mapping request node index to list of response node indices
     *   - "warnings":    List<String> of warning messages for sync requests without responses
     * @throws IllegalArgumentException if root is null
     */
    public static Map<String, Object> analyzeScenario(Node root) {
        if (root == null) {
            throw new IllegalArgumentException("rootNode cannot be null");
        }

        // Map node name -> index (for output)
        Map<String, Integer> nodeIndices = new HashMap<>();
        // Map node instance -> index (for internal lookup)
        Map<Node, Integer> nodeToIndex = new IdentityHashMap<>();
        // Map node instance -> parent server name
        Map<Node, String> parentServerName = new IdentityHashMap<>();

        Queue<Node> queue = new LinkedList<>();
        int index = 0;
        queue.add(root);
        parentServerName.put(root, null); // root has no parent

        // First pass: assign indices and record parent server names
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            nodeIndices.put(current.name, index);
            nodeToIndex.put(current, index);
            index++;
            for (Node child : current.children) {
                parentServerName.put(child, current.serverName);
                queue.add(child);
            }
        }

        // Second pass: detect synchronous request‑response pairs and warnings
        Map<Integer, List<Integer>> syncPairs = new HashMap<>();
        List<String> warnings = new ArrayList<>();

        for (Map.Entry<Node, Integer> entry : nodeToIndex.entrySet()) {
            Node node = entry.getKey();
            int reqIdx = entry.getValue();

            if (!node.isSync) continue;

            String parentSrv = parentServerName.get(node);
            if (parentSrv == null) continue; // no parent to match against

            boolean matched = false;
            for (Node child : node.children) {
                if (parentSrv.equals(child.serverName)) {
                    int respIdx = nodeToIndex.get(child);
                    syncPairs.computeIfAbsent(reqIdx, k -> new ArrayList<>()).add(respIdx);
                    matched = true;
                }
            }

            if (!matched) {
                String warning = String.format(
                        "Warning: There is no corresponding response to server \"%s\" from server \"%s\"",
                        parentSrv, node.serverName);
                warnings.add(warning);
            }
        }

        Map<String, Object> result = new HashMap<>();
        result.put("nodeIndices", nodeIndices);
        result.put("syncPairs", syncPairs);
        result.put("warnings", warnings);
        return result;
    }

    // Example usage
    public static void main(String[] args) {
        Node root = new Node("root", false, "srvRoot");

        Node reqA = new Node("ReqA", true, "srvA");
        Node respA1 = new Node("RespA1", false, "srvRoot"); // matches parent serverName of ReqA
        Node respA2 = new Node("RespA2", false, "srvRoot"); // another matching response

        Node reqB = new Node("ReqB", true, "srvB");
        Node respB = new Node("RespB", false, "srvX"); // does not match

        root.addChild(reqA);
        root.addChild(reqB);
        reqA.addChild(respA1);
        reqA.addChild(respA2);
        reqB.addChild(respB);

        Map<String, Object> analysis = analyzeScenario(root);
        System.out.println("Node indices: " + analysis.get("nodeIndices"));
        System.out.println("Sync pairs: " + analysis.get("syncPairs"));
        System.out.println("Warnings: " + analysis.get("warnings"));
    }
}
