import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;

public class ClassAnalyzer {

    /**
     * Analyzes the class specified by its fully qualified name.
     *
     * @param fullyQualifiedName the fully qualified name of the class to analyze
     * @return a report containing the class name, public constructors, and declared constructors
     */
    public static String analyzeClass(String fullyQualifiedName) {
        StringBuilder report = new StringBuilder();
        try {
            Class<?> clazz = Class.forName(fullyQualifiedName);
            report.append("Class: ").append(clazz.getName()).append('\n');

            // Public constructors
            report.append("\nPublic Constructors:\n");
            Constructor<?>[] publicConstructors = clazz.getConstructors();
            if (publicConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : publicConstructors) {
                    report.append("  ").append(formatConstructor(ctor)).append('\n');
                }
            }

            // Declared constructors
            report.append("\nDeclared Constructors:\n");
            Constructor<?>[] declaredConstructors = clazz.getDeclaredConstructors();
            if (declaredConstructors.length == 0) {
                report.append("  None\n");
            } else {
                for (Constructor<?> ctor : declaredConstructors) {
                    report.append("  ").append(formatConstructor(ctor)).append('\n');
                }
            }

        } catch (ClassNotFoundException e) {
            report.append("Error: Class not found - ").append(fullyQualifiedName).append('\n');
        } catch (Exception e) {
            report.append("Error: Unable to analyze class - ")
                  .append(fullyQualifiedName)
                  .append(" (")
                  .append(e.getMessage())
                  .append(")\n");
        }
        return report.toString();
    }

    /**
     * Formats a constructor into a readable string.
     *
     * @param ctor the constructor to format
     * @return a string representation of the constructor
     */
    private static String formatConstructor(Constructor<?> ctor) {
        StringBuilder sb = new StringBuilder();

        // Modifiers
        String modifiers = Modifier.toString(ctor.getModifiers());
        if (!modifiers.isEmpty()) {
            sb.append(modifiers).append(' ');
        }

        // Constructor name (simple class name)
        sb.append(ctor.getName().substring(ctor.getName().lastIndexOf('.') + 1));

        // Parameter types
        sb.append('(');
        Class<?>[] params = ctor.getParameterTypes();
        for (int i = 0; i < params.length; i++) {
            sb.append(params[i].getSimpleName());
            if (i < params.length - 1) {
                sb.append(", ");
            }
        }
        sb.append(')');

        return sb.toString();
    }
}

