                                   Map<String, Object> properties) {
        if (!nodes.containsKey(startNodeId) || !nodes.containsKey(endNodeId)) {
            throw new IllegalArgumentException(
                "Node not found: one or both specified nodes do not exist.");
        }
        long relId = nextRelId++;
        Relationship rel = new Relationship(relId, startNodeId, endNodeId, type, properties);
        relationships.put(relId, rel);
        return relId;
    }

