import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.ReentrantLock;

class ThreadSynchronizer {
    private final ReentrantLock lock;
    private final Condition condition;
    private boolean isSignalled;

    public ThreadSynchronizer() {
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();
        this.isSignalled = false;
    }

    /**
     * Waits for the specified number of seconds. The method does not
     * consider any external deadlines; it simply waits for the given
     * duration or until {@link #notifyAllThreads()} is called.
     *
     * @param waitSeconds the number of seconds to wait
     * @return {@code true} if the thread was signalled before the timeout,
     *         {@code false} otherwise (including interruption)
     */
    public boolean waitWithDeadline(int waitSeconds) {
        lock.lock();
        try {
            // If already signalled, consume the signal and return immediately
            if (isSignalled) {
                isSignalled = false;
                return true;
            }

            // Wait for the specified time or until signalled
            boolean signalled = condition.await(waitSeconds, TimeUnit.SECONDS);
            // If signalled, reset the flag
            if (signalled) {
                isSignalled = false;
            }
            return signalled;
        } catch (InterruptedException e) {
            // Preserve interrupt status and return false
            Thread.currentThread().interrupt();
            return false;
        } finally {
            lock.unlock();
        }
    }

    /**
     * Notifies all waiting threads. The notification is stored in
     * {@code isSignalled} so that a thread that wakes up due to a
     * timeout can still detect that a notification occurred.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
}

