            Date deadline = new Date(System.currentTimeMillis() + waitSeconds * 1000L);
            while (!isSignalled) {
                try {
                    // Await until the deadline; returns true if signaled, false if timed out
                    boolean signaled = condition.awaitUntil(deadline);
                    if (!signaled) {
                        // Timed out
                        break;
                    }
                    // If signaled, the loop will exit because isSignalled is true
                } catch (InterruptedException e) {
                    // Restore interrupt status and return false
                    Thread.currentThread().interrupt();
                    return false;
                }
            }
            return isSignalled;
        } finally {
            // Reset the flag for the next wait and release the lock
            isSignalled = false;
            lock.unlock();
        }
    }

    /**
     * Notifies all waiting threads. The {@code isSignalled} flag is set to
     * {@code true} before signaling to ensure that waiting threads can
     * detect the notification even if they wake up due to a spurious
     * interruption.
     */
    public void notifyAllThreads() {
        lock.lock();
        try {
            isSignalled = true;
            condition.signalAll();
        } finally {
            lock.unlock();
        }
    }
