 * Demo class to show how to use ThreadExecutor and SampleTask.
 */
class Main {
    public static void main(String[] args) {
        try {
            String result = ThreadExecutor.executeTaskWithTimeout(
                    new SampleTask("A", 1000), 2000);
            System.out.println(result);
        } catch (TimeoutException e) {
            System.err.println("The task timed out: " + e.getMessage());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

