import java.util.ArrayList;
import java.util.List;

public class TreePathAnalyzer {

    /**
     * Nested Node class representing a node in an N‑ary tree.
     */
    public static class Node {
        int data;
        List<Node> children;

        public Node(int data) {
            this.data = data;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            if (child != null) {
                children.add(child);
            }
        }
    }

    /**
     * Finds the longest path from the root to any leaf in the tree.
     *
     * @param root the root node of the tree
     * @return a list of nodes representing the longest path; empty if root is null
     */
    public List<Node> findLongestPath(Node root) {
        List<Node> bestPath = new ArrayList<>();
        if (root == null) {
            return bestPath;
        }
        List<Node> currentPath = new ArrayList<>();
        dfs(root, currentPath, bestPath);
        return bestPath;
    }

    /**
     * Depth‑first search helper that tracks the current path and updates the best path found.
     *
     * @param node        current node being visited
     * @param currentPath list of nodes from the root to the current node
     * @param bestPath    list of nodes representing the longest path found so far
     */
    private void dfs(Node node, List<Node> currentPath, List<Node> bestPath) {
        currentPath.add(node);

        // If this is a leaf node, check if the current path is longer than the best one.
        if (node.children.isEmpty()) {
            if (currentPath.size() > bestPath.size()) {
                bestPath.clear();
                bestPath.addAll(new ArrayList<>(currentPath));
            }
        } else {
            // Recurse into each child.
            for (Node child : node.children) {
                dfs(child, currentPath, bestPath);
            }
        }

        // Backtrack: remove the current node before returning to the caller.
        currentPath.remove(currentPath.size() - 1);
    }

    // Example usage (for illustration; remove or comment out in production)
    public static void main(String[] args) {
        Node root = new Node(1);
        Node childA = new Node(2);
        Node childB = new Node(3);
        Node childC = new Node(4);
        Node childD = new Node(5);

        root.addChild(childA);
        root.addChild(childB);
        childA.addChild(childC);
        childC.addChild(childD);

        TreePathAnalyzer analyzer = new TreePathAnalyzer();
        List<Node> longestPath = analyzer.findLongestPath(root);

        System.out.print("Longest path: ");
        for (Node n : longestPath) {
            System.out.print(n.data + " ");
        }
    }
}

