import java.util.List;
import java.util.Map;

public class TreePathAnalyzer {

    /**
     * Nested Node class representing a node in an N‑ary tree.
     */
    public static class Node {
        int data;
        List<Node> children;

        public Node(int data) {
            this.data = data;
            this.children = new ArrayList<>();
        }

        public void addChild(Node child) {
            if (child != null) {
                children.add(child);
            }
        }

        @Override
        public String toString() {
            return Integer.toString(data);
        }
    }

    /* ----------  Class level state for the longest path  ---------- */
    private int bestLength = 0;          // number of nodes in the longest path found so far
    private Node bestEndpoint1 = null;   // one end of the longest path
    private Node bestEndpoint2 = null;   // the other end of the longest path
    private final Map<Node, Node> parent = new HashMap<>();   // parent map for path reconstruction

    /**
     * Finds the longest path between any two nodes in an N‑ary tree.
     *
     * @param root the root node of the tree
     * @return a list of nodes representing the longest path; empty if root is null
     */
    public List<Node> findLongestPath(Node root) {
        bestLength = 0;
        bestEndpoint1 = null;
        bestEndpoint2 = null;
        parent.clear();

        if (root == null) {
            return new ArrayList<>();   // empty list for null input
        }

        parent.put(root, null);   // root has no parent
        dfs(root);

        // Reconstruct the path from bestEndpoint1 to bestEndpoint2
        return buildPath(bestEndpoint1, bestEndpoint2);
    }

    /**
     * Depth‑first search that computes the height of the subtree rooted at {@code node}
     * and updates the global best path (diameter) that may pass through {@code node}.
     *
     * @param node current node being processed
     * @return Result containing height and deepest node in this subtree
     */
    private Result dfs(Node node) {
        // Track the two deepest child heights and their deepest nodes
        int max1 = 0, max2 = 0;
        Node deepest1 = null, deepest2 = null;

        for (Node child : node.children) {
            parent.put(child, node);          // record parent for reconstruction
            Result childRes = dfs(child);

            if (childRes.height > max1) {
                max2 = max1;
                deepest2 = deepest1;
                max1 = childRes.height;
                deepest1 = childRes.deepest;
            } else if (childRes.height > max2) {
                max2 = childRes.height;
                deepest2 = childRes.deepest;
            }
        }

        // Height from this node to its deepest leaf
        int currentHeight = max1 + 1;
        Node deepestNode = (deepest1 != null) ? deepest1 : node;

        // Update best path if the downward path from this node is longer
        if (currentHeight > bestLength) {
            bestLength = currentHeight;
            bestEndpoint1 = node;
            bestEndpoint2 = deepestNode;
        }

        // Candidate path that goes through this node connecting two deepest subtrees
        if (max2 > 0) {   // at least two children
            int candidateLength = max1 + max2 + 1;
            if (candidateLength > bestLength) {
                bestLength = candidateLength;
                bestEndpoint1 = deepest1;
                bestEndpoint2 = deepest2;
            }
        }

        return new Result(currentHeight, deepestNode);
    }

    /**
     * Reconstructs the path between two nodes using the parent map.
     *
     * @param a one endpoint of the path
     * @param b the other endpoint
     * @return list of nodes from a to b (inclusive)
     */
    private List<Node> buildPath(Node a, Node b) {
        List<Node> path = new ArrayList<>();
        if (a == null || b == null) {
            return path;
        }

        // Build ancestor lists for both endpoints
        List<Node> ancestorsA = new ArrayList<>();
        for (Node cur = a; cur != null; cur = parent.get(cur)) {
            ancestorsA.add(cur);
        }

        List<Node> ancestorsB = new ArrayList<>();
        for (Node cur = b; cur != null; cur = parent.get(cur)) {
            ancestorsB.add(cur);
        }

        // Find lowest common ancestor (LCA)
        int i = ancestorsA.size() - 1;
        int j = ancestorsB.size() - 1;
        Node lca = null;
        while (i >= 0 && j >= 0 && ancestorsA.get(i) == ancestorsB.get(j)) {
            lca = ancestorsA.get(i);
            i--;
            j--;
        }

        // Path from a up to (but not including) LCA
        for (int k = 0; k <= i + 1; k++) {
            path.add(ancestorsA.get(k));
        }

        // Add LCA
        if (lca != null) {
            path.add(lca);
        }

        // Path from LCA down to b (reverse of ancestorsB up to LCA)
        for (int k = j + 1; k >= 0; k--) {
            path.add(ancestorsB.get(k));
        }

        return path;
    }

    /* ----------  Helper class for DFS results  ---------- */
    private static class Result {
        int height;      // number of nodes from this node to deepest leaf
        Node deepest;    // deepest node in this subtree

        Result(int height, Node deepest) {
            this.height = height;
            this.deepest = deepest;
        }
    }

    /* ----------  Example usage (can be removed in production)  ---------- */
    public static void main(String[] args) {
        Node root = new Node(1);
        Node a = new Node(2);
        Node b = new Node(3);
        Node c = new Node(4);
        Node d = new Node(5);
        Node e = new Node(6);
