         */
        public Celestial(Celestial other) {
            this.name = other.name;
            this.mass = other.mass;
            this.position = new Vector(other.position.x, other.position.y);
            this.velocity = new Vector(other.velocity.x, other.velocity.y);
            this.acceleration = new Vector(other.acceleration.x, other.acceleration.y);
        }

        /**
         * Update position and velocity using the equations
         * x = x0 + v*t and v = v0 + a*t.
         *
         * @param dt Time step.
         */
        public void update(double dt) {
            position = position.add(velocity.multiply(dt));
            velocity = velocity.add(acceleration.multiply(dt));
        }

        /**
         * Compute the gravitational force vector exerted by another body.
         *
         * @param other The other celestial body.
         * @return Force vector (newtons) acting on this body due to {@code other}.
         */
        public Vector calculateGravityForce(Celestial other) {
