import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.atomic.AtomicInteger;

class PollingQueue<T> {
    private final Queue<T> queue;
    private final AtomicInteger pollingCount;
    private final int maxPollingAttempts;

    public PollingQueue(int maxPollingAttempts) {
        this.queue = new LinkedList<>();
        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    public synchronized void enqueue(T element) {
        queue.add(element);
    }

    public synchronized T poll() {
        pollingCount.incrementAndGet(); // increment counter each poll
        return queue.poll();            // return element or null if empty
    }

    public int getPollingCount() {
        return pollingCount.get();
    }

    public int getMaxPollingAttempts() {
        return maxPollingAttempts;
    }
}

public class Main {
    public static void main(String[] args) {
        PollingQueue<String> pq = new PollingQueue<>(10);

        pq.enqueue("first");
        pq.enqueue("second");
        pq.enqueue("third");

        System.out.println("Polling count before polls: " + pq.getPollingCount());
        System.out.println("Polled: " + pq.poll());
        System.out.println("Polled: " + pq.poll());
        System.out.println("Polled: " + pq.poll());
        System.out.println("Polled: " + pq.poll()); // should be null
        System.out.println("Polling count after polls: " + pq.getPollingCount());
    }
}

