class RegexHelper {
    public Map<String, String> generateRegexPattern(String patternType, Map<String, String> parameters) {
        Map<String, String> result = new HashMap<>();

        if ("literal".equals(patternType)) {
            String text = parameters != null ? parameters.get("text") : null;
            result.put("pattern", text);
            result.put("type", "literal");
            result.put("description", "Literal text");
        } else if ("characterClass".equals(patternType)) {
            String cls = parameters != null ? parameters.get("class") : null;
            String pattern;
            String description;

            if ("digit".equalsIgnoreCase(cls)) {
                pattern = "\\\\d";
                description = "Digit character class";
            } else if ("lowercase".equalsIgnoreCase(cls)) {
                pattern = "[a-z]";
                description = "Lowercase letter character class";
            } else if ("uppercase".equalsIgnoreCase(cls)) {
                pattern = "[A-Z]";
                description = "Uppercase letter character class";
            } else {
                pattern = ".";
                description = "Any character (default)";
            }

            result.put("pattern", pattern);
            result.put("type", "characterClass");
            result.put("description", description);
        }

        return result;
    }
}

