        Map<String, String> result = new HashMap<>();

        if ("literal".equals(patternType)) {
            String text = parameters != null ? parameters.get("text") : null;
            if (text == null) text = "";
            String escaped = escapeRegexChars(text);
            result.put("pattern", escaped);
            result.put("type", "literal");
            result.put("description", "Literal text");
        } else if ("characterClass".equals(patternType)) {
            String cls = parameters != null ? parameters.get("class") : null;
            String pattern;
            String description;
            if ("digit".equalsIgnoreCase(cls)) {
