            result.put("description", description);
        } else if ("boundary".equals(patternType)) {
            if (parameters == null) {
                throw new IllegalArgumentException("Parameters map cannot be null for boundary pattern");
            }
            String type = parameters.get("type");
            if (type == null) {
                throw new IllegalArgumentException("Boundary type parameter is required");
            }
            String pattern;
            String description;
            switch (type.toLowerCase()) {
                case "start-line":
                    pattern = "^";
                    description = "Start of line anchor";
                    break;
                case "end-line":
                    pattern = "$";
                    description = "End of line anchor";
                    break;
                case "word":
                    pattern = "\\b";
                    description = "Word boundary";
                    break;
                case "non-word":
                    pattern = "\\B";
                    description = "Non-word boundary";
                    break;
                default:
                    throw new IllegalArgumentException("Unknown boundary type: " + type);
            }
            result.put("pattern", pattern);
            result.put("type", "boundary");
            result.put("description", description);
        } else if ("lookaround".equals(patternType)) {
            if (parameters == null) {
