import java.util.HashMap;
import java.util.Map;

class WebFragmentSimulator {
    private String currentUrl;
    private boolean isFragmentVisible;
    private Map<String, String> intentExtras;
    private boolean networkAvailable;

    public WebFragmentSimulator() {
        // Initialize fields with default values
        this.currentUrl = null;
        this.isFragmentVisible = false;
        this.intentExtras = new HashMap<>();
        this.networkAvailable = false;
    }

    /**
     * Loads web content for the given URL.
     *
     * @param url                The URL to load.
     * @param isFragmentVisible  Visibility flag for the fragment (ignored in this simplified version).
     * @param networkAvailable   Network availability flag (ignored in this simplified version).
     * @return A map containing the status of the load operation.
     *         If the URL is null or empty, the map will contain:
     *             "success" -> false
     *             "error"   -> "Invalid URL"
     *         Otherwise, it will contain:
     *             "success" -> true
     *             "url"     -> the provided URL
     */
    public Map<String, Object> loadWebContent(String url, boolean isFragmentVisible, boolean networkAvailable) {
        // Update internal state (though visibility and network flags are not used here)
        this.currentUrl = url;
        this.isFragmentVisible = isFragmentVisible;
        this.networkAvailable = networkAvailable;

        Map<String, Object> result = new HashMap<>();

        if (url == null || url.isEmpty()) {
            result.put("success", false);
            result.put("error", "Invalid URL");
            return result;
        }

        // URL is valid – proceed with success
        result.put("success", true);
        result.put("url", url);
        return result;
    }
}

