    private final Date expiration;   // expiration time
    private final int status;         // 1 = active, others = invalid
    private final String userId;      // associated user

    public Token(String tokenString, Date expiration, int status, String userId) {
        this.tokenString = tokenString;
        this.expiration  = expiration;
        this.status      = status;
        this.userId      = userId;
    }

    public String getTokenString() { return tokenString; }
    public Date getExpiration()    { return expiration; }
    public int getStatus()         { return status; }
    public String getUserId()      { return userId; }
}

/** AuthTokenValidator with in‑memory storage and enhanced validation. */
class AuthTokenValidator {
    // In‑memory stores
    private final Map<String, Token> tokenStore;
    private final Map<String, User>  userStore;

    /** Constructor initializes the stores with sample data. */
    public AuthTokenValidator() {
        tokenStore = new HashMap<>();
        userStore  = new HashMap<>();

        // Sample user
        User user1 = new User("user1", "Alice");
        userStore.put(user1.getUserId(), user1);

        // Sample token: valid, expires in 1 hour, status 1, associated with user1
        String tokenStr = "user192.168.1.10";
        Date expiresInOneHour = new Date(System.currentTimeMillis() + 60 * 60 * 1000);
        Token token1 = new Token(tokenStr, expiresInOneHour, 1, user1.getUserId());
        tokenStore.put(tokenStr, token1);
    }

    /**
     * Validates the given token against several criteria.
     *
     * @param token    the token string
     * @param clientIp the IP address of the client
     * @return a map containing validation results; on success includes the User object
     */
    public Map<String, Object> validateToken(String token, String clientIp) {
        Map<String, Object> result = new HashMap<>();

        // 1. Null or empty token
        if (token == null || token.isEmpty()) {
            result.put("valid", false);
            result.put("message", "Token is empty");
            return result;
        }

        // 2. Token must exist in the in‑memory store
        Token storedToken = tokenStore.get(token);
        if (storedToken == null) {
            result.put("valid", false);
            result.put("message", "Token not found");
            return result;
        }

        // 3. Check expiration
        if (storedToken.getExpiration().before(new Date())) {
            result.put("valid", false);
            result.put("message", "Token expired");
            return result;
        }

        // 4. Check status
        if (storedToken.getStatus() != 1) {
            result.put("valid", false);
            result.put("message", "Token invalid");
            return result;
        }

        // 5. Verify user exists
        User user = userStore.get(storedToken.getUserId());
        if (user == null) {
            result.put("valid", false);
            result.put("message", "User not found");
            return result;
        }

        // 6. Extract IP address that follows the 'user' substring
        int userIndex = token.indexOf("user");
        if (userIndex == -1) {
            result.put("valid", false);
            result.put("message", "Token format invalid");
            return result;
        }
        String ipInToken = token.substring(userIndex + "user".length());

        // 7. Compare the extracted IP with the provided client IP
        if (!ipInToken.equals(clientIp)) {
            result.put("valid", false);
            result.put("message", "IP address mismatch");
            return result;
        }

        // 8. All checks passed
        result.put("valid", true);
        result.put("message", "Validation successful");
        result.put("user", user);
        return result;
    }
}

