import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class AsyncOperationManager {

    // A shared scheduler for timeout tasks
    private static final ScheduledExecutorService scheduler =
            Executors.newScheduledThreadPool(1);

    public <T> CompletableFuture<T> executeWithTimeoutAndRetry(
            Supplier<T> taskSupplier,
            long timeout,
            TimeUnit timeUnit,
            T fallbackValue,
            int maxRetries) {

        // The original task executed asynchronously
        CompletableFuture<T> taskFuture = CompletableFuture.supplyAsync(taskSupplier);

        // A future that will complete with the fallback value after the timeout
        CompletableFuture<T> timeoutFuture = new CompletableFuture<>();

        // Schedule the fallback completion
        ScheduledFuture<?> scheduled = scheduler.schedule(
                () -> timeoutFuture.complete(fallbackValue),
                timeout,
                timeUnit);

        // If the task completes first, cancel the scheduled fallback
        taskFuture.whenComplete((res, ex) -> scheduled.cancel(false));

        // Return a future that completes with whichever completes first
        return CompletableFuture.anyOf(taskFuture, timeoutFuture)
                .thenApply(result -> (T) result);
    }
}

