class TicTacToeGame {
    private final char[][] board;
    private char currentPlayer;
    private boolean gameOver;

    public TicTacToeGame(int size) {
        this.board = new char[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                board[i][j] = '-';
            }
        }
        this.currentPlayer = 'X';
        this.gameOver = false; // initially the game never ends
    }

    /**
     * Attempts to place the current player's mark at the specified position.
     *
     * @param row the row index (0‑based)
     * @param col the column index (0‑based)
     * @return true if the move was successful; false if the move is out of bounds,
     *         the cell is already occupied, or the game is over.
     */
    public boolean makeMove(int row, int col) {
        // Check if the game has already ended
        if (gameOver) {
            return false;
        }

        // Validate bounds
        if (row < 0 || row >= board.length || col < 0 || col >= board[0].length) {
            return false;
        }

        // Check if the cell is empty
        if (board[row][col] != '-') {
            return false;
        }

        // Place the mark and switch player
        board[row][col] = currentPlayer;
        currentPlayer = (currentPlayer == 'X') ? 'O' : 'X';
        return true;
    }

    /**
     * Returns a snapshot of the current board state as a list of strings.
     * Each string represents a row of the board.
     */
    public List<String> getBoardState() {
        List<String> state = new ArrayList<>();
        for (char[] row : board) {
            state.add(new String(row));
        }
        return state;
    }

    /**
     * Returns the player whose turn it is next.
     */
    public char getCurrentPlayer() {
        return currentPlayer;
    }

    /**
     * Marks the game as over. After this call, no further moves will be accepted.
     */
    public void setGameOver(boolean over) {
        this.gameOver = over;
    }
}

