import java.util.Map;
import java.util.LinkedHashMap;
import java.util.Collection;
import java.util.Map.Entry;
import java.lang.reflect.Array;

class DataStructureAnalyzer {
    public static Map<String, Object> analyzeDataStructure(Object data) {
        if (data == null) {
            throw new IllegalArgumentException("Input data cannot be null");
        }

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("containsBinary", false);
        result.put("maxDepth", 0);
        result.put("totalElements", 0);
        Map<String, Integer> typeCounts = new LinkedHashMap<>();
        result.put("typeCounts", typeCounts);

        analyzeRecursive(data, result, typeCounts, 1);

        return result;
    }

    private static void analyzeRecursive(Object data, Map<String, Object> result,
                                         Map<String, Integer> typeCounts, int currentDepth) {
        // Update maxDepth
        int currentMax = (int) result.get("maxDepth");
        if (currentDepth > currentMax) {
            result.put("maxDepth", currentDepth);
        }

        // Update containsBinary
        if (data instanceof byte[]) {
            result.put("containsBinary", true);
        }

        // Update totalElements
        int total = (int) result.get("totalElements");
        total += 1;
        result.put("totalElements", total);

        // Update typeCounts
        String typeName = data.getClass().getSimpleName();
        typeCounts.put(typeName, typeCounts.getOrDefault(typeName, 0) + 1);

        // Recurse into containers
        if (data.getClass().isArray()) {
            int len = Array.getLength(data);
            for (int i = 0; i < len; i++) {
                Object elem = Array.get(data, i);
                if (elem != null) {
                    analyzeRecursive(elem, result, typeCounts, currentDepth + 1);
                }
            }
        } else if (data instanceof Collection) {
            for (Object elem : (Collection<?>) data) {
                if (elem != null) {
                    analyzeRecursive(elem, result, typeCounts, currentDepth + 1);
                }
            }
        } else if (data instanceof Map) {
            Map<?, ?> map = (Map<?, ?>) data;
            for (Entry<?, ?> entry : map.entrySet()) {
                Object key = entry.getKey();
                Object value = entry.getValue();
                if (key != null) {
                    analyzeRecursive(key, result, typeCounts, currentDepth + 1);
                }
                if (value != null) {
                    analyzeRecursive(value, result, typeCounts, currentDepth + 1);
                }
            }
        }
        // For other objects, nothing more to recurse
    }
}

