public class GameOfLifePatterns {

    /**
     * Creates a new square boolean grid of the specified size.
     *
     * @param size the dimension of the grid (size x size)
     * @return a boolean[][] array initialized to false
     * @throws IllegalArgumentException if size is negative
     */
    public static boolean[][] createGrid(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("Size must be non-negative");
        }
        return new boolean[size][size];
    }

    /**
     * Counts the number of live cells (true values) in the given grid.
     *
     * @param grid the boolean[][] grid to inspect
     * @return the count of true values; returns 0 if grid is null or empty
     */
    public static int countLiveCells(boolean[][] grid) {
        if (grid == null || grid.length == 0) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < grid.length; i++) {
            boolean[] row = grid[i];
            if (row == null) {
                continue; // skip null rows
            }
            for (int j = 0; j < row.length; j++) {
                if (row[j]) {
                    count++;
                }
            }
        }
        return count;
    }
}

