            throw new IllegalArgumentException("Offsets must be non-negative");
        }

        // Only glider pattern is implemented
        if (!"glider".equalsIgnoreCase(patternName)) {
            return; // No action for unsupported patterns
        }

        // Relative coordinates of the glider pattern
        int[][] gliderCoords = {
                {0, 0},
                {1, 0},
                {2, 0},
                {2, 1},
                {1, 2}
        };

        int rows = grid.length;
        int cols = grid[0].length;

        for (int[] coord : gliderCoords) {
            int x = xOffset + coord[0];
            int y = yOffset + coord[1];
            if (x >= 0 && x < rows && y >= 0 && y < cols) {
                grid[x][y] = true;
            }
