public class UserAuthenticator {
    // Hardcoded user database: phone number -> password
    private static final Map<String, String> USER_DB = new HashMap<>();

    static {
        USER_DB.put("1234567890", "password123");
        USER_DB.put("0987654321", "secure456");
    }

    /**
     * Authenticates a user based on phone number and password.
     *
     * @param phoneNumber the user's phone number
     * @param password    the user's password
     * @return a success or failure message
     */
    public String authenticate(String phoneNumber, String password) {
        if (!USER_DB.containsKey(phoneNumber)) {
            return "Authentication failed: phone number not found.";
        }
        String storedPassword = USER_DB.get(phoneNumber);
        if (storedPassword.equals(password)) {
            return "Authentication successful for phone number: " + phoneNumber;
        } else {
            return "Authentication failed: incorrect password.";
        }
    }

    // Example usage
    public static void main(String[] args) {
        UserAuthenticator auth = new UserAuthenticator();

        System.out.println(auth.authenticate("1234567890", "password123")); // success
        System.out.println(auth.authenticate("1234567890", "wrongpass"));   // failure
        System.out.println(auth.authenticate("1111111111", "any"));         // failure
    }
}

