        if (phoneNumber == null || phoneNumber.isEmpty()) {
            throw new IllegalArgumentException("Phone number cannot be null or empty.");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Password cannot be null or empty.");
        }
        if (phoneNumber.length() != 10) {
            throw new IllegalArgumentException("Phone number must be exactly 10 digits long.");
        }

        // Authentication logic
        if (!USER_DB.containsKey(phoneNumber)) {
            return "Authentication failed: phone number not found.";
        }
        String storedPassword = USER_DB.get(phoneNumber);
        if (storedPassword.equals(password)) {
            return "Authentication successful for phone number: " + phoneNumber;
        } else {
            return "Authentication failed: incorrect password.";
        }
    }

    // Example usage
    public static void main(String[] args) {
        UserAuthenticator auth = new UserAuthenticator();

        // Successful authentication
        System.out.println(auth.authenticate("1234567890", "password123"));

        // Incorrect password
        System.out.println(auth.authenticate("1234567890", "wrongpass"));

        // Phone number not in database
