    public static class AuthenticationResult {
        private final int statusCode;
        private final String message;
        private final String user; // phone number of authenticated user, null if not authenticated

        public AuthenticationResult(int statusCode, String message, String user) {
            this.statusCode = statusCode;
            this.message = message;
            this.user = user;
        }

        public int getStatusCode() {
            return statusCode;
        }

        public String getMessage() {
            return message;
        }

        public String getUser() {
            return user;
        }

        @Override
        public String toString() {
            return "AuthenticationResult{" +
                    "statusCode=" + statusCode +
                    ", message='" + message + '\'' +
                    ", user='" + user + '\'' +
                    '}';
        }
    }

    // Example usage
    public static void main(String[] args) {
        UserAuthenticator auth = new UserAuthenticator();

        // Successful first factor
        AuthenticationResult first = auth.authenticate("1234567890", "password123");
        System.out.println(first); // Should show status 250

        // Attempt to verify with wrong code
        AuthenticationResult secondFail = auth.verifyCode("1234567890", "000000");
        System.out.println(secondFail); // Should show status 401

        // Verify with correct code
        AuthenticationResult secondSuccess = auth.verifyCode("1234567890", "123456");
        System.out.println(secondSuccess); // Should show status 200

        // Attempt to verify again (code should have been cleared)
        AuthenticationResult secondAgain = auth.verifyCode("1234567890", "123456");
        System.out.println(secondAgain); // Should show status 401

        // Input validation examples (uncomment to test)
        // auth.authenticate(null, "pass");          // throws exception
        // auth.verifyCode("1234567890", null);      // throws exception
    }
}

