        if (identifier instanceof Long) {
            credentialsMatch = MOCK_ID.equals(identifier) && MOCK_PASS.equals(password);
        } else { // identifier is String
            String idStr = (String) identifier;
            boolean isEmail = idStr.contains("@");
            if (isEmail) {
                credentialsMatch = MOCK_EMAIL.equals(idStr) && MOCK_PASS.equals(password);
            } else {
                credentialsMatch = MOCK_USER.equals(idStr) && MOCK_PASS.equals(password);
            }
        }

        if (credentialsMatch) {
            User user = new User(MOCK_USER, MOCK_EMAIL);
            result.put("authenticated", true);
            result.put("user", user);
        } else {
            result.put("authenticated", false);
            result.put("error", "Invalid credentials");
        }

        return result;
    }

    // Demo usage
    public static void main(String[] args) {
        // Successful authentication with account name
        Map<String, Object> successAccount = authenticateUser("testuser", "password");
        System.out.println(successAccount);

        // Successful authentication with email
        Map<String, Object> successEmail = authenticateUser("test@example.com", "password");
        System.out.println(successEmail);

        // Successful authentication with user ID
        Map<String, Object> successId = authenticateUser(1L, "password");
