        Map<String, Object> failure = authenticateUser("testuser", "wrongpass");
        System.out.println(failure);

        // Invalid identifier type (will throw IllegalArgumentException)
        try {
            authenticateUser(2.5, "password");
        } catch (IllegalArgumentException e) {
            System.out.println("Exception: " + e.getMessage());
        }
    }
}

