import java.util.*;

public class PlayerManagementSystem {

    /** Stores a player's ID and score. */
    public static class PlayerInfo {
        private final String id;
        private int score;

        public PlayerInfo(String id, int score) {
            this.id = id;
            this.score = score;
        }

        public String getId() {
            return id;
        }

        public int getScore() {
            return score;
        }

        public void setScore(int score) {
            this.score = score;
        }

        @Override
        public String toString() {
            return "PlayerInfo{id='" + id + "', score=" + score + "}";
        }
    }

    /** Manages player registrations using a map. */
    public static class PlayerManager {
        private final Map<String, PlayerInfo> players = new HashMap<>();

        /**
         * Registers a new player with the given ID and score.
         * @param id    unique player identifier
         * @param score initial score
         * @return true if registration succeeded, false if the ID already exists
         */
        public boolean registerPlayer(String id, int score) {
            if (players.containsKey(id)) {
                return false; // duplicate ID
            }
            players.put(id, new PlayerInfo(id, score));
            return true;
        }

        public PlayerInfo getPlayer(String id) {
            return players.get(id);
        }

        public Collection<PlayerInfo> getAllPlayers() {
            return players.values();
        }
    }

    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        System.out.println("Registering player1: " + manager.registerPlayer("player1", 100)); // true
        System.out.println("Registering player2: " + manager.registerPlayer("player2", 150)); // true
        System.out.println("Registering player1 again: " + manager.registerPlayer("player1", 200)); // false

        System.out.println("\nAll registered players:");
        for (PlayerInfo p : manager.getAllPlayers()) {
            System.out.println(p);
        }
    }
}

