import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * A thread‑safe player management system that supports registering,
 * removing, and updating player scores.
 */
public class PlayerManagementSystem {

    /** Stores a player's ID, score and active status. */
    public static class PlayerInfo {
        private final String id;
        private int score;
        private volatile boolean active;

        public PlayerInfo(String id, int score) {
            this.id = id;
            this.score = score;
            this.active = true;
        }

        public String getId() {
            return id;
        }

        public int getScore() {
            return score;
        }

        public boolean isActive() {
            return active;
        }

        /** Adjusts the score by the given delta (can be negative). */
        public synchronized void adjustScore(int delta) {
            this.score += delta;
        }

        /** Marks the player as inactive. */
        public void deactivate() {
            this.active = false;
        }

        @Override
        public String toString() {
            return "PlayerInfo{id='" + id + "', score=" + score + ", active=" + active + "}";
        }
    }

    /** Manages player registrations and operations. */
    public static class PlayerManager {
        // Thread‑safe map of all players.
        private final ConcurrentHashMap<String, PlayerInfo> players = new ConcurrentHashMap<>();

        // Queue of active players (order of registration).
        private final ConcurrentLinkedQueue<PlayerInfo> activeQueue = new ConcurrentLinkedQueue<>();

        /**
         * Registers a new player with the given ID and score.
         *
         * @param id    unique player identifier
         * @param score initial score
         * @return true if registration succeeded, false if the ID already exists
         */
        public synchronized boolean registerPlayer(String id, int score) {
            if (players.containsKey(id)) {
                return false; // duplicate ID
            }
            PlayerInfo p = new PlayerInfo(id, score);
            players.put(id, p);
            activeQueue.add(p);
            return true;
        }

        /**
         * Removes a player from the system.
         * The player is marked as inactive and removed from the active queue.
         *
         * @param id player identifier
         * @return true if the player existed and was removed, false otherwise
         */
        public synchronized boolean removePlayer(String id) {
            PlayerInfo p = players.get(id);
            if (p == null) {
                return false; // no such player
            }
            p.deactivate();
            // Remove from queue (O(n) but acceptable for small queues).
            activeQueue.remove(p);
            return true;
        }

        /**
         * Updates the score of an existing player by the given delta.
         *
         * @param id    player identifier
         * @param delta amount to add (can be negative)
         * @return true if the player existed and the score was updated, false otherwise
         */
        public boolean updateScore(String id, int delta) {
            PlayerInfo p = players.get(id);
            if (p == null) {
                return false; // no such player
            }
            // Synchronize on the player object to avoid race conditions.
            synchronized (p) {
                p.adjustScore(delta);
            }
            return true;
        }

        public PlayerInfo getPlayer(String id) {
            return players.get(id);
        }

        /**
         * Returns a snapshot of all registered players.
         */
        public Collection<PlayerInfo> getAllPlayers() {
            return new ArrayList<>(players.values());
        }

        /**
         * Returns a snapshot of the active player queue.
         */
        public Collection<PlayerInfo> getActiveQueue() {
            return new ArrayList<>(activeQueue);
        }
    }

    public static void main(String[] args) {
        PlayerManager manager = new PlayerManager();

        System.out.println("Registering player1: " + manager.registerPlayer("player1", 100)); // true
        System.out.println("Registering player2: " + manager.registerPlayer("player2", 150)); // true
        System.out.println("Registering player1 again: " + manager.registerPlayer("player1", 200)); // false

        System.out.println("\nUpdating scores:");
        System.out.println("player1 +50: " + manager.updateScore("player1", 50)); // true
        System.out.println("player2 -20: " + manager.updateScore("player2", -20)); // true
        System.out.println("nonexistent +10: " + manager.updateScore("player3", 10)); // false

        System.out.println("\nRemoving player1:");
        System.out.println("remove player1: " + manager.removePlayer("player1")); // true
        System.out.println("remove player1 again: " + manager.removePlayer("player1")); // false

        System.out.println("\nAll registered players:");
        for (PlayerInfo p : manager.getAllPlayers()) {
            System.out.println(p);
        }

        System.out.println("\nActive player queue:");
        for (PlayerInfo p : manager.getActiveQueue()) {
            System.out.println(p);
        }
    }
}

