            if (p == null) {
                return false; // no such player
            }
            // Synchronize on the player object to avoid race conditions.
            synchronized (p) {
                p.adjustScore(delta);
            }
            return true;
        }

        /**
         * Returns the next active player in round‑robin order.
         * The retrieved player is moved to the back of the queue.
         *
         * @return the next PlayerInfo, or null if no active players exist
