import java.util.*;

/**
 * Represents a category with an id, name and parent id.
 */
class Category {
    private long id;
    private String name;
    private long parentId;

    public Category(long id, String name, long parentId) {
        this.id = id;
        this.name = name;
        this.parentId = parentId;
    }

    public long getId() { return id; }
    public String getName() { return name; }
    public long getParentId() { return parentId; }

    public void setId(long id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setParentId(long parentId) { this.parentId = parentId; }
}

/**
 * Node used in the category tree. Each node has an id, name and a list of child nodes.
 */
class CategoryNode {
    private long id;
    private String name;
    private List<CategoryNode> children = new ArrayList<>();

    public CategoryNode(long id, String name) {
        this.id = id;
        this.name = name;
    }

    public long getId() { return id; }
    public String getName() { return name; }
    public List<CategoryNode> getChildren() { return children; }

    public void setId(long id) { this.id = id; }
    public void setName(String name) { this.name = name; }
    public void setChildren(List<CategoryNode> children) { this.children = children; }
}

/**
 * Result wrapper that contains the list of root category nodes.
 */
class CatResult {
    private List<CategoryNode> data = new ArrayList<>();

    public List<CategoryNode> getData() { return data; }
    public void setData(List<CategoryNode> data) { this.data = data; }
}

/**
 * Service that manages categories and builds the category tree.
 */
class ItemCatService {
    // Stores all categories by id
    private Map<Long, Category> categories = new HashMap<>();
    // Maps parentId to list of child categories
    private Map<Long, List<Category>> childrenMap = new HashMap<>();

    /**
     * Adds a category to the service.
     */
    public void addCategory(Category cat) {
        categories.put(cat.getId(), cat);
        childrenMap.computeIfAbsent(cat.getParentId(), k -> new ArrayList<>()).add(cat);
    }

    /**
     * Builds and returns the category tree as a CatResult.
     * If no categories exist, returns an empty CatResult.
     */
    public CatResult getItemCatList() {
        CatResult result = new CatResult();
        List<Category> roots = childrenMap.get(0L);
        if (roots == null || roots.isEmpty()) {
            return result; // empty result
        }
        for (Category root : roots) {
            result.getData().add(buildNode(root));
        }
        return result;
    }

    /**
     * Recursively builds a CategoryNode from a Category.
     */
    private CategoryNode buildNode(Category cat) {
        CategoryNode node = new CategoryNode(cat.getId(), cat.getName());
        List<Category> children = childrenMap.get(cat.getId());
        if (children != null) {
            for (Category child : children) {
                node.getChildren().add(buildNode(child));
            }
        }
        return node;
    }
}

