public class FactorySimulation {
    public static void main(String[] args) {
        // Total items initially in the input stock
        int totalItems = 10;
        // Fixed number of items the workshop will process
        int itemsToProcess = 6;

        // Initialize the input stock as a queue
        java.util.Queue<Integer> inputStock = new java.util.LinkedList<>();
        for (int i = 1; i <= totalItems; i++) {
            inputStock.add(i);
        }

        // Output stock to hold processed items
        java.util.List<Integer> outputStock = new java.util.ArrayList<>();

        // Process items
        int processedCount = 0;
        while (processedCount < itemsToProcess && !inputStock.isEmpty()) {
            int item = inputStock.poll(); // take from input
            // Simulate processing (here we just move it to output)
            outputStock.add(item);
            processedCount++;
        }

        // Remaining items in the input stock
        int remainingInput = inputStock.size();

        // Display results
        System.out.println("Processed items: " + processedCount);
        System.out.println("Remaining items in input stock: " + remainingInput);
        System.out.println("Output stock contents: " + outputStock);
    }
}

