import java.util.*;

public class Main {

    // Thread‑safe stock with synchronized operations
    static class Stock<T> {
        private final Queue<T> queue = new LinkedList<>();

        public synchronized void add(T item) {
            queue.offer(item);
            notifyAll();
        }

        public synchronized T poll() throws InterruptedException {
            while (queue.isEmpty()) {
                wait();
            }
            return queue.poll();
        }

        public synchronized T pollNonBlocking() {
            return queue.poll();
        }

        public synchronized int size() {
            return queue.size();
        }

        public synchronized boolean isEmpty() {
            return queue.isEmpty();
        }
    }

    // Functional interface for workshop processing
    interface WorkshopProcessor {
        int process(int item);
    }

    // Workshop thread that processes items from its input stock to its output stock
    static class WorkshopThread extends Thread {
        private final Stock<Integer> input;
        private final Stock<Integer> output;
        private final WorkshopProcessor processor;
        private final int sentinel;

        public WorkshopThread(Stock<Integer> input, Stock<Integer> output,
                              WorkshopProcessor processor, int sentinel) {
            this.input = input;
            this.output = output;
            this.processor = processor;
            this.sentinel = sentinel;
        }

        @Override
        public void run() {
            try {
                while (true) {
                    int item = input.poll();
                    if (item == sentinel) {
                        output.add(sentinel);
                        break;
                    }
                    int processed = processor.process(item);
                    output.add(processed);
                }
            } catch (InterruptedException e) {
                // Thread interrupted – exit gracefully
            }
        }
    }

    // Return workshop processors for a given factory version
    static List<WorkshopProcessor> getProcessorsForVersion(int version) {
        List<WorkshopProcessor> list = new ArrayList<>();
        switch (version) {
            case 1:
                list.add(item -> item * 2);
                break;
            case 2:
                list.add(item -> item + 1);
                list.add(item -> item * 3);
                break;
            case 3:
                list.add(item -> item - 1);
                list.add(item -> item / 2);
                list.add(item -> item + 5);
                break;
            case 4:
                list.add(item -> item * item);
                list.add(item -> item % 10);
                list.add(item -> item * 7);
                list.add(item -> item - 3);
                break;
            default:
                list.add(item -> item); // identity for unknown version
                break;
        }
        return list;
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);

        int version = sc.nextInt();          // factory version (1‑4)
        int itemsToProcess = sc.nextInt();   // number of items to process
        int stockSize = sc.nextInt();        // total items in the initial stock

        // Initial input stock
        Stock<Integer> inputStock = new Stock<>();
        for (int i = 0; i < stockSize; i++) {
            inputStock.add(sc.nextInt());
        }

        final int SENTINEL = Integer.MIN_VALUE; // special value to signal end

        // Create pipeline stocks
        List<WorkshopProcessor> processors = getProcessorsForVersion(version);
        int numWorkshops = processors.size();
        List<Stock<Integer>> pipelineStocks = new ArrayList<>();
        for (int i = 0; i <= numWorkshops; i++) {
            pipelineStocks.add(new Stock<>());
        }

        // Start workshop threads
        List<WorkshopThread> threads = new ArrayList<>();
        for (int i = 0; i < numWorkshops; i++) {
            WorkshopThread wt = new WorkshopThread(
                    pipelineStocks.get(i),
                    pipelineStocks.get(i + 1),
                    processors.get(i),
                    SENTINEL);
            wt.start();
            threads.add(wt);
        }

        // Feed items to the first workshop
        for (int i = 0; i < itemsToProcess && !inputStock.isEmpty(); i++) {
            Integer item = inputStock.pollNonBlocking();
            if (item != null) {
                pipelineStocks.get(0).add(item);
            }
        }

        // Signal end of input to the first workshop
        pipelineStocks.get(0).add(SENTINEL);

        // Collect processed items from the last workshop
        int processedCount = 0;
        while (true) {
            int item = pipelineStocks.get(numWorkshops).poll();
            if (item == SENTINEL) {
                break;
            }
            processedCount++;
        }

        // Remaining items in the original input stock
        int remainingInput = inputStock.size();

        // Output the results
        System.out.println(processedCount + " " + remainingInput);

        // Wait for all workshop threads to finish
        for (WorkshopThread wt : threads) {
            wt.join();
        }
    }
}

