public class FileHandler {

    /**
     * Handles file operations based on the provided operation type.
     *
     * @param operationType the type of operation to perform (e.g., "upload", "download", "zip")
     * @param files         the list of files to process (used for upload and zip)
     * @param targetDir     the directory where files should be uploaded or from which they should be downloaded
     * @param fileName      the name of the file to download (used for download)
     * @return a String message for upload, a byte[] containing the file contents for download,
     *         or a byte[] containing the zip archive for zip
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) {
        if ("upload".equalsIgnoreCase(operationType)) {
            if (files == null || targetDir == null) {
                return "Invalid parameters for upload operation.";
            }

            try {
                // Create the target directory if it does not exist
                Files.createDirectories(targetDir);

                int uploadedCount = 0;
                for (Path file : files) {
                    if (Files.exists(file) && Files.isRegularFile(file)) {
                        Path targetFile = targetDir.resolve(file.getFileName());
                        Files.copy(file, targetFile, StandardCopyOption.REPLACE_EXISTING);
                        uploadedCount++;
                    }
                }

                return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + ".";
            } catch (IOException e) {
                return "Error during upload: " + e.getMessage();
            }

        } else if ("download".equalsIgnoreCase(operationType)) {
            if (targetDir == null || fileName == null) {
                return "Invalid parameters for download operation.";
            }

            Path filePath = targetDir.resolve(fileName);
            try {
                return Files.readAllBytes(filePath);
            } catch (IOException e) {
                return ("Error during download: " + e.getMessage()).getBytes();
            }

        } else if ("zip".equalsIgnoreCase(operationType)) {
            if (files == null) {
                return "Invalid parameters for zip operation.";
            }

            try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
                 ZipOutputStream zos = new ZipOutputStream(baos)) {

                for (Path file : files) {
                    if (Files.exists(file) && Files.isRegularFile(file)) {
                        ZipEntry entry = new ZipEntry(file.getFileName().toString());
                        zos.putNextEntry(entry);
                        Files.copy(file, zos);
                        zos.closeEntry();
                    }
                }
                zos.finish();
                return baos.toByteArray();

            } catch (IOException e) {
                return ("Error during zip creation: " + e.getMessage()).getBytes();
            }

        } else {
            // Unsupported operation
            return null;
        }
    }
}

