import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.file.*;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * Utility class for handling file operations such as upload, download, and zip.
 */
public class FileHandler {

    /**
     * Handles file operations based on the provided operation type.
     *
     * @param operationType the type of operation to perform ("upload", "download", or "zip")
     * @param files         the list of files to process (used for upload and zip)
     * @param targetDir     the directory where files should be uploaded or from which they should be downloaded
     * @param fileName      the name of the file to download (used for download)
     * @return a String message for upload, a byte[] for download, or a byte[] for zip
     * @throws IOException              if an I/O error occurs during the operation
     * @throws IllegalArgumentException if the operation type is unsupported or required parameters are missing
     */
    public static Object handleFileOperation(String operationType,
                                             List<Path> files,
                                             Path targetDir,
                                             String fileName) throws IOException {
        if (operationType == null) {
            throw new IllegalArgumentException("Operation type cannot be null.");
        }

        switch (operationType.toLowerCase()) {
            case "upload":
                return uploadFiles(files, targetDir);
            case "download":
                return downloadFile(targetDir, fileName);
            case "zip":
                return zipFiles(files);
            default:
                throw new IllegalArgumentException("Unsupported operation: " + operationType);
        }
    }

    /**
     * Uploads the given files to the target directory.
     *
     * @param files     the list of files to upload
     * @param targetDir the target directory
     * @return a message indicating how many files were uploaded
     * @throws IOException if an I/O error occurs
     */
    private static String uploadFiles(List<Path> files, Path targetDir) throws IOException {
        if (files == null || targetDir == null) {
            throw new IllegalArgumentException("Files and target directory must not be null for upload.");
        }

        Files.createDirectories(targetDir);

        int uploadedCount = 0;
        for (Path file : files) {
            if (Files.exists(file) && Files.isRegularFile(file)) {
                Path destination = targetDir.resolve(file.getFileName());
                Files.copy(file, destination, StandardCopyOption.REPLACE_EXISTING);
                uploadedCount++;
            }
        }

        return "Uploaded " + uploadedCount + " file" + (uploadedCount == 1 ? "" : "s") + ".";
    }

    /**
     * Downloads the specified file from the target directory.
     *
     * @param targetDir the directory containing the file
     * @param fileName  the name of the file to download
     * @return the file contents as a byte array
     * @throws IOException if an I/O error occurs
     */
    private static byte[] downloadFile(Path targetDir, String fileName) throws IOException {
        if (targetDir == null || fileName == null) {
            throw new IllegalArgumentException("Target directory and file name must not be null for download.");
        }

        Path filePath = targetDir.resolve(fileName);
        return Files.readAllBytes(filePath);
    }

    /**
     * Creates an in‑memory ZIP archive containing the given files.
     *
     * @param files the list of files to include in the ZIP
     * @return the ZIP archive as a byte array
     * @throws IOException if an I/O error occurs
     */
    private static byte[] zipFiles(List<Path> files) throws IOException {
        if (files == null) {
            throw new IllegalArgumentException("Files list must not be null for zip.");
        }

        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ZipOutputStream zos = new ZipOutputStream(baos)) {

            for (Path file : files) {
                if (Files.exists(file) && Files.isRegularFile(file)) {
                    ZipEntry entry = new ZipEntry(file.getFileName().toString());
                    zos.putNextEntry(entry);
                    Files.copy(file, zos);
                    zos.closeEntry();
                }
            }
            zos.finish();
            return baos.toByteArray();
        }
    }
}

