            if (value != null) {
                // RFC 5987 format: encoding'lang'value
                int firstQuote = value.indexOf('\'');
                int secondQuote = value.indexOf('\'', firstQuote + 1);
                if (firstQuote != -1 && secondQuote != -1 && secondQuote > firstQuote) {
                    String encoding = value.substring(0, firstQuote);
                    // String language = value.substring(firstQuote + 1, secondQuote); // ignored
                    String encoded = value.substring(secondQuote + 1);
                    try {
                        return URLDecoder.decode(encoded, encoding);
                    } catch (Exception e) {
                        // Unsupported encoding or decoding error
                        return null;
                    }
                } else {
                    // Malformed filename* value; fall back to plain extraction
                    return value;
                }
            }
        }

        // Fallback to plain filename
        idx = lower.indexOf("filename=");
        if (idx != -1) {
            return extractParameterValue(contentDisposition, idx + "filename=".length());
        }

        return null;
    }

    /**
     * Extracts the parameter value starting at {@code startIdx} in the header string.
     * Handles quoted, single‑quoted, or unquoted values.
     *
     * @param header   the full header string
     * @param startIdx the index where the value starts (after the '=')
     * @return the extracted value without surrounding quotes, or {@code null}
     *         if extraction fails
     */
    private static String extractParameterValue(String header, int startIdx) {
        int len = header.length();
        // Skip leading whitespace
        while (startIdx < len && Character.isWhitespace(header.charAt(startIdx))) {
            startIdx++;
        }
        if (startIdx >= len) {
            return null;
        }

        char firstChar = header.charAt(startIdx);
        if (firstChar == '\"' || firstChar == '\'') {
            // Quoted value
            int endIdx = header.indexOf(firstChar, startIdx + 1);
            if (endIdx == -1) {
                return null; // malformed
            }
            return header.substring(startIdx + 1, endIdx);
        } else {
            // Unquoted value: read until ';' or whitespace
            int endIdx = startIdx;
            while (endIdx < len) {
                char c = header.charAt(endIdx);
                if (c == ';' || Character.isWhitespace(c)) {
                    break;
                }
                endIdx++;
            }
            return header.substring(startIdx, endIdx);
        }
    }

    /**
     * Returns the file extension of the given filename in lowercase.
     *
     * @param filename the filename to inspect
     * @return the extension without the dot, in lowercase; or an empty string if
     *         the filename is null, empty, has no dot, or ends with a dot.
     */
    public static String getExtension(String filename) {
        if (filename == null || filename.isEmpty()) {
            return "";
        }

        int lastDot = filename.lastIndexOf('.');
        if (lastDot == -1 || lastDot == filename.length() - 1) {
            return "";
        }

        String ext = filename.substring(lastDot + 1);
        return ext.toLowerCase();
    }
}
