import java.util.HashMap;
import java.util.Map;

class FileUploadUtil {

    /**
     * Parses a Content-Disposition header into a map.
     * <p>
     * The first token before any semicolon is stored under the key {@code "type"}.
     * Subsequent tokens are treated as key/value pairs. Keys are converted to
     * lower‑case and values have surrounding quotes (single or double) removed.
     *
     * @param contentDisposition the header string, e.g.
     *        {@code form-data; name="file"; filename="example.txt"}
     * @return a map containing the parsed parts; an empty map if the input is
     *         {@code null} or empty.
     */
    public static Map<String, String> parseContentDisposition(String contentDisposition) {
        Map<String, String> result = new HashMap<>();

        if (contentDisposition == null || contentDisposition.isEmpty()) {
            return result;
        }

        // Split on ';' – this is sufficient for typical headers.
        String[] parts = contentDisposition.split(";");
        for (int i = 0; i < parts.length; i++) {
            String part = parts[i].trim();
            if (part.isEmpty()) {
                continue;
            }

            if (i == 0) {
                // The first part is the type.
                result.put("type", part);
                continue;
            }

            int eqIdx = part.indexOf('=');
            String key;
            String value;

            if (eqIdx == -1) {
                // No value – store empty string.
                key = part.toLowerCase();
                value = "";
            } else {
                key = part.substring(0, eqIdx).trim().toLowerCase();
                value = part.substring(eqIdx + 1).trim();

                // Strip surrounding quotes if present.
                if ((value.startsWith("\"") && value.endsWith("\"")) ||
                    (value.startsWith("'") && value.endsWith("'"))) {
                    value = value.substring(1, value.length() - 1);
                }
            }

            result.put(key, value);
        }

        return result;
    }

